        ["Pick a version and press Install. It goes in {0}"] = "Scegli una versione e premi Installa. Va in {0}",
        ["Update, reinstall or remove"] = "Aggiorna, reinstalla o rimuovi",
        ["OptiScaler files: {0}"] = "File di OptiScaler: {0}",
        ["in {0} file"] = "in {0} file",
        ["in {0} files"] = "in {0} file",
        ["logs {0}"] = "log {0}",
        ["Largest files (updated every few seconds, logs grow while the game runs):"] = "File più grandi (aggiornati ogni pochi secondi, i log crescono mentre il gioco è aperto):",
        ["No builds yet: use Import"] = "Ancora nessuna build: usa Importa",
        ["Offline: can't list versions"] = "Offline: impossibile elencare le versioni",
        ["Asking GitHub for a code…"] = "Richiesta del codice a GitHub…",
        ["Copy code and open GitHub"] = "Copia il codice e apri GitHub",
        ["Forgets the sign-in on this PC. To revoke it on GitHub too: Settings → Applications there."] = "Dimentica l'accesso su questo PC. Per revocarlo anche su GitHub: Settings → Applications lì.",
        ["GITHUB"] = "GITHUB",
        ["GitHub allows 60 requests an hour without sign-in, so version lists can't load until {0:HH:mm}. Sign in to GitHub to lift the limit."] = "GitHub consente 60 richieste l'ora senza accesso, quindi gli elenchi delle versioni non si caricano fino alle {0:HH:mm}. Accedi a GitHub per togliere il limite.",
        ["GitHub limit reached"] = "Limite di GitHub raggiunto",
        ["GitHub refused the sign-in ({0})."] = "GitHub ha rifiutato l'accesso ({0}).",
        ["GitHub sign-in"] = "Accesso a GitHub",
        ["GitHub sign-in is not available in this build."] = "L'accesso a GitHub non è disponibile in questa build.",
        ["Limit reached"] = "Limite raggiunto",
        ["Sign in to GitHub"] = "Accedi a GitHub",
        ["Signed in to GitHub as {0}."] = "Accesso a GitHub come {0}.",
        ["Signed in to GitHub as {0}. Version lists load again."] = "Accesso a GitHub come {0}. Gli elenchi delle versioni si caricano di nuovo.",
        ["The GitHub CLI (gh) is signed in on this PC as {0}: use that account."] = "La GitHub CLI (gh) è collegata su questo PC come {0}: usa quell'account.",
        ["The GitHub CLI (gh) is signed in on this PC: use that account."] = "La GitHub CLI (gh) è collegata su questo PC: usa quell'account.",
        ["The GitHub CLI is not signed in any more."] = "La GitHub CLI non è più collegata.",
        ["The code expired before it was confirmed on GitHub. Try again."] = "Il codice è scaduto prima della conferma su GitHub. Riprova.",
        ["The limit is used up until {0:HH:mm}."] = "Il limite è esaurito fino alle {0:HH:mm}.",
        ["The sign-in was cancelled on GitHub."] = "L'accesso è stato annullato su GitHub.",
        ["Type this code on GitHub's page and confirm. Hybrid Launcher asks for no permissions: it can only read what anyone can see, to list versions."] = "Inserisci questo codice nella pagina di GitHub e conferma. Hybrid Launcher non chiede permessi: può leggere solo ciò che chiunque vede, per elencare le versioni.",
        ["Use GitHub CLI"] = "Usa GitHub CLI",
        ["Versions of OptiScaler, its forks, ReShade and mods are read from GitHub, which allows 60 requests an hour without sign-in: past that, lists show as offline. Signing in raises the limit to 5000."] = "Le versioni di OptiScaler, dei suoi fork, di ReShade e delle mod si leggono da GitHub, che consente 60 richieste l'ora senza accesso: oltre, gli elenchi risultano offline. Accedendo il limite sale a 5000.",
        ["Waiting for you to confirm on {0}…"] = "In attesa della tua conferma su {0}…",
        ["from the GitHub CLI"] = "dalla GitHub CLI",
        ["up to 5000 version lists an hour."] = "fino a 5000 elenchi di versioni l'ora.",
        ["GitHub limit reached: versions after {0:HH:mm}"] = "Limite di GitHub raggiunto: versioni dopo le {0:HH:mm}",
        ["GitHub's limit of requests without sign-in is used up until {0:HH:mm}, and these releases are not cached yet."] = "Il limite di richieste di GitHub senza accesso è esaurito fino alle {0:HH:mm} e queste versioni non sono ancora in cache.",
        ["No releases found"] = "Nessuna versione trovata",
        ["Latest  ({0})"] = "Più recente  ({0})",
        ["Tested releases, published less often than nightly builds."] = "Versioni collaudate, pubblicate meno spesso delle nightly.",
        ["The newest features and fixes, built every day. If a game misbehaves, go back to Stable."] = "Le ultime novità e correzioni, compilate ogni giorno. Se un gioco dà problemi, torna a Stable.",
        ["No {0} in this build: taken from the latest nightly at install."] = "Questa build non ha {0}: viene preso dall'ultima nightly durante l'installazione.",
        ["Builds you imported, e.g. test builds shared on the OptiScaler Discord. Import a folder or a .zip / .7z / .rar."] = "Build che hai importato, es. build di prova condivise sul Discord di OptiScaler. Importa una cartella o un .zip / .7z / .rar.",
        ["Can't read the custom builds folder"] = "Impossibile leggere la cartella delle build personalizzate",
        ["Importing…"] = "Importazione…",
        ["Imported \"{0}\": OptiScaler {1}."] = "Importata \"{0}\": OptiScaler {1}.",
        ["Could not import the build"] = "Impossibile importare la build",
        ["Deletes this build from the custom builds folder:\n{0}\n\nGames where it is installed keep working and can still be uninstalled."] = "Elimina questa build dalla cartella delle build personalizzate:\n{0}\n\nI giochi in cui è installata continuano a funzionare e si possono ancora disinstallare.",
        ["Could not delete the build"] = "Impossibile eliminare la build",
        ["The setup asks which GPU you use. Detected: {0}."] = "L'installazione chiede quale GPU usi. Rilevata: {0}.",
        ["spoofing on"] = "spoofing attivo",
        ["spoofing off"] = "spoofing disattivo",
        ["OptiPatcher if supported"] = "OptiPatcher se supportato",
        ["OptiPatcher supports this game"] = "OptiPatcher supporta questo gioco",
        ["Spoofing is off because OptiPatcher supports this game: it opens the upscaler options without spoofing."] = "Lo spoofing è disattivato perché OptiPatcher supporta questo gioco: apre le opzioni dell'upscaler senza spoofing.",
        ["no OptiPatcher"] = "senza OptiPatcher",
        ["✔ This game is supported: OptiPatcher unlocks DLSS / DLSS-FG inputs without spoofing. Asked only on AMD / Intel."] = "✔ Questo gioco è supportato: OptiPatcher sblocca gli input DLSS / DLSS-FG senza spoofing. Chiesto solo su AMD / Intel.",
        ["This game is not in OptiPatcher's list, so the setup will skip it. Asked only on AMD / Intel."] = "Questo gioco non è nella lista di OptiPatcher, quindi l'installazione lo salterà. Chiesto solo su AMD / Intel.",
        ["Unlocks DLSS / DLSS-FG inputs without spoofing in supported games (could not check the list now)."] = "Sblocca gli input DLSS / DLSS-FG senza spoofing nei giochi supportati (ora non è stato possibile controllare la lista).",
        ["Import a build first: Custom build → Import → from a folder or an archive."] = "Importa prima una build: Build personalizzata → Importa → da una cartella o un archivio.",
        ["No version available"] = "Nessuna versione disponibile",
        ["Hybrid Launcher could not list OptiScaler releases. Check the connection and try again."] = "Hybrid Launcher non è riuscito a elencare le versioni di OptiScaler. Controlla la connessione e riprova.",
        ["No game exe"] = "Nessun exe del gioco",
        ["Another file has that name"] = "C'è già un file con quel nome",
        ["OptiScaler would replace it, so that mod would stop working while OptiScaler is installed. Hybrid Launcher keeps a backup and puts it back when you uninstall."] = "OptiScaler lo sostituirebbe, quindi quella mod smetterebbe di funzionare finché OptiScaler è installato. Hybrid Launcher ne tiene una copia e la rimette quando disinstalli.",
        ["Tip: pick a different OptiScaler file name in Setup options (e.g. winmm.dll) to keep both."] = "Suggerimento: scegli un altro nome per il file di OptiScaler nelle Opzioni di installazione (es. winmm.dll) per tenerli entrambi.",
        ["Replace (keep a backup)"] = "Sostituisci (con copia di sicurezza)",
        ["OptiScaler {0} installed in {1} as {2}."] = "OptiScaler {0} installato in {1} come {2}.",
        ["Install cancelled. The game folder was left as it was."] = "Installazione annullata. La cartella del gioco è rimasta com'era.",
        ["setup_windows.bat output"] = "output di setup_windows.bat",
        ["Install failed"] = "Installazione non riuscita",
        ["Uninstall OptiScaler?"] = "Disinstallare OptiScaler?",
        ["Removes the {0} files Hybrid Launcher installed in\n{1}\nand restores the {2} original file(s) it backed up. Your setup answers and ini choices stay saved."] = "Rimuove i {0} file installati da Hybrid Launcher in\n{1}\ne ripristina i {2} file originali salvati. Le tue risposte di installazione e le scelte dell'ini restano salvate.",
        ["OptiScaler removed."] = "OptiScaler rimosso.",
        ["OptiScaler removed and the original files restored."] = "OptiScaler rimosso e file originali ripristinati.",
        ["Uninstall failed"] = "Disinstallazione non riuscita",
        ["the custom build \"{0}\""] = "la build personalizzata \"{0}\"",
        ["nightly {0}"] = "la nightly {0}",
        ["Installs {0}. Install runs OptiScaler's own setup script silently with your setup options; Standard .bat install opens it so you answer it yourself. Every file it replaces is backed up, and uninstall puts the folder back as it was."] = "Installa {0}. Installa esegue in silenzio lo script di OptiScaler con le tue opzioni; Installazione .bat standard lo apre per farti rispondere. Ogni file sostituito viene salvato e la disinstallazione rimette la cartella com'era.",
        ["Reinstall"] = "Reinstalla",
        ["{0} is installed. Reinstalling keeps your settings."] = "{0} è installato. Reinstallando tieni le tue impostazioni.",
        ["Update"] = "Aggiorna",
        ["Replaces {0} with {1}. Your settings are applied again."] = "Sostituisce {0} con {1}. Le tue impostazioni vengono applicate di nuovo.",
        ["Switch to {0}"] = "Passa a {0}",
