        ["Install OptiScaler to change its settings here. Changes are written to OptiScaler.ini and re-applied after every reinstall or update."] = "Installa OptiScaler per cambiarne qui le impostazioni. Le modifiche vengono scritte in OptiScaler.ini e riapplicate dopo ogni reinstallazione o aggiornamento.",
