        ["Restore the default settings?"] = "Ripristinare le impostazioni predefinite?",
        ["Every setting of this game's OptiScaler.ini goes back to how it was right after the install. The choices Hybrid Launcher applies again after a reinstall are cleared; saved profiles stay."] = "Ogni impostazione dell'OptiScaler.ini di questo gioco torna a com'era subito dopo l'installazione. Le scelte che Hybrid Launcher riapplica dopo una reinstallazione vengono cancellate; i profili salvati restano.",
        ["This install was made before Hybrid Launcher kept a copy of the original OptiScaler.ini, so every setting goes back to Auto (OptiScaler's own default). The choices Hybrid Launcher applies again after a reinstall are cleared; saved profiles stay."] = "Questa installazione è stata fatta prima che Hybrid Launcher tenesse una copia dell'OptiScaler.ini originale, quindi ogni impostazione torna su Auto (il predefinito di OptiScaler). Le scelte che Hybrid Launcher riapplica dopo una reinstallazione vengono cancellate; i profili salvati restano.",
