        // ---- ReShade tab ----
        ["Standard"] = "Standard",
        ["standard"] = "standard",
        ["Full add-on support"] = "Supporto completo agli add-on",
        ["full add-on support"] = "supporto completo agli add-on",
        ["Download and run the installer"] = "Scarica e avvia l'installer",
        ["Uninstall with ReShade's setup"] = "Disinstalla con il setup di ReShade",
        ["Hybrid Launcher downloads the official installer from reshade.me and starts it with this game's exe chosen. Pick the graphics API there and, if you like, some shaders. ReShade's setup also updates and uninstalls it."] = "Hybrid Launcher scarica l'installer ufficiale da reshade.me e lo avvia con l'exe di questo gioco già scelto. Lì scegli l'API grafica e, se vuoi, qualche shader. Il setup di ReShade serve anche per aggiornarlo e disinstallarlo.",
        ["Install ReShade in the game"] = "Installa ReShade nel gioco",
        ["Use it together with OptiScaler"] = "Usalo insieme a OptiScaler",
        ["Files"] = "File",
        ["Saved installers"] = "Installer salvati",
        ["Kept on this PC, ready to run again"] = "Tenuti su questo PC, pronti da riavviare",
        ["ReShade links"] = "Link di ReShade",
        ["reshade.me (downloads, forum)"] = "reshade.me (download, forum)",
        ["ReShade on GitHub"] = "ReShade su GitHub",
        ["Shader list"] = "Elenco degli shader",
        ["Needed by RenoDX and other add-ons. Use it only in single-player games: online games with anti-cheat may block or ban add-on builds."] = "Serve a RenoDX e ad altri add-on. Usalo solo nei giochi single player: i giochi online con anti-cheat possono bloccare o bannare le build con add-on.",
        ["The usual build, fine for shaders and presets. RenoDX needs the full add-on support edition."] = "La build normale, va bene per shader e preset. RenoDX richiede l'edizione con supporto completo agli add-on.",
        ["ReShade is not installed in this game"] = "ReShade non è installato in questo gioco",
        ["ReShade {0} is installed"] = "ReShade {0} è installato",
        ["Run the installer below. It goes next to the game exe: {0}"] = "Avvia l'installer qui sotto. Va accanto all'exe del gioco: {0}",
        ["As {0}, loaded by OptiScaler"] = "Come {0}, caricato da OptiScaler",
        ["once LoadReshade is on (see below)."] = "quando LoadReshade è attivo (vedi sotto).",
        ["As {0}"] = "Come {0}",
        ["last installer: {0}"] = "ultimo installer: {0}",
        ["OptiScaler is not installed in this game, so ReShade loads on its own: nothing to do here. With OptiScaler, both want to be the game's dxgi.dll; this makes OptiScaler load ReShade instead."] = "OptiScaler non è installato in questo gioco, quindi ReShade si carica da solo: qui non c'è niente da fare. Con OptiScaler, entrambi vorrebbero essere la dxgi.dll del gioco; questo fa caricare ReShade da OptiScaler.",
        ["OptiScaler loads ReShade (ReShade64.dll, LoadReshade = true)"] = "OptiScaler carica ReShade (ReShade64.dll, LoadReshade = true)",
        ["OptiScaler does not load ReShade yet"] = "OptiScaler non carica ancora ReShade",
        ["Both work together. Press Home in game for ReShade, Insert for OptiScaler's menu."] = "Funzionano insieme. In gioco premi Home per ReShade, Ins per il menu di OptiScaler.",
        ["OptiScaler and ReShade can't both be dxgi.dll. Hybrid Launcher renames ReShade's DLL to ReShade64.dll and turns on LoadReshade in OptiScaler.ini (kept after OptiScaler updates)."] = "OptiScaler e ReShade non possono essere entrambi dxgi.dll. Hybrid Launcher rinomina la dll di ReShade in ReShade64.dll e attiva LoadReshade in OptiScaler.ini (mantenuto dopo gli aggiornamenti di OptiScaler).",
        ["ReShade replaced OptiScaler's DLL"] = "ReShade ha sostituito la dll di OptiScaler",
        ["The ReShade installer wrote over OptiScaler's file. Load ReShade through OptiScaler, then reinstall OptiScaler (Hybrid Launcher offers it)."] = "L'installer di ReShade ha sovrascritto il file di OptiScaler. Carica ReShade tramite OptiScaler, poi reinstalla OptiScaler (te lo propone Hybrid Launcher).",
        ["Load ReShade through OptiScaler"] = "Carica ReShade tramite OptiScaler",
        ["Stop loading it through OptiScaler"] = "Non caricarlo più tramite OptiScaler",
        ["Open ReShade.ini"] = "Apri ReShade.ini",
        ["Shaders folder"] = "Cartella degli shader",
        ["Game folder"] = "Cartella del gioco",
        ["None yet: the first installer you run is kept here."] = "Ancora nessuno: il primo installer che avvii viene tenuto qui.",
        ["Run this installer for this game"] = "Avvia questo installer per questo gioco",
        ["Delete this installer from this PC"] = "Elimina questo installer dal PC",
        ["Delete ReShade {0}?"] = "Eliminare ReShade {0}?",
        ["Removes the saved installer:\n{0}\n\nReShade stays installed in your games."] = "Rimuove l'installer salvato:\n{0}\n\nReShade resta installato nei tuoi giochi.",
        ["ReShade's setup is open. When it finishes, come back here and press Load ReShade through OptiScaler."] = "Il setup di ReShade è aperto. Quando finisce, torna qui e premi Carica ReShade tramite OptiScaler.",
        ["ReShade's setup is open. When it finishes, come back here."] = "Il setup di ReShade è aperto. Quando finisce, torna qui.",
        ["In ReShade's setup, pick this game, then Uninstall."] = "Nel setup di ReShade scegli questo gioco, poi Disinstalla.",
        ["Could not get ReShade"] = "Impossibile scaricare ReShade",
        ["Reinstall OptiScaler?"] = "Reinstallare OptiScaler?",
        ["ReShade's installer had written over OptiScaler's DLL. Reinstall OptiScaler now, with your settings? ReShade stays as ReShade64.dll."] = "L'installer di ReShade aveva sovrascritto la dll di OptiScaler. Reinstallare ora OptiScaler con le tue impostazioni? ReShade resta come ReShade64.dll.",
        ["Could not set it up"] = "Impossibile configurarlo",
        ["Could not undo it"] = "Impossibile annullarlo",
        ["OptiScaler is not installed in this folder (no OptiScaler.ini). Install OptiScaler first."] = "OptiScaler non è installato in questa cartella (manca OptiScaler.ini). Installa prima OptiScaler.",
        ["ReShade {0} is already {1}."] = "ReShade {0} è già {1}.",
        ["Renamed ReShade's {0} to {1}."] = "Rinominato {0} di ReShade in {1}.",
        ["ReShade had been replaced when OptiScaler was installed: Hybrid Launcher put it back as {0}."] = "ReShade era stato sostituito all'installazione di OptiScaler: Hybrid Launcher l'ha rimesso come {0}.",
        ["No ReShade dll in this folder. Run the ReShade installer for this game first, then press the button again."] = "Nessuna dll di ReShade in questa cartella. Avvia prima l'installer di ReShade per questo gioco, poi premi di nuovo il pulsante.",
        ["This OptiScaler version has no LoadReshade setting in OptiScaler.ini."] = "Questa versione di OptiScaler non ha l'impostazione LoadReshade in OptiScaler.ini.",
        ["OptiScaler no longer loads ReShade."] = "OptiScaler non carica più ReShade.",

        // ---- RenoDX tab ----
        ["Search every RenoDX mod"] = "Cerca tra tutte le mod RenoDX",
        ["RenoDX: HDR for this game"] = "RenoDX: HDR per questo gioco",
        ["RenoDX mod list"] = "Lista delle mod RenoDX",
        ["Rewritten shaders for real HDR, as a ReShade add-on"] = "Shader riscritti per un vero HDR, come add-on di ReShade",
        ["From the RenoDX list, matched by name and engine"] = "Dalla lista RenoDX, trovate per nome e motore",
        ["Picked from the list"] = "Scelta dalla lista",
        ["In the game folder"] = "Nella cartella del gioco",
        [".addon64 / .addon32 files next to the exe"] = "File .addon64 / .addon32 accanto all'exe",
        ["Install a downloaded file…"] = "Installa un file scaricato…",
        ["Tips"] = "Consigli",
        ["• Turn on HDR in Windows. Turn off Windows Auto HDR and RTX HDR for this game, or the picture is tone mapped twice and looks washed out."] = "• Attiva l'HDR in Windows. Disattiva Auto HDR di Windows e RTX HDR per questo gioco, altrimenti l'immagine subisce due tone mapping e appare slavata.",
        ["• In game, Home opens ReShade: RenoDX's settings are in its Add-ons tab."] = "• In gioco, Home apre ReShade: le impostazioni di RenoDX sono nella sua scheda Add-ons.",
        ["• Snapshot builds are newer than the Nexus Mods ones but may be less stable. Some mods need extra steps: read their page."] = "• Le build snapshot sono più recenti di quelle su Nexus Mods ma possono essere meno stabili. Alcune mod richiedono passaggi in più: leggi la loro pagina.",
        ["Could not load the RenoDX list (offline?). The mod list link above opens it in the browser."] = "Impossibile caricare la lista RenoDX (offline?). Il link della lista qui sopra la apre nel browser.",
        ["No RenoDX mod is listed for {0} yet."] = "Non c'è ancora una mod RenoDX per {0}.",
        ["No RenoDX mod is listed for {0} yet, and no generic one for its engine ({1})."] = "Non c'è ancora una mod RenoDX per {0}, né una generica per il suo motore ({1}).",
        ["Search the list above if it goes by another name."] = "Cerca nella lista qui sopra se ha un altro nome.",
        ["Working"] = "Funzionante",
        ["In progress"] = "In corso",
        ["by {0}"] = "di {0}",
        ["Install snapshot ({0}-bit)"] = "Installa lo snapshot ({0} bit)",
        ["Nexus Mods page"] = "Pagina su Nexus Mods",
        ["Download it on Nexus Mods (Manual download). Hybrid Launcher watches your Downloads folder and offers to install the file."] = "Scaricala da Nexus Mods (Manual download). Hybrid Launcher controlla la cartella Download e ti propone di installare il file.",
        ["ReShade with full add-on support is not installed"] = "ReShade con supporto completo agli add-on non è installato",
        ["(full add-on support)"] = "(supporto completo agli add-on)",
        ["(standard: RenoDX needs full add-on support)"] = "(standard: RenoDX richiede il supporto completo agli add-on)",
        ["Get it in the ReShade tab: pick \"Full add-on support\" and run the installer."] = "Prendilo nella scheda ReShade: scegli \"Supporto completo agli add-on\" e avvia l'installer.",
        ["Open the ReShade tab"] = "Apri la scheda ReShade",
        ["Open the ReShade section"] = "Apri la sezione ReShade",
        ["OptiScaler loads ReShade"] = "OptiScaler carica ReShade",
        ["OptiScaler is installed: ReShade must load through it"] = "OptiScaler è installato: ReShade deve caricarsi tramite lui",
        ["One click in the ReShade tab: ReShade becomes ReShade64.dll and OptiScaler loads it. RenoDX then works with OptiScaler's upscaling and frame generation."] = "Un clic nella scheda ReShade: ReShade diventa ReShade64.dll e lo carica OptiScaler. RenoDX poi funziona con l'upscaling e la frame generation di OptiScaler.",
        ["No OptiScaler here: ReShade loads on its own"] = "Qui non c'è OptiScaler: ReShade si carica da solo",
