        ["{0} in total. Deleting one never breaks a game: installs don't depend on it."] = "{0} in totale. Eliminarne una non rompe mai un gioco: le installazioni non dipendono da lei.",
        ["Could not read the saved versions."] = "Impossibile leggere le versioni salvate.",
        ["installed in {0}"] = "installata in {0}",
