        // ---- install (core) ----
        ["Removing the previous OptiScaler install"] = "Rimozione dell'installazione precedente di OptiScaler",
        ["Downloading {0}"] = "Download di {0}",
        ["Extracting"] = "Estrazione",
        ["The custom build \"{0}\" is no longer in the custom builds folder."] = "La build personalizzata \"{0}\" non è più nella cartella delle build personalizzate.",
        ["Preparing custom build {0}"] = "Preparazione della build personalizzata {0}",
        ["The custom build \"{0}\" has no OptiScaler dll."] = "La build personalizzata \"{0}\" non contiene la dll di OptiScaler.",
        ["Preparing custom build"] = "Preparazione della build personalizzata",
        ["{0} is OptiScaler: renamed to OptiScaler.dll for the setup script."] = "{0} è OptiScaler: rinominato in OptiScaler.dll per lo script di installazione.",
        ["This build has no {0} and Hybrid Launcher could not get them from the latest nightly: {1}"] = "Questa build non ha {0} e Hybrid Launcher non è riuscito a prenderli dall'ultima nightly: {1}",
        ["This build has no {0} and no nightly release was found to take them from."] = "Questa build non ha {0} e non è stata trovata una nightly da cui prenderli.",
        ["This build has no {0}: taking it from nightly {1}"] = "Questa build non ha {0}: lo prendo dalla nightly {1}",
        ["Downloading nightly {0} for its {1}"] = "Download della nightly {0} per {1}",
        ["Nightly {0} has no {1} to borrow."] = "La nightly {0} non ha {1} da prendere.",
        ["This release does not contain OptiScaler.dll and setup_windows.bat; it cannot be installed with the setup script."] = "Questa versione non contiene OptiScaler.dll e setup_windows.bat: non si può installare con lo script di installazione.",
        ["Backing up existing files"] = "Copia di sicurezza dei file esistenti",
        ["Copying OptiScaler files"] = "Copia dei file di OptiScaler",
        ["Waiting for setup_windows.bat: answer it in its window, then close it"] = "In attesa di setup_windows.bat: rispondi nella sua finestra, poi chiudila",
        ["setup_windows.bat closed without installing OptiScaler (OptiScaler.dll was not renamed). The folder was put back as it was."] = "setup_windows.bat si è chiuso senza installare OptiScaler (OptiScaler.dll non è stato rinominato). La cartella è stata rimessa com'era.",
        ["Setup finished"] = "Installazione completata",
        ["OptiScaler was installed as {0}."] = "OptiScaler è stato installato come {0}.",
        ["Running OptiScaler setup"] = "Esecuzione dell'installazione di OptiScaler",
        ["The setup script failed."] = "Lo script di installazione non è riuscito.",
        ["The setup script did not rename OptiScaler.dll to {0}. The folder may be read-only."] = "Lo script di installazione non ha rinominato OptiScaler.dll in {0}. La cartella potrebbe essere di sola lettura.",
        ["Applying saved settings"] = "Applicazione delle impostazioni salvate",
        ["OptiScaler {0} installed as {1}"] = "OptiScaler {0} installato come {1}",
        ["Install failed, restoring the folder"] = "Installazione non riuscita, ripristino della cartella",
        ["Windows could not open setup_windows.bat."] = "Windows non è riuscito ad aprire setup_windows.bat.",
        ["{0} no longer exists; nothing to remove."] = "{0} non esiste più: niente da rimuovere.",
        ["Kept {0}: it was replaced by something that is not OptiScaler after install."] = "Tenuto {0}: dopo l'installazione è stato sostituito da qualcosa che non è OptiScaler.",
        ["Could not delete {0} (in use?)"] = "Impossibile eliminare {0} (in uso?)",
        ["The game folder does not exist: {0}"] = "La cartella del gioco non esiste: {0}",
        ["Hybrid Launcher cannot write to {0}. Restart Hybrid Launcher as administrator, or move the game to a folder you own."] = "Hybrid Launcher non può scrivere in {0}. Riavvia Hybrid Launcher come amministratore, o sposta il gioco in una cartella tua.",
        ["Could not reach GitHub to list OptiScaler releases (and nothing is cached yet)."] = "Impossibile raggiungere GitHub per elencare le versioni di OptiScaler (e non c'è ancora niente in cache).",
        ["The download of {0} is corrupted (size or SHA-256 mismatch). Try again."] = "Il download di {0} è danneggiato (dimensione o SHA-256 non corrispondono). Riprova.",
        ["The setup script took too long."] = "Lo script di installazione ha impiegato troppo tempo.",
        ["The setup script stopped responding."] = "Lo script di installazione ha smesso di rispondere.",
        ["The setup script asked a question this version of Hybrid Launcher does not know:"] = "Lo script di installazione ha fatto una domanda che questa versione di Hybrid Launcher non conosce:",
        ["The setup script kept asking the same questions (rejected answer?)."] = "Lo script di installazione continuava a fare le stesse domande (risposta rifiutata?).",
        ["{0} does not contain an OptiScaler dll (OptiScaler.dll, or a dll whose file details say OptiScaler)."] = "{0} non contiene una dll di OptiScaler (OptiScaler.dll, o una dll i cui dettagli dicono OptiScaler).",
        ["Cannot extract the archive: tar.exe is missing and the built-in extractor failed."] = "Impossibile estrarre l'archivio: tar.exe manca e l'estrattore interno non è riuscito.",

