        ["Storage"] = "Archiviazione",
        ["{0} free of {1}"] = "{0} liberi su {1}",
        ["No fixed drive found."] = "Nessun disco fisso trovato.",
        ["HDR on"] = "HDR attivo",
        ["HDR off (supported)"] = "HDR disattivo (supportato)",
        ["Main display"] = "Schermo principale",
        ["Windows did not give this display's name: its settings can only be changed in Settings → Display."] = "Windows non ha dato il nome di questo schermo: le sue impostazioni si cambiano solo da Impostazioni → Schermo.",
        ["Resolution"] = "Risoluzione",
        ["Refresh rate"] = "Frequenza di aggiornamento",
        ["The highest rate the display offers is usually the right one for games."] = "Per i giochi di solito la frequenza più alta offerta dallo schermo è quella giusta.",
        ["Could not change HDR"] = "Impossibile cambiare l'HDR",
        ["Brighter highlights and wider colours in HDR games. Windows' own switch (Settings → Display → HDR)."] = "Luci più brillanti e colori più ampi nei giochi HDR. È l'interruttore di Windows (Impostazioni → Schermo → HDR).",
        ["This display does not support HDR."] = "Questo schermo non supporta l'HDR.",
