        ["Could not change the colour profile"] = "Impossibile cambiare il profilo colore",
        ["None (Windows default)"] = "Nessuno (predefinito di Windows)",
        ["Add more profiles in Windows' colour settings, then pick them here."] = "Aggiungi altri profili nelle impostazioni colore di Windows, poi sceglili qui.",
        ["Display settings"] = "Impostazioni schermo",
        ["Advanced display"] = "Schermo avanzate",
        ["Brightness"] = "Luminosità",
        ["Windows does not let apps change this screen's brightness."] = "Windows non permette alle app di cambiare la luminosità di questo schermo.",
        ["This monitor does not take brightness from Windows. Turn on DDC/CI in the monitor's own menu, then Refresh."] = "Questo monitor non accetta la luminosità da Windows. Attiva DDC/CI nel menu del monitor, poi premi Aggiorna.",
        ["Could not change the brightness"] = "Impossibile cambiare la luminosità",
        ["The display did not accept the new value."] = "Lo schermo non ha accettato il nuovo valore.",
        ["The built-in screen."] = "Lo schermo integrato.",
        ["Set over DDC/CI, like the monitor's own buttons."] = "Impostata via DDC/CI, come i tasti del monitor.",
        ["Could not change the display mode"] = "Impossibile cambiare la modalità dello schermo",
        ["{0} now runs at {1} × {2}, {3} Hz. Keep it? The previous mode comes back in {4} s."] = "{0} ora è a {1} × {2}, {3} Hz. Tenere? La modalità precedente torna tra {4} s.",
        ["Keep these display settings?"] = "Tenere queste impostazioni dello schermo?",
        ["Keep"] = "Tieni",
        ["Go back"] = "Torna indietro",
        ["Could not put the previous mode back"] = "Impossibile rimettere la modalità precedente",
        ["Windows switches for games"] = "Interruttori di Windows per i giochi",
        ["The same settings as in Windows' Settings app"] = "Le stesse impostazioni dell'app Impostazioni di Windows",
        ["Hardware-accelerated GPU scheduling"] = "Pianificazione GPU con accelerazione hardware",
        ["Not offered by this graphics card or driver."] = "Non disponibile con questa scheda video o driver.",
        ["Needed by DLSS Frame Generation, recommended for any frame generation. Windows asks for administrator rights; it applies after a restart."] = "Serve alla DLSS Frame Generation, consigliata per qualsiasi frame generation. Windows chiede i diritti di amministratore; si applica dopo un riavvio.",
        ["Saved. Restart Windows to apply the GPU scheduling change."] = "Salvato. Riavvia Windows per applicare la modifica alla pianificazione GPU.",
        ["Turns DirectX 11 / 12 games without HDR into HDR, on displays with HDR on. Turn it off for games with their own HDR or RenoDX."] = "Trasforma in HDR i giochi DirectX 11 / 12 senza HDR, sugli schermi con l'HDR attivo. Disattivalo per i giochi con un HDR proprio o con RenoDX.",
        ["Needs a display with HDR support."] = "Serve uno schermo che supporti l'HDR.",
        ["Night light"] = "Luce notturna",
        ["Turn it on once in Windows' Settings; then it can be switched from here."] = "Attivala una volta dalle Impostazioni di Windows; poi si può cambiare da qui.",
        ["Warmer colours to ease the eyes at night. Turn it off for colour-accurate games and HDR."] = "Colori più caldi per riposare gli occhi di sera. Disattivala per giochi con colori fedeli e per l'HDR.",
        ["Game Mode"] = "Modalità gioco",
        ["Windows gives the game priority while it runs."] = "Windows dà la priorità al gioco mentre è aperto.",
        ["Optimizations for windowed games"] = "Ottimizzazioni per i giochi in finestra",
        ["Lower latency and VRR / Auto HDR for DX10 and DX11 games running windowed or borderless."] = "Latenza più bassa e VRR / Auto HDR per i giochi DX10 e DX11 in finestra o senza bordi.",
        ["Graphics settings"] = "Impostazioni grafica",
        ["HDR settings"] = "Impostazioni HDR",
        ["Windows could not read this display's current mode."] = "Windows non è riuscito a leggere la modalità attuale di questo schermo.",
        ["Windows refused this mode (code {0})."] = "Windows ha rifiutato questa modalità (codice {0}).",
        ["Windows needs a restart to use this mode."] = "Windows deve riavviarsi per usare questa modalità.",
        ["Windows did not change HDR (code {0})."] = "Windows non ha cambiato l'HDR (codice {0}).",
        ["Windows did not change the colour profile (code 0x{0:X8})."] = "Windows non ha cambiato il profilo colore (codice 0x{0:X8}).",
        ["DLSS 4 with Multi Frame Generation, plus FSR and XeSS"] = "DLSS 4 con Multi Frame Generation, più FSR e XeSS",
        ["DLSS with DLSS Frame Generation, plus FSR and XeSS"] = "DLSS con DLSS Frame Generation, più FSR e XeSS",
        ["DLSS (no DLSS-FG: use FSR or XeSS frame generation through OptiScaler), plus FSR and XeSS"] = "DLSS (niente DLSS-FG: usa la frame generation FSR o XeSS tramite OptiScaler), più FSR e XeSS",
        ["No DLSS on this card: FSR 3.1 and XeSS (DP4a) work, frame generation through FSR"] = "Niente DLSS su questa scheda: funzionano FSR 3.1 e XeSS (DP4a), frame generation tramite FSR",
        ["FSR Redstone (RDNA 4): FSR 4 upscaling, ML frame generation and ray regeneration, plus XeSS. DLSS inputs need spoofing"] = "FSR Redstone (RDNA 4): upscaling FSR 4, frame generation ML e ray regeneration, più XeSS. Gli input DLSS richiedono lo spoofing",
        ["FSR 3.1 upscaling and frame generation, XeSS; FSR 4 only through OptiScaler's unofficial path (no Redstone). DLSS inputs need spoofing"] = "Upscaling e frame generation FSR 3.1, XeSS; FSR 4 solo con il metodo non ufficiale di OptiScaler (niente Redstone). Gli input DLSS richiedono lo spoofing",
        ["FSR 3.1 and XeSS (DP4a). DLSS inputs need spoofing"] = "FSR 3.1 e XeSS (DP4a). Gli input DLSS richiedono lo spoofing",
        ["XeSS with XMX acceleration, XeSS frame generation, FSR 3.1"] = "XeSS con accelerazione XMX, frame generation XeSS, FSR 3.1",
        ["XeSS (DP4a) and FSR 3.1"] = "XeSS (DP4a) e FSR 3.1",
        ["FSR 3.1 and XeSS"] = "FSR 3.1 e XeSS",

        // ---- settings page ----
        ["Appearance"] = "Aspetto",
        ["Features"] = "Funzionalità",
        ["About"] = "Informazioni",
        ["Language"] = "Lingua",
        ["Automatic (Windows)"] = "Automatica (Windows)",
        ["Automatic follows the Windows display language. Hybrid Launcher restarts to apply a new one."] = "Automatica segue la lingua di Windows. Hybrid Launcher si riavvia per applicarne una nuova.",
        ["Restart Hybrid Launcher to use the new language."] = "Riavvia Hybrid Launcher per usare la nuova lingua.",
        ["Restart now"] = "Riavvia ora",
        ["Look"] = "Aspetto",
        ["Theme"] = "Tema",
        ["Follow Windows, or force light or dark."] = "Segui Windows, o forza chiaro o scuro.",
        ["Light"] = "Chiaro",
        ["Dark"] = "Scuro",
        ["{0} is always dark. Pick another colour theme to use light or dark again."] = "{0} è sempre scuro. Scegli un altro tema colori per usare di nuovo chiaro o scuro.",
        ["Colour theme"] = "Tema colori",
        ["Accent colour and a soft tint behind the window. Works with light and dark."] = "Colore d'accento e una leggera tinta dietro la finestra. Funziona con chiaro e scuro.",
        ["Material colours"] = "Colori material",
        ["Shading"] = "Ombreggiatura",
        ["On: cards and rows lit from above, a glow under the open tab, and a sheen on the launch bar. Off: flat surfaces. Library covers always have their shadow and light."] = "Attiva: schede e righe illuminate dall'alto, un bagliore sotto la scheda aperta, e un riflesso sulla barra di avvio. Disattiva: superfici piatte. Le copertine della libreria hanno sempre ombra e luce.",
        ["On: cards, outlines and the window take a trace of the colour theme (with Windows accent, of your Windows colour). Off: neutral grey surfaces like before, only buttons and highlights in the accent colour."] = "Attivo: schede, contorni e finestra prendono una traccia del tema colori (con Accento di Windows, del colore di Windows). Disattivo: superfici grigio neutro come prima, solo pulsanti ed evidenziazioni nel colore d'accento.",
        ["My colours"] = "I miei colori",
        ["Pick any accent, the glow behind the window and, if you like, your own dark background. Picking a colour switches the colour theme to My colours."] = "Scegli qualsiasi accento, il bagliore dietro la finestra e, se vuoi, il tuo sfondo scuro. Scegliere un colore passa il tema colori a I miei colori.",
        ["Accent"] = "Accento",
        ["Accent: buttons, selections, highlights"] = "Accento: pulsanti, selezioni, evidenziazioni",
        ["Glow"] = "Bagliore",
        ["Glow: the soft colour wash behind the window"] = "Bagliore: la leggera tinta dietro la finestra",
        ["Background"] = "Sfondo",
        ["Background: your own dark backdrop (always dark), used while the switch is on"] = "Sfondo: il tuo sfondo scuro (sempre scuro), usato mentre l'interruttore è attivo",
        ["Own background"] = "Sfondo personale",
        ["Games view"] = "Vista dei giochi",
        ["A list by store in the side pane, or a grid of covers in the library. Pinned games stay on top in both. Also switchable under the search box."] = "Una lista per store nel pannello laterale, o una griglia di copertine nella libreria. I giochi fissati restano in alto in entrambe. Si cambia anche sotto la casella di ricerca.",
        ["List"] = "Lista",
        ["Grid"] = "Griglia",
        ["Game page tabs"] = "Schede della pagina di gioco",
        ["Tabs shown on every game page"] = "Schede mostrate in ogni pagina di gioco",
        ["Turn a tab off to hide it everywhere. To hide one for a single game, right-click it on that game's page or use the gear at the end of its tabs; drag the tabs there to reorder them."] = "Disattiva una scheda per nasconderla ovunque. Per nasconderla in un solo gioco, tasto destro sulla scheda nella sua pagina o usa l'ingranaggio in fondo alle schede; lì trascina le schede per riordinarle.",
        ["Default order, show all"] = "Ordine predefinito, mostra tutte",
        ["Shown"] = "Mostrata",
        ["Hidden"] = "Nascosta",
        ["Every tab is back, in the default order, on every game."] = "Tutte le schede sono tornate, nell'ordine predefinito, in ogni gioco.",
        ["The HowLongToBeat card in the overview's side column (main story, extras, 100%)."] = "La scheda di HowLongToBeat nella colonna laterale della panoramica (storia, extra, 100%).",
        ["The Metacritic card under How long to beat: the Metascore of the critics and the users' score."] = "La scheda di Metacritic sotto Quanto dura: il Metascore della critica e il voto degli utenti.",
        ["Unlock pop-ups"] = "Pop-up degli sblocchi",
        ["A small pop-up in the bottom-right corner when Steam records a new achievement, while Hybrid Launcher is open. Steam games only for now; read from Steam's own files, nothing is sent anywhere. It shows over borderless / windowed games, not over exclusive full screen."] = "Un piccolo pop-up nell'angolo in basso a destra quando Steam registra un nuovo obiettivo, mentre Hybrid Launcher è aperto. Per ora solo giochi Steam; letto dai file di Steam, non viene inviato nulla. Compare sopra i giochi in finestra o senza bordi, non sopra lo schermo intero esclusivo.",
        ["Try it"] = "Prova",
        ["Position"] = "Posizione",
        ["Bottom right"] = "In basso a destra",
        ["Bottom left"] = "In basso a sinistra",
        ["Top right"] = "In alto a destra",
        ["Top left"] = "In alto a sinistra",
        ["Screen"] = "Schermo",
        ["Where the game is"] = "Dove si trova il gioco",
        ["Size"] = "Dimensione",
        ["Normal"] = "Normale",
        ["Large"] = "Grande",
        ["Colour"] = "Colore",
        ["Colour theme accent"] = "Accento del tema colori",
        ["Gold"] = "Oro",
        ["Steam blue"] = "Blu Steam",
        ["My colour (#RRGGBB)"] = "Il mio colore (#RRGGBB)",
        ["Time on screen"] = "Tempo sullo schermo",
        ["Sound"] = "Suono",
        ["Pick .wav…"] = "Scegli .wav…",
        ["Windows notification"] = "Notifica di Windows",
        ["My sounds (.wav)"] = "I miei suoni (.wav)",
        ["Pop-ups"] = "Pop-up",
        ["No preset"] = "Nessun preset",
        ["My sounds"] = "I miei suoni",
        ["Save as…"] = "Salva come…",
        ["Preset name"] = "Nome del preset",
        ["Save these sounds as a preset"] = "Salva questi suoni come preset",
        ["Load a folder…"] = "Carica una cartella…",
        ["Its .wav files fill My sounds by their names (bronze, silver, gold, platinum; any other for every achievement) and are kept as a preset named after the folder."] = "I suoi file .wav riempiono I miei suoni in base al nome (bronze, silver, gold, platinum; un altro qualsiasi per ogni obiettivo) e vengono tenuti come preset con il nome della cartella.",
        ["No sounds"] = "Nessun suono",
        ["{0} has no .wav files."] = "{0} non contiene file .wav.",
        ["{0} sounds loaded from {1}."] = "{0} suoni caricati da {1}.",
        ["Delete this preset (the sound files stay)"] = "Elimina questo preset (i file audio restano)",
        ["Sound preset"] = "Preset dei suoni",
        ["Keep sets of your own sounds and switch between them, or load a folder of .wav files in one go."] = "Tieni più set di suoni tuoi e passa dall'uno all'altro, o carica in un colpo una cartella di file .wav.",
        ["A small pop-up (where you choose, in the look you choose) when a game unlocks an achievement, while Hybrid Launcher is open: Steam, GOG, local achievements and the feed folder. Read on this PC, nothing is sent anywhere. It shows over borderless / windowed games, not over exclusive full screen."] = "Un piccolo pop-up (dove vuoi, nello stile che vuoi) quando un gioco sblocca un obiettivo, mentre Hybrid Launcher è aperto: Steam, GOG, obiettivi locali e la cartella feed. Letto su questo PC, non viene inviato nulla. Appare sopra i giochi in finestra o senza bordi, non in schermo intero esclusivo.",
        ["Before a game starts, newer saves from the cloud come to this PC; after it closes, the saves that changed go to the cloud. Pick OneDrive (one click, through Windows' OneDrive app), sign in to MEGA, or use both: every upload then goes to each. Each game sends its saves, its own settings folder when it has one, and its local achievements when it keeps them. Older copies are kept, and what is here is backed up before anything replaces it."] = "Prima che un gioco parta, i salvataggi più recenti nel cloud arrivano su questo PC; quando si chiude, i salvataggi cambiati vanno nel cloud. Scegli OneDrive (un clic, tramite l'app OneDrive di Windows), accedi a MEGA, o usali entrambi: ogni caricamento va su tutti e due. Ogni gioco invia i suoi salvataggi, la sua cartella delle impostazioni quando ce l'ha, e i suoi obiettivi locali quando li tiene. Le copie più vecchie vengono conservate, e quello che c'è qui viene salvato prima di essere sostituito.",
        ["Open the local achievements folder"] = "Apri la cartella degli obiettivi locali",
        ["local achievements"] = "obiettivi locali",
        ["Local achievements"] = "Obiettivi locali",
        ["Achievements and the last session of games that keep them in save files on this PC."] = "Obiettivi e ultima sessione dei giochi che li tengono in file di salvataggio su questo PC.",
        ["PLATINUM UNLOCKED"] = "PLATINO SBLOCCATO",
        ["Platinum unlocked"] = "Platino sbloccato",
        ["Tireless"] = "Instancabile",
        ["Unlock every other achievement. This one is only a test."] = "Sblocca tutti gli altri obiettivi. Questo è solo un test.",
        ["No platinum"] = "Nessun platino",
        ["{0} has no achievement for unlocking all the others, so it has no platinum."] = "{0} non ha un obiettivo per sbloccare tutti gli altri, quindi non ha un platino.",
        ["SOURCES"] = "FONTI",
        ["Kept by Hybrid Launcher even if you uninstall the game, move it or add it again."] = "Conservato da Hybrid Launcher anche se disinstalli il gioco, lo sposti o lo aggiungi di nuovo.",
        ["Achievements and the last session of games that keep them in save files on this PC: shown on the game page and announced with a pop-up like the others."] = "Obiettivi e ultima sessione dei giochi che li tengono in file di salvataggio su questo PC: mostrati nella pagina del gioco e annunciati con un pop-up come gli altri.",
        ["Search all settings"] = "Cerca in tutte le impostazioni",
        ["No setting matches “{0}”."] = "Nessuna impostazione corrisponde a “{0}”.",
        ["{0} more: type a little more to narrow it down."] = "Altri {0}: scrivi ancora un po' per restringere.",
        ["A controller is connected."] = "Un controller è collegato.",
        ["A controller moves around Hybrid Launcher while its window is in front: the D-pad or left stick moves, the right stick scrolls, the buttons do what is set below. Turn it off if another tool (JoyToKey, JoyXoff, Steam Input) already moves the mouse with your controller, so each press acts only once."] = "Un controller si muove in Hybrid Launcher quando la sua finestra è in primo piano: croce direzionale o stick sinistro spostano, lo stick destro scorre, i tasti fanno quello che imposti qui sotto. Disattivalo se un altro programma (JoyToKey, JoyXoff, Steam Input) muove già il mouse con il controller, così ogni pressione agisce una volta sola.",
        ["A presses, B goes back, X opens the options menu, Y plays, LB / RB change tab, LT / RT scroll a page, Menu goes to the game list, View to Search."] = "A preme, B torna indietro, X apre il menu opzioni, Y avvia il gioco, LB / RB cambiano scheda, LT / RT scorrono di una pagina, Menu va all'elenco dei giochi, View alla ricerca.",
        ["Connected: {0}."] = "Collegato: {0}.",
        ["Controller"] = "Controller",
        ["Controller navigation, the buttons and the Home button go back to how Hybrid Launcher ships."] = "Navigazione con il controller, tasti e tasto Home tornano come in Hybrid Launcher appena installato.",
        ["Default buttons"] = "Tasti predefiniti",
        ["Game Bar settings"] = "Impostazioni di Game Bar",
        ["Hold leaves a short press to Windows or your handheld (Game Bar, the maker's menu)."] = "Tenere premuto lascia la pressione breve a Windows o alla tua console portatile (Game Bar, il menu del produttore).",
        ["Home button brings Hybrid Launcher back"] = "Il tasto Home riporta Hybrid Launcher",
        ["No controller connected right now."] = "Nessun controller collegato al momento.",
        ["Opens on"] = "Si apre su",
        ["PlayStation controllers connected directly"] = "Controller PlayStation collegati direttamente",
        ["Press again to go back"] = "Premi di nuovo per tornare indietro",
        ["Press or hold"] = "Premere o tenere premuto",
        ["Press the Xbox / Guide or PS button in a game or any app and Hybrid Launcher comes to the front, out of the notification area too, like a console's home screen: your achievements, notes and mods are a press away. The game keeps running."] = "Premi il tasto Xbox / Guide o PS in un gioco o in qualsiasi app e Hybrid Launcher passa in primo piano, anche dall'area di notifica, come la schermata home di una console: obiettivi, note e mod sono a una pressione di distanza. Il gioco continua a girare.",
        ["Reads the PS button of a DualShock 4 or DualSense plugged in or paired with Windows itself. Through DS4Windows, DualSenseX or Steam Input they show up as an Xbox controller, which is read already. Read only: the game reads the controller as before."] = "Legge il tasto PS di un DualShock 4 o DualSense collegato o associato direttamente a Windows. Con DS4Windows, DualSenseX o Steam Input appaiono come un controller Xbox, che viene già letto. Solo lettura: il gioco legge il controller come prima.",
        ["Reset buttons"] = "Ripristina i tasti",
        ["Used when Sound is My sounds. A rarity without its own .wav plays the one for every achievement, and without that the Windows sound. Rarity is the share of players who have the achievement (Steam's global stats); platinum is the game's achievement for unlocking all the others."] = "Usati quando Suono è I miei suoni. Una rarità senza un suo .wav suona quello di ogni obiettivo, e senza quello il suono di Windows. La rarità è la quota di giocatori che hanno l'obiettivo (statistiche globali di Steam); il platino è l'obiettivo del gioco per sbloccare tutti gli altri.",
        ["What each button does while Hybrid Launcher is in front (PlayStation names in brackets). A button does one thing: giving it to an action swaps it with the action that had it."] = "Cosa fa ogni tasto quando Hybrid Launcher è in primo piano (tra parentesi i nomi PlayStation). Un tasto fa una cosa sola: darlo a un'azione lo scambia con l'azione che lo aveva.",
        ["Where Hybrid Launcher opens when the Home button brings it forward."] = "Dove si apre Hybrid Launcher quando il tasto Home lo porta in primo piano.",
        ["Windows opens Game Bar with the Xbox button. To leave the button to Hybrid Launcher, turn off \"Open Game Bar using this button on a controller\" in Game Bar's settings, or pick Hold above. On a handheld (ROG Ally, Legion Go, MSI Claw), its maker's app can map a button to Xbox / Guide."] = "Windows apre Game Bar con il tasto Xbox. Per lasciare il tasto a Hybrid Launcher, disattiva \"Apri Game Bar con questo pulsante del controller\" nelle impostazioni di Game Bar, o scegli Tenere premuto qui sopra. Su una console portatile (ROG Ally, Legion Go, MSI Claw), l'app del produttore può assegnare un tasto a Xbox / Guide.",
        ["With Hybrid Launcher in front, the Home button takes you back to the game or app you came from."] = "Con Hybrid Launcher in primo piano, il tasto Home ti riporta al gioco o all'app da cui arrivavi.",
        ["Xbox button and Game Bar"] = "Tasto Xbox e Game Bar",
        ["NAVIGATION"] = "NAVIGAZIONE",
        ["BUTTONS"] = "TASTI",
        ["HOME BUTTON"] = "TASTO HOME",
        ["SOUNDS"] = "SUONI",
        ["Hold for half a second"] = "Tenere premuto mezzo secondo",
        ["The page of the game you are playing"] = "La pagina del gioco a cui stai giocando",
        ["The library"] = "La libreria",
        ["Where you left it"] = "Dove l'avevi lasciato",
        ["Rare: under 10% of players."] = "Raro: meno del 10% dei giocatori.",
        ["The game's own platinum: its achievement for unlocking all the others (most games have one)."] = "Il platino del gioco: il suo obiettivo per sbloccare tutti gli altri (quasi tutti i giochi ne hanno uno).",
        ["Options menu"] = "Menu opzioni",
        ["Previous tab"] = "Scheda precedente",
        ["Next tab"] = "Scheda successiva",
        ["Page up"] = "Pagina su",
        ["Page down"] = "Pagina giù",
        ["Search"] = "Cerca",
        ["Previous section"] = "Sezione precedente",
        ["Next section"] = "Sezione successiva",
        ["Press"] = "Premi",
        ["Presses what has the focus: a button, a game, a switch."] = "Preme ciò che ha il focus: un pulsante, un gioco, un interruttore.",
        ["Closes a menu or dialog, or goes back a page."] = "Chiude un menu o una finestra di dialogo, o torna indietro di una pagina.",
        ["The right-click menu of what has the focus (a game in the library, a list item)."] = "Il menu del clic destro di ciò che ha il focus (un gioco nella libreria, una voce di un elenco).",
        ["Starts the game of the open page."] = "Avvia il gioco della pagina aperta.",
        ["The tab on the left: on a game page, in Settings; on pages without tabs, the previous section."] = "La scheda a sinistra: nella pagina di un gioco, nelle Impostazioni; nelle pagine senza schede, la sezione precedente.",
        ["The tab on the right: on a game page, in Settings; on pages without tabs, the next section."] = "La scheda a destra: nella pagina di un gioco, nelle Impostazioni; nelle pagine senza schede, la sezione successiva.",
        ["Scrolls up a whole page."] = "Scorre su di una pagina intera.",
        ["Scrolls down a whole page."] = "Scorre giù di una pagina intera.",
        ["Jumps to the list of games on the left."] = "Salta all'elenco dei giochi a sinistra.",
        ["Puts the cursor in Search games."] = "Mette il cursore in Cerca giochi.",
        ["My PC, Library, Downloads and Settings, one after another, from any page."] = "Il mio PC, Libreria, Download e Impostazioni, uno dopo l'altro, da qualsiasi pagina.",
        ["The same, the other way."] = "Lo stesso, nell'altro verso.",
        ["A  (Cross)"] = "A  (Croce)",
        ["B  (Circle)"] = "B  (Cerchio)",
        ["X  (Square)"] = "X  (Quadrato)",
        ["Y  (Triangle)"] = "Y  (Triangolo)",
        ["Left stick press  (L3)"] = "Pressione stick sinistro  (L3)",
        ["Right stick press  (R3)"] = "Pressione stick destro  (R3)",
        ["Language, colour theme, material and the icons of the app."] = "Lingua, tema colori, materiale e icone dell'app.",
        ["What Hybrid Launcher does: graphics, the window, game page tabs, the library, mods and finding games."] = "Cosa fa Hybrid Launcher: grafica, finestra, schede della pagina gioco, libreria, mod e ricerca dei giochi.",
        ["Moving around with a controller, what each button does, and the Home button that brings Hybrid Launcher back from a game."] = "Muoversi con un controller, cosa fa ogni tasto, e il tasto Home che riporta Hybrid Launcher da un gioco.",
        ["The pop-up shown when a game unlocks an achievement: its look, where it shows, and its sounds."] = "Il pop-up che appare quando un gioco sblocca un obiettivo: stile, posizione e suoni.",
        ["The notification list in the title bar, and what you hear about."] = "L'elenco delle notifiche nella barra del titolo, e di cosa vieni avvisato.",
        ["Copies of your saves in the cloud services you link."] = "Copie dei tuoi salvataggi nei servizi cloud che colleghi.",
        ["Game updates, game folders, and where Hybrid Launcher keeps what it downloads."] = "Aggiornamenti dei giochi, cartelle dei giochi e dove Hybrid Launcher tiene ciò che scarica.",
        ["The version, updates, and the projects Hybrid Launcher works with."] = "La versione, gli aggiornamenti e i progetti con cui lavora Hybrid Launcher.",
        ["Sounds"] = "Suoni",
        ["SOUND"] = "SUONO",
        ["MY SOUNDS"] = "I MIEI SUONI",
        ["Bronze"] = "Bronzo",
        ["Silver"] = "Argento",
        ["Platinum"] = "Platino",
        ["Every achievement"] = "Ogni obiettivo",
        ["Plays for a rarity that has no sound of its own."] = "Suona per una rarità che non ha un suono suo.",
        ["Not set: the Windows sound plays."] = "Non impostato: suona il suono di Windows.",
        ["Not set: the sound for every achievement plays."] = "Non impostato: suona il suono di ogni obiettivo.",
        ["{0} is no longer there: the next sound in line plays."] = "{0} non c'è più: suona il successivo.",
        ["Common: 30% of players or more, or the rarity is not known."] = "Comune: il 30% dei giocatori o più, o rarità sconosciuta.",
        ["Uncommon: 10% to 30% of players."] = "Non comune: dal 10% al 30% dei giocatori.",
        ["What plays when a pop-up shows. No sounds come with Hybrid Launcher: with My sounds, pick your own .wav files below, one for each rarity if you like."] = "Cosa suona quando appare un pop-up. Hybrid Launcher non include suoni: con I miei suoni scegli i tuoi file .wav qui sotto, anche uno per ogni rarità.",
        ["How loud the sound plays. Let go of the slider to hear it."] = "Quanto forte suona. Rilascia il cursore per sentirlo.",
        ["Used when Sound is My sounds. A rarity without its own .wav plays the one for every achievement, and without that the Windows sound. Rarity is the share of players who have the achievement (Steam's global stats)."] = "Usati quando Suono è I miei suoni. Una rarità senza un suo .wav suona quello di ogni obiettivo, e senza quello il suono di Windows. La rarità è la quota di giocatori che hanno l'obiettivo (statistiche globali di Steam).",
        ["Show how rare it is"] = "Mostra quanto è raro",
        ["No file picked yet"] = "Ancora nessun file scelto",
        ["Game detection"] = "Rilevamento dei giochi",
        ["Stores to scan"] = "Store da analizzare",
        ["Installed games are found from each launcher's own records. Nothing is changed in the launchers."] = "I giochi installati vengono trovati dai dati di ogni launcher. Nei launcher non viene cambiato nulla.",
        ["Games folders"] = "Cartelle giochi",
        ["Each sub-folder that contains an .exe is listed as a game."] = "Ogni sottocartella che contiene un .exe compare come gioco.",
        ["Add folder…"] = "Aggiungi cartella…",
        ["Games added by hand"] = "Giochi aggiunti a mano",
        ["Added with “Add a game (pick its .exe)”."] = "Aggiunti con “Aggiungi un gioco (scegli il suo .exe)”.",
        ["Hidden games"] = "Giochi nascosti",
        ["Games you hid from the list."] = "Giochi che hai nascosto dalla lista.",
        ["Downloads and data"] = "Download e dati",
        ["Saved OptiScaler versions"] = "Versioni di OptiScaler salvate",
        ["Delete all downloads"] = "Elimina tutti i download",
        ["Downloaded releases (the newest 3 per channel are kept, in {0}) and the custom builds you imported."] = "Versioni scaricate (le 3 più recenti per canale, in {0}) e le build personalizzate che hai importato.",
        ["Custom OptiScaler builds folder"] = "Cartella delle build personalizzate di OptiScaler",
        ["Each sub-folder (or .zip / .7z) holding an OptiScaler DLL is a build you can install from a game's Custom box."] = "Ogni sottocartella (o .zip / .7z) con una dll di OptiScaler è una build che puoi installare dalla scelta Build personalizzata di un gioco.",
        ["Change…"] = "Cambia…",
        ["Hybrid Launcher data"] = "Dati di Hybrid Launcher",
        ["Open logs"] = "Apri i log",
        ["Open folder"] = "Apri la cartella",
        ["Could not clear the cache"] = "Impossibile svuotare la cache",
        ["(running as administrator)"] = "(in esecuzione come amministratore)",
        ["Support on Ko-fi"] = "Sostienimi su Ko-fi",
        ["OptiScaler, OptiPatcher and their setup script belong to the OptiScaler team; Hybrid Launcher downloads them from GitHub and runs them unchanged."] = "OptiScaler, OptiPatcher e il loro script di installazione appartengono al team di OptiScaler; Hybrid Launcher li scarica da GitHub e li esegue senza modifiche.",
        ["ReShade installers come from reshade.me and run unchanged; RenoDX mods come from their authors' GitHub pages or, for Nexus Mods files, from your own download."] = "Gli installer di ReShade arrivano da reshade.me e girano senza modifiche; le mod RenoDX arrivano dalle pagine GitHub dei loro autori o, per i file di Nexus Mods, dal tuo download.",
