        ["Choices"] = "Scelte",
        ["Clear finished"] = "Togli i completati",
        ["Click a key, then press the one you want."] = "Clicca un tasto, poi premi quello che vuoi.",
        ["Click to fold this group. Drag it up or down to move the group."] = "Clicca per chiudere il gruppo. Trascinalo su o giù per spostarlo.",
        ["Click to show these games. Drag it up or down to move the group."] = "Clicca per mostrare questi giochi. Trascinalo su o giù per spostare il gruppo.",
        ["Click, then press the key you want"] = "Clicca, poi premi il tasto che vuoi",
        ["Close the game"] = "Chiudi il gioco",
        ["Close {0}?"] = "Chiudere {0}?",
        ["Closing the game…"] = "Chiusura del gioco…",
        ["Closing the window leaves Hybrid Launcher in the notification area (by the clock): games stay tracked, Smart HDR keeps working, achievements still pop up. Right-click its icon there to quit."] = "Chiudendo la finestra Hybrid Launcher resta nell'area di notifica (vicino all'orologio): i giochi restano seguiti, lo Smart HDR continua a funzionare e gli obiettivi compaiono ancora. Tasto destro sulla sua icona per uscire.",
        ["Could not change the preset"] = "Impossibile cambiare il preset",
        ["Could not change the start with Windows setting"] = "Impossibile cambiare l'avvio con Windows",
        ["Could not delete the preset"] = "Impossibile eliminare il preset",
        ["Could not go forward"] = "Impossibile andare avanti",
        ["Could not import the preset"] = "Impossibile importare il preset",
        ["Could not install Luma"] = "Impossibile installare Luma",
        ["Could not load the Luma list (offline?). The mod list link above opens it in the browser."] = "Impossibile caricare l'elenco di Luma (offline?). Il link all'elenco qui sopra lo apre nel browser.",
