        ["Games not installed (from your launchers)"] = "Giochi non installati (dei tuoi launcher)",
        ["Games you own on Steam, Epic or GOG but have not installed, with an Install button (accounts in Downloads)."] = "I giochi che possiedi su Steam, Epic o GOG ma non hai installato, con il tasto Installa (account in Download).",
