        ["It is the active one: ReShade goes back to its default preset."] = "È quello attivo: ReShade torna al suo preset predefinito.",
        ["Its settings could not be read now. The mod's page lists them."] = "Impossibile leggere ora le sue impostazioni. La pagina della mod le elenca.",
