        ["Linked accounts"] = "Account collegati",
        ["Luma brings its own ReShade with add-on support and replaces {0} (Hybrid Launcher keeps a backup and puts it back when you uninstall Luma). Your ReShade presets and shaders stay."] = "Luma porta il suo ReShade con supporto add-on e sostituisce {0} (Hybrid Launcher ne tiene una copia e la rimette quando disinstalli Luma). I tuoi preset e shader di ReShade restano.",
        ["Luma files are in the folder (not installed by Hybrid Launcher)"] = "Nella cartella ci sono file di Luma (non installati da Hybrid Launcher)",
        ["Luma is not installed in this game"] = "Luma non è installato in questo gioco",
        ["Luma mod list"] = "Elenco mod Luma",
        ["Luma removed, with problems"] = "Luma rimosso, con dei problemi",
        ["Luma: HDR and DLSS for this game"] = "Luma: HDR e DLSS per questo gioco",
        ["Make ReShade load this preset (the one on now goes off)."] = "Fa caricare questo preset a ReShade (quello attivo ora si spegne).",
        ["Microsoft keeps the Xbox / Game Pass library online only: install games from the Xbox app. Hybrid Launcher lists them once installed."] = "Microsoft tiene la libreria Xbox / Game Pass solo online: installa i giochi dall'app Xbox. Hybrid Launcher li elenca una volta installati.",
        ["Move down"] = "Sposta giù",
        ["Move up"] = "Sposta su",
