        ["New note"] = "Nuova nota",
        ["No Luma mod is listed for {0} yet."] = "Nessuna mod Luma è ancora elencata per {0}.",
        ["No OptiScaler here: Luma's ReShade loads as dxgi.dll"] = "Qui non c'è OptiScaler: il ReShade di Luma si carica come dxgi.dll",
        ["No build of this mod is published on GitHub yet."] = "Nessuna build di questa mod è ancora pubblicata su GitHub.",
        ["No key"] = "Nessun tasto",
