        ["No notes yet. Make the first one with New note."] = "Ancora nessuna nota. Crea la prima con Nuova nota.",
        ["No presets in this game yet. Import .ini presets (from Nexus Mods, a friend, another game): they are copied into the game folder, then turn one on."] = "Ancora nessun preset in questo gioco. Importa preset .ini (da Nexus Mods, da un amico, da un altro gioco): vengono copiati nella cartella del gioco, poi attivane uno.",
        ["No store details."] = "Nessun dettaglio dallo store.",
        ["Nobody is signed in to Steam on this PC."] = "Nessuno ha fatto l'accesso a Steam su questo PC.",
        ["Not in reshade-shaders (install them with ReShade's setup or copy them there):"] = "Non presenti in reshade-shaders (installali con il setup di ReShade o copiali lì):",
        ["Not linked: its games are not listed here."] = "Non collegato: i suoi giochi non sono elencati qui.",
        ["Note {0}"] = "Nota {0}",
        ["Open Hybrid Launcher"] = "Apri Hybrid Launcher",
        ["Open the Xbox app"] = "Apri l'app Xbox",
