        ["Open this game in the Xbox app"] = "Apri questo gioco nell'app Xbox",
        ["Opens the game's store page in Steam, at its reviews: write yours there with your Steam account."] = "Apre la pagina del gioco nello store di Steam, alle recensioni: scrivi la tua lì con il tuo account Steam.",
        ["Opens this game's controller layout in Steam (Steam Input: remapping and community configurations)"] = "Apre il layout del controller di questo gioco in Steam (Steam Input: rimappatura e configurazioni della community)",
        ["Opens {0} on its install page for this game; Hybrid Launcher follows the download."] = "Apre {0} sulla pagina d'installazione di questo gioco; Hybrid Launcher segue il download.",
        ["OptiScaler is here: Luma's ReShade goes in as ReShade64.dll and OptiScaler loads it"] = "Qui c'è OptiScaler: il ReShade di Luma va come ReShade64.dll e lo carica OptiScaler",
