        ["Hybrid Launcher asks the game to close, as if you closed its window, and ends it after a few seconds if it does not. Progress that is not saved is lost."] = "Hybrid Launcher chiede al gioco di chiudersi, come se chiudessi la sua finestra, e lo termina dopo qualche secondo se non lo fa. I progressi non salvati vanno persi.",
        ["Hybrid Launcher starts in the notification area when you sign in to Windows, without opening its window. Its icon may be among the hidden icons (the arrow by the clock)."] = "Hybrid Launcher parte nell'area di notifica quando accedi a Windows, senza aprire la finestra. La sua icona può essere tra le icone nascoste (la freccia vicino all'orologio).",
