        // Through variables: the new tab, the Luma tips, Steam's review words, the tab icon choices, the overview's cards.
        ["Luma Framework mods: HDR and DLSS for DirectX 11 games"] = "Mod di Luma Framework: HDR e DLSS per giochi DirectX 11",
        ["• Each Luma mod is made for one game (or one engine): it rewrites the game's post-processing for real HDR, and many add DLSS / FSR."] = "• Ogni mod Luma è fatta per un gioco (o un motore): riscrive il post-processing del gioco per un vero HDR, e molte aggiungono DLSS / FSR.",
        ["• The package brings its own ReShade with add-on support: no separate ReShade install is needed."] = "• Il pacchetto porta il suo ReShade con supporto add-on: non serve installare ReShade a parte.",
        ["• With OptiScaler in the folder, Hybrid Launcher installs Luma's ReShade as ReShade64.dll and OptiScaler loads it (LoadReshade = true): both work together. Use one upscaler at a time: Luma's DLSS or OptiScaler's."] = "• Con OptiScaler nella cartella, Hybrid Launcher installa il ReShade di Luma come ReShade64.dll e lo carica OptiScaler (LoadReshade = true): funzionano insieme. Usa un upscaler alla volta: il DLSS di Luma o quello di OptiScaler.",
        ["• Turn on HDR in Windows (or Smart HDR on the launch bar). Turn off Auto HDR / RTX HDR for the game: they would tone map twice."] = "• Accendi l'HDR di Windows (o lo Smart HDR nella barra di avvio). Spegni Auto HDR / RTX HDR per il gioco: farebbero il tone mapping due volte.",
        ["• In game, Home opens ReShade: Luma's settings are in its Add-ons tab."] = "• In gioco, Home apre ReShade: le impostazioni di Luma sono nella sua tab Add-ons.",
        ["Overwhelmingly Positive"] = "Estremamente positive",
        ["Very Positive"] = "Molto positive",
        ["Positive"] = "Positive",
        ["Mostly Positive"] = "Perlopiù positive",
        ["Mixed"] = "Nella media",
