        ["Idle (power-saving)"] = "Inattiva (risparmio energetico)",
        ["Desktop shortcut for downloaded games"] = "Collegamento sul desktop per i giochi scaricati",
        ["A game Hybrid Launcher downloads gets a shortcut on the desktop when it is installed. It starts the game through the app, so Smart HDR, play time and cloud saves work."] = "Un gioco scaricato da Hybrid Launcher riceve un collegamento sul desktop quando è installato. Avvia il gioco tramite l'app, così Smart HDR, tempo di gioco e salvataggi nel cloud funzionano.",
        ["{0} is installed. Its shortcut is on the desktop."] = "{0} è installato. Il suo collegamento è sul desktop.",
        ["A game's page"] = "La pagina di un gioco",
        ["Check at start"] = "Controlla all'avvio",
        ["Check for updates"] = "Cerca aggiornamenti",
        ["Checking GitHub…"] = "Controllo su GitHub…",
        ["Colour themes, cloud saves (OneDrive, MEGA or a folder), achievement pop-ups, game updates and the app's own updates. This tour is in Settings → Features → Welcome tour."] = "Temi di colore, salvataggi nel cloud (OneDrive, MEGA o una cartella), pop-up degli obiettivi, aggiornamenti dei giochi e dell'app stessa. Questo tour è in Impostazioni → Funzionalità → Tour di benvenuto.",
        ["Could not check for updates"] = "Impossibile cercare aggiornamenti",
        ["Downloading the update…"] = "Download dell'aggiornamento…",
        ["Every game you own as covers, installed or not, with search and filters. A game that is not installed has Download on its page."] = "Tutti i giochi che possiedi come copertine, installati o no, con ricerca e filtri. Un gioco non installato ha Scarica nella sua pagina.",
        ["Every installed game, grouped by launcher. Type here to search; the button beside the box sorts and filters. Right-click a game to pin it on top."] = "Tutti i giochi installati, raggruppati per launcher. Scrivi qui per cercare; il pulsante accanto ordina e filtra. Clic destro su un gioco per fissarlo in cima.",
        ["Game has the overview, trailer and controller support. OptiScaler installs in one click and swaps DLSS, FSR and XeSS; Mods lists what is in the game folder and adds ReShade, RenoDX, Luma, DLSS 5 and DXVK; PCGamingWiki lists the game's known fixes. Drag a tab to reorder it."] = "Gioco ha la panoramica, il trailer e il supporto ai controller. OptiScaler si installa con un clic e scambia DLSS, FSR e XeSS; Mod elenca cosa c'è nella cartella del gioco e aggiunge ReShade, RenoDX, Luma, DLSS 5 e DXVK; PCGamingWiki elenca le correzioni note del gioco. Trascina una scheda per spostarla.",
        ["Later"] = "Più tardi",
        ["No notes for this version."] = "Nessuna nota per questa versione.",
        ["Open any game from the list to start. Have fun!"] = "Apri un gioco dall'elenco per iniziare. Buon divertimento!",
        ["Restarting…"] = "Riavvio…",
        ["Sign in to Steam, Epic or GOG with Accounts at the top right of this page to install the games you own. Downloads and game updates show here, with pause and resume."] = "Accedi a Steam, Epic o GOG con Account in alto a destra in questa pagina per installare i giochi che possiedi. Qui compaiono download e aggiornamenti dei giochi, con pausa e ripresa.",
        ["The gear opens the game's properties: launch options, which exe to start, desktop shortcut, files and uninstall."] = "L'ingranaggio apre le proprietà del gioco: opzioni di avvio, quale exe avviare, collegamento sul desktop, file e disinstallazione.",
        ["The tips shown at the first start, each beside the real control: your games, a game's page and its tools, Library, Downloads, My PC and Settings."] = "I suggerimenti mostrati al primo avvio, ognuno accanto al controllo reale: i tuoi giochi, la pagina di un gioco e i suoi strumenti, Libreria, Download, Il mio PC e Impostazioni.",
        ["The update could not be downloaded: {0}"] = "Impossibile scaricare l'aggiornamento: {0}",
        ["The update has no app inside it."] = "L'aggiornamento non contiene l'app.",
        ["This is {0}'s page. Play starts the game; while it runs the same button stops it. Last played and play time are beside it."] = "Questa è la pagina di {0}. Gioca avvia il gioco; mentre è in esecuzione lo stesso pulsante lo ferma. Ultima partita e tempo di gioco sono accanto.",
        ["Tools for this game"] = "Strumenti per questo gioco",
        ["Turn it on and Windows HDR switches on when this game starts and off when it closes, even after a crash. When it is off, the tile shows what Windows HDR is now: On or Off."] = "Attivalo e l'HDR di Windows si accende quando il gioco parte e si spegne quando si chiude, anche dopo un crash. Quando è disattivo, il riquadro mostra lo stato attuale dell'HDR di Windows: Attivo o Disattivo.",
        ["Update available"] = "Aggiornamento disponibile",
        ["{0} {1} is available. Click to update."] = "{0} {1} è disponibile. Fai clic per aggiornare.",
        ["Update now"] = "Aggiorna ora",
        ["Update to {0}"] = "Aggiorna a {0}",
        ["Updated to {0} {1}."] = "Aggiornato a {0} {1}.",
        ["Updates"] = "Aggiornamenti",
        ["You have the newest version ({0})."] = "Hai la versione più recente ({0}).",
        ["You have {0}. New versions come from GitHub and install with one click."] = "Hai la {0}. Le nuove versioni arrivano da GitHub e si installano con un clic.",
        ["Your Steam, Epic, GOG and Xbox games in one place, with the tools PC players add to them: OptiScaler, ReShade, RenoDX, Luma, cloud saves and Smart HDR. This tour shows where each one is, on the real window; it takes about a minute."] = "I tuoi giochi Steam, Epic, GOG e Xbox in un solo posto, con gli strumenti che i giocatori PC ci aggiungono: OptiScaler, ReShade, RenoDX, Luma, salvataggi nel cloud e Smart HDR. Questo tour mostra dove si trova ognuno, sulla finestra vera; richiede circa un minuto.",
        ["Your graphics card, processor, memory and displays, with the exact version of every upscaler and frame generation your card runs, and Windows' own graphics switches."] = "Scheda video, processore, memoria e schermi, con la versione esatta di ogni upscaler e frame generation che la scheda supporta, e gli interruttori grafici di Windows.",
        ["{0} is out: update now, the app opens again by itself."] = "È uscita la {0}: aggiorna ora, l'app si riapre da sola.",
        ["{0} {1} is out (you have {2}). Update now? The app closes for a moment and opens again by itself; your games, settings and accounts stay as they are."] = "È uscito {0} {1} (hai la {2}). Aggiornare ora? L'app si chiude per un momento e si riapre da sola; giochi, impostazioni e account restano come sono.",
        ["Windows HDR is on now."] = "L'HDR di Windows ora è attivo.",
        ["Windows HDR is off now."] = "L'HDR di Windows ora è disattivo.",
        ["The OneDrive app is not set up on this PC: sign in to it with your Microsoft account, then come back here."] = "L'app OneDrive non è configurata su questo PC: accedi con il tuo account Microsoft, poi torna qui.",
        ["Saves go to \"{0}\" in your OneDrive; Windows' OneDrive app keeps them in sync."] = "I salvataggi vanno in \"{0}\" nel tuo OneDrive; l'app OneDrive di Windows li tiene sincronizzati.",
        ["Set up OneDrive"] = "Configura OneDrive",
        ["Check again"] = "Controlla di nuovo",
        ["Native"] = "Nativo",
        ["Through OptiScaler"] = "Tramite OptiScaler",
        ["The newest version of each technology (its latest release, whatever driver is installed). Native runs on the card itself; the others work through OptiScaler. Update the driver to get the newest ones."] = "La versione più recente di ogni tecnologia (l'ultima uscita, qualunque driver sia installato). Nativo gira sulla scheda stessa; le altre funzionano tramite OptiScaler. Aggiorna il driver per avere le più recenti.",
        ["FSR Redstone, driver-assisted frame pacing"] = "FSR Redstone, frame pacing assistito dal driver",
        ["FSR Redstone, DirectX 12"] = "FSR Redstone, DirectX 12",
        ["AI upscaling on RX 7000"] = "Upscaling IA su RX 7000",
        ["In games that ship it"] = "Nei giochi che lo includono",
        ["RTX 50 first; RTX 40 support announced for later"] = "Prima su RTX 50; supporto RTX 40 annunciato per dopo",
        ["UPSCALING AND FRAME GENERATION"] = "UPSCALING E FRAME GENERATION",
        ["DISPLAYS AND WINDOWS SETTINGS"] = "SCHERMI E IMPOSTAZIONI DI WINDOWS",
        ["Second-generation transformer model"] = "Modello transformer di seconda generazione",
        ["Dynamic, up to 6x"] = "Dinamica, fino a 6x",
        ["DP4a path, lighter than on Intel Arc"] = "Percorso DP4a, più leggero che su Intel Arc",
        ["Any card with Shader Model 6.4"] = "Qualsiasi scheda con Shader Model 6.4",
        ["INT8 model for RX 6000 (Adrenalin 26.10.1 and newer)"] = "Modello INT8 per RX 6000 (Adrenalin 26.10.1 e successivi)",
        ["Needs Adrenalin 26.10.1 or newer (INT8 model for RX 6000)"] = "Serve Adrenalin 26.10.1 o successivo (modello INT8 per RX 6000)",
        ["In games that ship it; FSR frame generation pairs with it"] = "Nei giochi che lo includono; la frame generation FSR lo usa insieme",
        ["Driver-wide"] = "In tutto il driver",
        ["Starting… Click to force the game closed"] = "Avvio… Clic per chiudere forzatamente il gioco",
        ["Icon colours"] = "Colori delle icone",
        ["The icons of the game page tabs and sections: one quiet colour, or each in its own colour."] = "Le icone delle schede e delle sezioni della pagina del gioco: un colore sobrio, o ognuna col suo colore.",
        ["Icons"] = "Icone",
        ["Tabs"] = "Schede",
        ["The icons of the game page tabs"] = "Le icone delle schede della pagina del gioco",
        ["Sub-tabs"] = "Sottoschede",
        ["The icons of the sections under a tab (OptiScaler, Mods...)"] = "Le icone delle sezioni sotto una scheda (OptiScaler, Mod...)",
        ["Card headings"] = "Intestazioni dei riquadri",
        ["The icons beside the headings of the cards inside the tabs"] = "Le icone accanto ai titoli dei riquadri dentro le schede",
        ["Launch bar"] = "Barra di avvio",
        ["The icons of HDR, the folders and the achievements beside Play"] = "Le icone di HDR, delle cartelle e degli obiettivi accanto a Gioca",
        ["Banner"] = "Banner",
        ["The logos of the links and tags on the game's banner"] = "I loghi dei link e dei tag sul banner del gioco",
        ["Game list"] = "Lista dei giochi",
        ["The icons of My PC, Library, Downloads and the games in the side list"] = "Le icone di Il mio PC, Libreria, Download e dei giochi nella lista laterale",
        ["Game page"] = "Pagina del gioco",
        ["What the banner and the launch bar show in every game. To hide something for one game only, use the gear beside Play → Show on this page on its page."] = "Cosa mostrano il banner e la barra di avvio in ogni gioco. Per nascondere qualcosa in un solo gioco usa ⋯ → Mostra in questa pagina nella sua pagina.",
        ["Links on the banner"] = "Link sul banner",
        ["Tags on the banner (store, graphics API, upscalers, developer and date)"] = "Tag sul banner (negozio, API grafica, upscaler, sviluppatore e data)",
        ["Last played and play time"] = "Ultima partita e tempo di gioco",
        ["Achievements button"] = "Pulsante degli obiettivi",
        ["Where mods go (the line under the bar)"] = "Dove vanno le mod (la riga sotto la barra)",
        ["Show on this page"] = "Mostra in questa pagina",
        ["(hidden in every game)"] = "(nascosto in tutti i giochi)",
        ["Choose for every game…"] = "Scegli per tutti i giochi…",
        ["Customize"] = "Personalizza",
        ["Choose which OptiScaler settings the Quick Panel shows"] = "Scegli quali impostazioni di OptiScaler mostra il Quick Panel",
        ["IN THE QUICK PANEL"] = "NEL QUICK PANEL",
        ["ADD A SETTING"] = "AGGIUNGI UN'IMPOSTAZIONE",
        ["Search every OptiScaler setting"] = "Cerca tra tutte le impostazioni di OptiScaler",
        ["Remove from the Quick Panel"] = "Togli dal Quick Panel",
        ["Back to the Quick Panel's own settings"] = "Torna alle impostazioni predefinite del Quick Panel",
        ["The Quick Panel is empty. Add the settings you change most with +."] = "Il Quick Panel è vuoto. Aggiungi con + le impostazioni che cambi più spesso.",
        ["Add a setting"] = "Aggiungi un'impostazione",
        ["Install OptiScaler first: the settings come from its OptiScaler.ini."] = "Prima installa OptiScaler: le impostazioni vengono dal suo OptiScaler.ini.",
        ["What each stable and nightly OptiScaler release changed"] = "Cosa ha cambiato ogni versione stabile e nightly di OptiScaler",
        ["What each OptiScaler version changed, from GitHub"] = "Cosa ha cambiato ogni versione di OptiScaler, da GitHub",
        ["All releases"] = "Tutte le versioni",
        ["No notes for this release."] = "Nessuna nota per questa versione.",
        ["GitHub lists no releases for this channel."] = "GitHub non elenca versioni per questo canale.",
        ["GitHub could not be reached."] = "GitHub non è raggiungibile.",
        ["Introduction"] = "Introduzione",
        ["Game info"] = "Informazioni sul gioco",
        ["Developers"] = "Sviluppatori",
        ["Publishers"] = "Editori",
        ["Engines"] = "Motori",
        ["Release dates"] = "Date di uscita",
        ["Reception"] = "Accoglienza",
        ["Taxonomy"] = "Classificazione",
        ["Elsewhere"] = "Altrove",
        ["Official site"] = "Sito ufficiale",
        ["Sign in with account name"] = "Accedi con il nome dell'account",
        ["Or sign in with QR"] = "Oppure accedi con il QR",
        ["Use the Steam mobile app to sign in via QR code"] = "Usa l'app mobile di Steam per accedere con il codice QR",
        ["Both ways go straight to Steam, which hands back a sign-in token; Hybrid Launcher keeps only that token, encrypted for your Windows user."] = "Entrambi i modi vanno direttamente a Steam, che restituisce un token di accesso; Hybrid Launcher tiene solo quel token, cifrato per il tuo utente di Windows.",
        ["Signing in with the account name instead."] = "Accesso con il nome dell'account al suo posto.",
        ["Install folders"] = "Cartelle di installazione",
        ["Games go where their launcher installs them, under the launcher's own folder name, so the launcher sees them too."] = "I giochi vanno dove li installa il loro launcher, con il nome di cartella del launcher, così il launcher li vede anche lui.",
        ["launcher's folder"] = "cartella del launcher",
        ["Launcher's folder"] = "Cartella del launcher",
        ["The folder {0} games downloaded by Hybrid Launcher go in (one folder per game)"] = "La cartella in cui vanno i giochi {0} scaricati da Hybrid Launcher (una cartella per gioco)",
        ["Could not install"] = "Installazione non riuscita",
        ["Hybrid Launcher may not write in {0}. Allow it when Windows asks, or choose another folder in Downloads → Accounts."] = "Hybrid Launcher non può scrivere in {0}. Consentilo quando Windows lo chiede, o scegli un'altra cartella in Download → Account.",
        ["Hybrid Launcher downloads the official installer from reshade.me and starts it with this game's exe chosen. Pick the graphics API there and, if you like, some shaders. Run it again to update; Remove ReShade takes it out, ReShade64.dll included."] = "Hybrid Launcher scarica l'installer ufficiale da reshade.me e lo avvia con l'exe di questo gioco già scelto. Lì scegli l'API grafica e, se vuoi, qualche shader. Avvialo di nuovo per aggiornare; Rimuovi ReShade lo toglie, ReShade64.dll compresa.",
        ["Remove ReShade"] = "Rimuovi ReShade",
        ["Remove ReShade from this game?"] = "Rimuovere ReShade da questo gioco?",
        ["Deletes {0} from the game folder. ReShade.ini, presets and shaders are kept."] = "Elimina {0} dalla cartella del gioco. ReShade.ini, preset e shader restano.",
        ["Could not remove ReShade"] = "Impossibile rimuovere ReShade",
        ["There was no ReShade dll in the game folder."] = "Nella cartella del gioco non c'era nessuna dll di ReShade.",
        ["Removed {0}. ReShade.ini, presets and shaders are kept for a later install."] = "Rimossi: {0}. ReShade.ini, preset e shader restano per una prossima installazione.",
        ["ReShade {0} is in the folder but nothing loads it"] = "ReShade {0} è nella cartella ma niente lo carica",
        ["{0} is only loaded by OptiScaler with LoadReshade on. Turn it on below, or remove ReShade."] = "{0} viene caricato solo da OptiScaler con LoadReshade attivo. Attivalo qui sotto, o rimuovi ReShade.",
        ["OptiScaler's own DLL is missing"] = "Manca la dll di OptiScaler",
        ["Only OptiScaler.ini is left (ReShade's installer may have written over OptiScaler's DLL), so nothing loads ReShade64.dll. Install OptiScaler again from the OptiScaler tab."] = "È rimasto solo OptiScaler.ini (l'installer di ReShade può aver sovrascritto la dll di OptiScaler), quindi niente carica ReShade64.dll. Reinstalla OptiScaler dalla scheda OptiScaler.",
        ["ReShade had written over OptiScaler's DLL: install OptiScaler again from the OptiScaler tab. ReShade stays as ReShade64.dll."] = "ReShade aveva sovrascritto la dll di OptiScaler: reinstalla OptiScaler dalla scheda OptiScaler. ReShade resta come ReShade64.dll.",
        ["Platinum: every Steam achievement unlocked"] = "Platino: tutti gli obiettivi Steam sbloccati",
        ["{0} library"] = "Libreria {0}",
        ["Ray reconstruction"] = "Ray reconstruction",
        ["Latency"] = "Latenza",
        ["Transformer model"] = "Modello transformer",
        ["Up to 6x, dynamic"] = "Fino a 6x, dinamica",
        ["Any recent card"] = "Qualsiasi scheda recente",
        ["DP4a path, lighter quality"] = "Percorso DP4a, qualità più bassa",
        ["XMX cores"] = "Core XMX",
        ["Up to 4x"] = "Fino a 4x",
        ["Needs an RTX 40 or 50: use FSR or XeSS frame generation through OptiScaler"] = "Richiede una RTX 40 o 50: usa la frame generation FSR o XeSS tramite OptiScaler",
        ["Driver frame generation for any DX11 / DX12 / Vulkan game"] = "Frame generation del driver per qualsiasi gioco DX11 / DX12 / Vulkan",
        ["Frame Warp where the game supports it"] = "Frame Warp dove il gioco lo supporta",
        ["Needs an RTX card: FSR or XeSS take its place through OptiScaler"] = "Richiede una scheda RTX: FSR o XeSS lo sostituiscono tramite OptiScaler",
        ["GTX 900 and newer"] = "GTX 900 e successive",
        ["FSR Redstone, AI upscaling"] = "FSR Redstone, upscaling con IA",
        ["Only through OptiScaler's unofficial INT8 path"] = "Solo tramite il percorso INT8 non ufficiale di OptiScaler",
        ["Games with only DLSS need OptiScaler's spoofing"] = "I giochi solo DLSS richiedono lo spoofing di OptiScaler",
        // ---- 0.24: game updates ----
        ["GAME UPDATES"] = "AGGIORNAMENTI DEI GIOCHI",
        ["Keep games up to date"] = "Tieni i giochi aggiornati",
        ["Games Hybrid Launcher downloaded (Steam, Epic Games, GOG) are checked when Hybrid Launcher starts and every six hours, and update in Downloads by themselves, like on Steam: only the files that changed are downloaded, mods and settings stay. A game does not start while it updates."] = "I giochi scaricati da Hybrid Launcher (Steam, Epic Games, GOG) vengono controllati all'avvio di Hybrid Launcher e ogni sei ore, e si aggiornano da soli in Download, come su Steam: si scaricano solo i file cambiati, mod e impostazioni restano. Un gioco non parte mentre si aggiorna.",
        ["Check now"] = "Controlla ora",
        ["Games installed by a launcher"] = "Giochi installati da un launcher",
        ["Steam, the Epic Games Launcher and GOG Galaxy update the games they installed when they are open. Xbox / Game Pass games update from the Microsoft Store."] = "Steam, Epic Games Launcher e GOG Galaxy aggiornano i giochi che hanno installato quando sono aperti. I giochi Xbox / Game Pass si aggiornano dal Microsoft Store.",
        ["Microsoft Store updates"] = "Aggiornamenti del Microsoft Store",
        ["Checking…"] = "Controllo…",
        ["Every game Hybrid Launcher downloaded is up to date."] = "Tutti i giochi scaricati da Hybrid Launcher sono aggiornati.",
        ["{0} update(s) started in Downloads."] = "{0} aggiornamenti avviati in Download.",
        ["Updating"] = "Aggiornamento",
        ["Preparing the update"] = "Preparazione dell'aggiornamento",
        ["Updated"] = "Aggiornato",
        ["{0} is updating. It can start once the update in Downloads is done."] = "{0} si sta aggiornando. Potrà partire quando l'aggiornamento in Download sarà finito.",
        // ---- 0.23: Settings section headings in capitals, as the rest of the app ----
        ["LANGUAGE"] = "LINGUA",
        ["ICONS"] = "ICONE",
        ["GAME PAGE"] = "PAGINA DEL GIOCO",
        ["GRAPHICS"] = "GRAFICA",
        ["WINDOW"] = "FINESTRA",
        ["GAME PAGE TABS"] = "SCHEDE DELLA PAGINA DI GIOCO",
        ["LIBRARY"] = "LIBRERIA",
        ["GAME"] = "GIOCO",
        ["ACHIEVEMENTS"] = "OBIETTIVI",
        ["GAME DETECTION"] = "RILEVAMENTO DEI GIOCHI",
        ["DOWNLOADS AND DATA"] = "DOWNLOAD E DATI",
        ["CLOUD SAVES"] = "SALVATAGGI NEL CLOUD",
        ["WHERE THE SAVES GO"] = "DOVE VANNO I SALVATAGGI",
        ["COPIES AND SYNC"] = "COPIE E SINCRONIZZAZIONE",
        // ---- 0.19-0.21: cloud saves, friends, sign-ins, tour, pop-up placement ----
        ["A NAS, a USB drive, or a folder another sync app keeps."] = "Un NAS, una chiavetta USB o una cartella sincronizzata da un'altra app.",
        ["A box beside Play to change them quickly."] = "Una casella accanto a Gioca per cambiarli al volo.",
        ["A folder of your choice"] = "Una cartella a tua scelta",
        ["A small pop-up (where you choose, in the colours you choose) when Steam records a new achievement, while Hybrid Launcher is open. Steam games only for now; read from Steam's own files, nothing is sent anywhere. It shows over borderless / windowed games, not over exclusive full screen."] = "Un piccolo pop-up (dove vuoi, nei colori che vuoi) quando Steam registra un nuovo obiettivo, mentre Hybrid Launcher è aperto. Per ora solo giochi Steam; letto dai file di Steam, non viene inviato nulla. Appare sopra i giochi in finestra o senza bordi, non in schermo intero esclusivo.",
        ["Across"] = "Orizzontale",
        ["Add any OptiScaler.ini setting to the Quick Panel"] = "Aggiungi qualsiasi impostazione di OptiScaler.ini al Pannello rapido",
        ["Add its .exe, or a whole folder of games: each sub-folder becomes a game."] = "Aggiungi il suo .exe, o un'intera cartella di giochi: ogni sottocartella diventa un gioco.",
        ["Advanced users can type launch options here. Steam games start through Steam (-applaunch) with them; Epic, GOG and other games start their exe directly with them."] = "Gli utenti esperti possono scrivere qui le opzioni di avvio. I giochi Steam partono tramite Steam (-applaunch) con queste opzioni; Epic, GOG e gli altri avviano direttamente il loro exe.",
        ["Also games you own but have not installed"] = "Anche i giochi che possiedi ma non hai installato",
        ["Approve the sign-in in the Steam mobile app…"] = "Approva l'accesso nell'app Steam sul telefono…",
        ["Asking Steam…"] = "Chiedo a Steam…",
        ["Automatic"] = "Automatico",
        ["Automatic (Hybrid Launcher's match)"] = "Automatica (scelta da Hybrid Launcher)",
        ["Away"] = "Assente",
        ["Back to desktop"] = "Torna al desktop",
        ["Back to the top of the page"] = "Torna in cima alla pagina",
        ["Background opacity"] = "Opacità dello sfondo",
        ["Browse…"] = "Sfoglia…",
        ["Busy"] = "Occupato",
        ["Change the saves folder…"] = "Cambia la cartella dei salvataggi…",
        ["Chat in Steam"] = "Chatta su Steam",
        ["Checking {0}…"] = "Controllo {0}…",
        ["Choose a copy"] = "Scegli una copia",
        ["Choose the game's page"] = "Scegli la pagina del gioco",
        ["Choose the saves folder…"] = "Scegli la cartella dei salvataggi…",
        ["Choose…"] = "Scegli…",
        ["Click to fold or open"] = "Clicca per chiudere o aprire",
        ["Click, then press the new key (Esc to cancel)"] = "Clicca, poi premi il nuovo tasto (Esc per annullare)",
        ["Close"] = "Chiudi",
        ["Close (Esc)"] = "Chiudi (Esc)",
        ["Cloud"] = "Cloud",
        ["Cloud saves"] = "Salvataggi nel cloud",
        ["Possible causes: Windows asked for permission and the request was turned down."] = "Possibili cause: Windows ha chiesto l'autorizzazione e la richiesta è stata rifiutata.",
        ["Possible causes: a damaged download or archive. Try again; if it keeps failing, clear the cache in Settings → Storage."] = "Possibili cause: un download o un archivio danneggiato. Riprova; se continua a non riuscire, svuota la cache in Impostazioni → Archiviazione.",
        ["Possible causes: no internet connection, or the service is slow or down. Check your connection and try again in a few minutes."] = "Possibili cause: nessuna connessione a internet, oppure il servizio è lento o non disponibile. Controlla la connessione e riprova tra qualche minuto.",
        ["Possible causes: the cloud is full. Free some space there or turn off cloud saves for the games you do not need."] = "Possibili cause: il cloud è pieno. Libera spazio o disattiva i salvataggi nel cloud per i giochi che non ti servono.",
        ["Possible causes: the disk is full. Free some space and try again."] = "Possibili cause: il disco è pieno. Libera spazio e riprova.",
        ["Possible causes: the file is in use or protected. Close the game and its launcher, let OneDrive or your antivirus finish with the folder, and check Controlled folder access in Windows Security."] = "Possibili cause: il file è in uso o protetto. Chiudi il gioco e il suo launcher, lascia che OneDrive o l'antivirus finiscano con la cartella e controlla Accesso alle cartelle controllato in Sicurezza di Windows.",
        ["Possible causes: the folder needs administrator rights (Program Files, say). Move the game or Hybrid Launcher to a folder of yours."] = "Possibili cause: la cartella richiede i diritti di amministratore (Programmi, per esempio). Sposta il gioco o Hybrid Launcher in una tua cartella.",
        ["Possible causes: the folder or file is gone. A drive may be disconnected, a cloud app (OneDrive, Google Drive) closed, or the game moved or uninstalled."] = "Possibili cause: la cartella o il file non c'è più. Un disco potrebbe essere scollegato, un'app cloud (OneDrive, Google Drive) chiusa, o il gioco spostato o disinstallato.",
        ["Possible causes: the game, its launcher or a cloud app is still using the file. Close them and try again."] = "Possibili cause: il gioco, il suo launcher o un'app cloud stanno ancora usando il file. Chiudili e riprova.",
        ["Possible causes: the service limits how often it can be asked (GitHub allows 60 checks an hour). Wait a while and try again."] = "Possibili cause: il servizio limita le richieste (GitHub ne consente 60 all'ora). Aspetta un po' e riprova.",
        ["The saves of {0} are in {1} but not in {2} yet: {3} They go there at the next sync."] = "I salvataggi di {0} sono su {1} ma non ancora su {2}: {3} Ci arrivano alla prossima sincronizzazione.",
        ["Troubleshooting"] = "Risoluzione dei problemi",
        ["not in {0} yet: {1}"] = "non ancora su {0}: {1}",
        ["Cloud saves go to {0} ({1}) now."] = "I salvataggi ora vanno su {0} ({1}).",
        ["Cloud saves go to {0} now."] = "I salvataggi ora vanno su {0}.",
        ["Cloud saves settings"] = "Impostazioni dei salvataggi nel cloud",
        ["Cloud saves with {0}."] = "Salvataggi nel cloud con {0}.",
        ["Cloud saves with {0}. Last upload: {1}, from {2}."] = "Salvataggi nel cloud con {0}. Ultimo invio: {1}, da {2}.",
        ["Cloud saves: sync this game's saves with OneDrive, MEGA or a folder. Set it up in Settings → Cloud saves."] = "Salvataggi nel cloud: sincronizza i salvataggi di questo gioco con OneDrive, MEGA o una cartella. Si configura in Impostazioni → Salvataggi nel cloud.",
        ["Cloud: sent from {0} on {1}"] = "Cloud: inviati da {0} il {1}",
        ["Colours and themes, cloud saves with OneDrive or MEGA, achievement pop-ups and more are in Settings. The tour can be taken again from there."] = "Colori e temi, salvataggi nel cloud con OneDrive o MEGA, pop-up degli obiettivi e altro sono nelle Impostazioni. Da lì puoi anche rifare il tour.",
