        ["MEGA ended Hybrid Launcher's sign-in: sign in to MEGA again in Settings → Cloud saves."] = "MEGA ha chiuso l'accesso di Hybrid Launcher: accedi di nuovo a MEGA in Impostazioni → Salvataggi nel cloud.",
