        ["MEGA's sign-in page is open in your browser. Enter your e-mail and password there (and your two-factor code, if you use one); this window closes by itself."] = "La pagina di accesso a MEGA è aperta nel browser. Inserisci lì e-mail e password (e il codice a due fattori, se lo usi); questa finestra si chiude da sola.",
