        ["ReShade saves its settings when the game closes, which can undo a change made here now. Change them in ReShade's menu, or after closing the game."] = "ReShade salva le impostazioni quando il gioco si chiude, e potrebbe annullare una modifica fatta qui adesso. Cambiale dal menu di ReShade, o dopo aver chiuso il gioco.",
        ["ReShade settings"] = "Impostazioni di ReShade",
        ["ReShade.ini is made the first time the game runs with ReShade. Its settings show here then."] = "ReShade.ini viene creato la prima volta che il gioco parte con ReShade. Allora le impostazioni compariranno qui.",
