        ["Sign in to your launchers here to install the games you own and follow their downloads, all in one list."] = "Accedi qui ai tuoi launcher per installare i giochi che possiedi e seguirne i download, tutto in un'unica lista.",
        ["Sign in to {0}"] = "Accedi a {0}",
        ["Sign in to {0} in Hybrid Launcher: every game you own is listed, and Hybrid Launcher downloads and uninstalls them itself, without the launcher."] = "Accedi a {0} in Hybrid Launcher: ogni gioco che possiedi viene elencato, e Hybrid Launcher li scarica e disinstalla da solo, senza launcher.",
        ["Sign in with your MEGA account in your browser. Saves go to \"{0}\" in your Cloud Drive, end-to-end encrypted."] = "Accedi con il tuo account MEGA nel browser. I salvataggi vanno in \"{0}\" nel tuo Cloud Drive, cifrati end-to-end.",
