        ["Size of installation: {0}"] = "Dimensione dell'installazione: {0}",
        ["Skip tour"] = "Salta il tour",
        ["Smooth effects, the blurred reflection under the banner and videos that play by themselves. Turn it off on a slow or busy graphics card. Videos never play while a game is running."] = "Effetti fluidi, il riflesso sfocato sotto il banner e i video che partono da soli. Disattivala su una scheda grafica lenta o occupata. I video non partono mai mentre un gioco è in esecuzione.",
