        ["Take the tour again"] = "Rifai il tour",
        ["That code was not right. Try the new one."] = "Quel codice non era giusto. Prova quello nuovo.",
        ["That folder holds much more than one game's saves: pick the game's own saves folder."] = "Quella cartella contiene molto più dei salvataggi di un gioco: scegli la cartella dei salvataggi del gioco.",
        ["The Global Quick Panel, shared by every game set to Global."] = "Il Pannello rapido globale, condiviso da tutti i giochi impostati su Globale.",
        ["The Steam store could not be reached. Automatic and No store page still work."] = "Impossibile raggiungere lo store di Steam. Automatica e Nessuna pagina dello store funzionano comunque.",
        ["The Steam store lists nothing for this name."] = "Lo store di Steam non trova nulla con questo nome.",
        ["The account's library came back empty: showing what the launcher keeps on this PC."] = "La libreria dell'account è vuota: mostro ciò che il launcher tiene su questo PC.",
        ["The account's library did not load ({0}): showing what the launcher keeps on this PC."] = "La libreria dell'account non si è caricata ({0}): mostro ciò che il launcher tiene su questo PC.",
        ["The cloud check failed, {0} starts with the saves on this PC: {1}"] = "Il controllo del cloud non è riuscito, {0} parte con i salvataggi di questo PC: {1}",
        ["The cloud has no saves for this game yet."] = "Il cloud non ha ancora salvataggi per questo gioco.",
        ["The cloud is not available."] = "Il cloud non è disponibile.",
        ["The cloud's saves are on this PC now."] = "I salvataggi del cloud ora sono su questo PC.",
        ["The cloud's saves are on this PC now; the ones here are in Hybrid Launcher's backups."] = "I salvataggi del cloud ora sono su questo PC; quelli di prima sono nei backup di Hybrid Launcher.",
        ["The cover size and the look stay as they are."] = "La dimensione delle copertine e l'aspetto restano come sono.",
        ["The download stopped, but its folder could not be deleted: {0}"] = "Il download si è fermato, ma la sua cartella non è stata eliminata: {0}",
        ["The download stops and its folder is deleted."] = "Il download si ferma e la sua cartella viene eliminata.",
        ["The exe that starts the game; mods go next to it."] = "L'exe che avvia il gioco; le mod vanno accanto a lui.",
        ["The few tips shown at the first start: where your games, the library, downloads and settings are."] = "I pochi suggerimenti mostrati al primo avvio: dove sono i tuoi giochi, la libreria, i download e le impostazioni.",
        ["The game"] = "Il gioco",
        ["The game is running"] = "Il gioco è in esecuzione",
        ["The game's page"] = "La pagina del gioco",
        ["The information on this page (trailer, description, reviews, wikis) follows the page you pick. The game still starts the same way."] = "Le informazioni di questa pagina (trailer, descrizione, recensioni, wiki) seguono la pagina che scegli. Il gioco si avvia comunque allo stesso modo.",
        ["The name you sign in with, not your profile name"] = "Il nome con cui accedi, non il nome del profilo",
        ["The older copy is on this PC now."] = "La copia precedente ora è su questo PC.",
        ["The page chosen before"] = "La pagina scelta prima",
        ["The parts of the banner and the launch bar shown for this game. Parts hidden for every game are changed in Settings."] = "Le parti del banner e della barra di avvio mostrate per questo gioco. Quelle nascoste per tutti i giochi si cambiano nelle Impostazioni.",
        ["The saves folder is larger than {0}: it is not synced. Check the folder in the game's cloud menu."] = "La cartella dei salvataggi supera {0}: non viene sincronizzata. Controlla la cartella nel menu cloud del gioco.",
        ["The saves of {0} changed on this PC and in the cloud since the last sync. Which ones should Hybrid Launcher keep? The other copy is not lost: it stays in the cloud's history or in Hybrid Launcher's backups."] = "I salvataggi di {0} sono cambiati sia su questo PC che nel cloud dall'ultima sincronizzazione. Quali deve tenere Hybrid Launcher? L'altra copia non va persa: resta nella cronologia del cloud o nei backup di Hybrid Launcher.",
        ["The saves of {0} could not be sent: {1}"] = "Impossibile inviare i salvataggi di {0}: {1}",
        ["Cloud not reachable"] = "Cloud non raggiungibile",
        ["{0} did not answer in time."] = "{0} non ha risposto in tempo.",
        ["Restore an older copy (reading the cloud…)"] = "Ripristina una copia precedente (lettura del cloud…)",
        ["Stop using this folder and forget it. The saves already in it stay there."] = "Non usare più questa cartella e dimenticala. I salvataggi già presenti restano lì.",
        ["The folder is no longer used for cloud saves."] = "La cartella non viene più usata per i salvataggi nel cloud.",
        ["MEGA did not answer in time: check the connection, the saves go up at the next sync."] = "MEGA non ha risposto in tempo: controlla la connessione, i salvataggi verranno inviati alla prossima sincronizzazione.",
        ["Hybrid Launcher cannot write in \"{0}\": pick a folder inside it."] = "Hybrid Launcher non può scrivere in \"{0}\": scegli una cartella al suo interno.",
        ["The saves on this PC are replaced by the cloud's copy. They are zipped into Hybrid Launcher's backups first."] = "I salvataggi di questo PC vengono sostituiti dalla copia del cloud. Prima vengono compressi nei backup di Hybrid Launcher.",
        ["The saves on this PC are replaced by the copy of {0}. They are zipped into Hybrid Launcher's backups first, and the restored copy goes up after you play."] = "I salvataggi di questo PC vengono sostituiti dalla copia del {0}. Prima vengono compressi nei backup di Hybrid Launcher, e la copia ripristinata va su dopo la partita.",
        ["The sign-in page could not open (Microsoft Edge WebView2 is needed): {0}"] = "Impossibile aprire la pagina di accesso (serve Microsoft Edge WebView2): {0}",
        ["The store page its art, overview and wiki come from. Pick another when Hybrid Launcher matched the wrong game."] = "La pagina dello store da cui vengono immagini, descrizione e wiki. Scegline un'altra se Hybrid Launcher ha abbinato il gioco sbagliato.",
        ["This PC's saves are in the cloud now; the cloud's are kept in its history."] = "I salvataggi di questo PC ora sono nel cloud; quelli del cloud restano nella sua cronologia.",
        ["This PC: last changed {0}"] = "Questo PC: ultima modifica {0}",
        ["This game's own Quick Panel: what you add or remove stays with this game."] = "Il Pannello rapido di questo gioco: ciò che aggiungi o togli resta a questo gioco.",
        ["This page is served by Hybrid Launcher on your PC. Your e-mail and password go straight to MEGA, once: Hybrid Launcher keeps only the session MEGA opens, encrypted for your Windows user, never the password."] = "Questa pagina è servita da Hybrid Launcher sul tuo PC. E-mail e password vanno direttamente a MEGA, una volta sola: Hybrid Launcher conserva solo la sessione aperta da MEGA, cifrata per il tuo utente Windows, mai la password.",
        ["This store's games install from its own app."] = "I giochi di questo store si installano dalla sua app.",
        ["Two-factor code"] = "Codice a due fattori",
        ["Type the code shown in the Steam mobile app."] = "Scrivi il codice mostrato nell'app Steam sul telefono.",
        ["Upscaler tags on the covers"] = "Etichette upscaler sulle copertine",
        ["Upscaler tags on the covers (DLSS, FSR, XeSS)"] = "Etichette upscaler sulle copertine (DLSS, FSR, XeSS)",
        ["Use"] = "Usa",
        ["Stop using"] = "Non usare più",
        // ---- 1.0: report a problem ----
        ["Report a problem"] = "Segnala un problema",
        ["Opens the bug form on GitHub with the version, your system and this session's log already filled in. Your user name, PC name and e-mail addresses are taken out first."] = "Apre il modulo di segnalazione su GitHub con versione, sistema e log di questa sessione già compilati. Nome utente, nome del PC e indirizzi e-mail vengono tolti prima.",
        ["Report on GitHub"] = "Segnala su GitHub",
        ["1. GitHub opens the bug form (you need a GitHub account). The version, your system and the end of this session's log are already filled in."] = "1. GitHub apre il modulo di segnalazione (serve un account GitHub). Versione, sistema e la fine del log di questa sessione sono già compilati.",
        ["2. Explorer shows the whole log of this session and the one before: drag that file into the Log field."] = "2. Esplora file mostra il log completo di questa sessione e di quella prima: trascina quel file nel campo Log.",
        ["3. Write what happened and the steps that make it happen again, and add screenshots. Reports without them are closed."] = "3. Scrivi cosa è successo e i passi per farlo succedere di nuovo, e aggiungi screenshot. Le segnalazioni senza vengono chiuse.",
        ["Your Windows user name, the PC's name and e-mail addresses are taken out of the log first. Nothing is sent until you submit the form yourself."] = "Il nome utente di Windows, il nome del PC e gli indirizzi e-mail vengono prima tolti dal log. Non viene inviato nulla finché non invii tu il modulo.",
        ["Open GitHub"] = "Apri GitHub",
        // ---- 1.0: backup or replace when a mod goes in ----
        ["Ask each time"] = "Chiedi ogni volta",
        ["Install {0} in {1}"] = "Installa {0} in {1}",
        ["Files of the game that the mod replaces can be backed up first: uninstalling the mod then puts them back. Without a backup they are simply replaced, and uninstalling only removes the mod's files."] = "I file del gioco che la mod sostituisce possono essere copiati prima in un backup: disinstallando la mod tornano al loro posto. Senza backup vengono semplicemente sostituiti, e la disinstallazione rimuove solo i file della mod.",
        ["Back up and install"] = "Backup e installa",
        ["Just replace"] = "Sostituisci e basta",
        ["OptiScaler would replace it without a backup (as chosen in Settings → Features): uninstalling OptiScaler will not bring it back."] = "OptiScaler lo sostituirebbe senza backup (come scelto in Impostazioni → Funzionalità): disinstallando OptiScaler non tornerà.",
        ["Luma brings its own ReShade with add-on support and replaces {0}, without a backup (as chosen in Settings → Features). Your ReShade presets and shaders stay."] = "Luma porta il suo ReShade con supporto agli add-on e sostituisce {0}, senza backup (come scelto in Impostazioni → Funzionalità). I preset e gli shader di ReShade restano.",
        ["MODS"] = "MOD",
        // ---- 2.1: master switch of backups ----
        ["Back up the game files Hybrid Launcher replaces"] = "Fai un backup dei file del gioco che Hybrid Launcher sostituisce",
        ["When OptiScaler, Luma, DXVK, Ultra+ or a DLSS NR file goes into a game, the game's own files it replaces are kept first and uninstalling puts them back. Off: they are simply replaced, and uninstalling only removes the mod's files. ReShade's own installer keeps its own backups."] = "Quando OptiScaler, Luma, DXVK, Ultra+ o un file DLSS NR vengono installati in un gioco, i file del gioco che sostituiscono vengono prima conservati e la disinstallazione li rimette a posto. Disattivato: vengono semplicemente sostituiti, e la disinstallazione rimuove solo i file della mod. L'installer di ReShade tiene i suoi backup.",
        ["When to back up"] = "Quando fare il backup",
        ["At every install, or asked each time a mod goes into a game."] = "A ogni installazione, oppure chiedendolo ogni volta che una mod va in un gioco.",
        ["Always"] = "Sempre",
        ["Ask at each install"] = "Chiedi a ogni installazione",
        ["Use the cloud's"] = "Usa quelli del cloud",
        ["Use the cloud's saves now"] = "Usa ora i salvataggi del cloud",
        ["Use the cloud's saves?"] = "Usare i salvataggi del cloud?",
        ["Hybrid Launcher did not find the saves folder of {0}. Pick it in the cloud menu."] = "Hybrid Launcher non ha trovato la cartella dei salvataggi di {0}. Sceglila nel menu cloud.",
        ["Hybrid Launcher downloaded it: its folder is deleted for good."] = "L'ha scaricato Hybrid Launcher: la sua cartella viene eliminata definitivamente.",
        ["Hybrid Launcher forgets this account's sign-in. Games it installed stay."] = "Hybrid Launcher dimentica l'accesso a questo account. I giochi installati restano.",
        ["Hybrid Launcher is signed in to MEGA. You can close this tab."] = "Hybrid Launcher ha effettuato l'accesso a MEGA. Puoi chiudere questa scheda.",
        ["Hybrid Launcher looks the game up by its name"] = "Hybrid Launcher cerca il gioco per nome",
        ["Hybrid Launcher needs the permission to keep its saves in your Drive: sign in again and leave its box ticked."] = "Hybrid Launcher ha bisogno del permesso per tenere i salvataggi nel tuo Drive: accedi di nuovo e lascia la casella spuntata.",
        ["Hybrid Launcher removes it directly: Steam is closed for a moment if it is running (it would write the game back), the game folder and Steam's record of it are deleted, then Steam starts again."] = "Hybrid Launcher lo rimuove direttamente: se Steam è aperto viene chiuso un attimo (riscriverebbe il gioco), la cartella del gioco e il suo record in Steam vengono eliminati, poi Steam riparte.",
        ["Hybrid Launcher removes it directly: the Epic Games Launcher is closed if it is running, then the game folder and the launcher's records of it are deleted."] = "Hybrid Launcher lo rimuove direttamente: se l'Epic Games Launcher è aperto viene chiuso, poi la cartella del gioco e i record del launcher vengono eliminati.",
        ["Hybrid Launcher runs the game's own uninstaller silently: no GOG Galaxy needed."] = "Hybrid Launcher esegue in silenzio il disinstallatore del gioco: GOG Galaxy non serve.",
        ["Hybrid Launcher was not allowed to use your Drive."] = "Hybrid Launcher non è stato autorizzato a usare il tuo Drive.",
        ["Welcome to Hybrid Launcher"] = "Benvenuto in Hybrid Launcher",
        ["Welcome tour"] = "Tour di benvenuto",
        ["What the banner and the launch bar show in every game. To hide something for one game only, use ⋯ → Show on this page on its page."] = "Cosa mostrano il banner e la barra di avvio in ogni gioco. Per nascondere qualcosa in un solo gioco, usa ⋯ → Mostra in questa pagina dalla sua pagina.",
        ["Where the saves go"] = "Dove vanno i salvataggi",
        ["Which games are listed"] = "Quali giochi sono elencati",
        ["Which saves should stay?"] = "Quali salvataggi tenere?",
        ["Windows HDR turns on when the game starts and off when it closes."] = "L'HDR di Windows si accende quando il gioco parte e si spegne quando si chiude.",
        ["You're set"] = "Tutto pronto",
        ["Your MEGA storage or transfer quota is used up."] = "Hai esaurito lo spazio o la quota di trasferimento di MEGA.",
        ["Your e-mail and password go straight to MEGA, once. Hybrid Launcher keeps only the session MEGA opens, encrypted for your Windows user, never the password; signing out closes that session."] = "E-mail e password vanno direttamente a MEGA, una volta sola. Hybrid Launcher conserva solo la sessione aperta da MEGA, cifrata per il tuo utente Windows, mai la password; uscendo la sessione si chiude.",
        ["Your games from Steam, Epic, GOG and Xbox in one place, with OptiScaler, ReShade, RenoDX and Luma a click away. Here is a quick look around: six short tips."] = "I tuoi giochi di Steam, Epic, GOG e Xbox in un unico posto, con OptiScaler, ReShade, RenoDX e Luma a un clic. Ecco un giro veloce: sei brevi suggerimenti.",
        ["Your library"] = "La tua libreria",
        ["last played {0}"] = "ultima partita {0}",
        ["not installed"] = "non installato",
        ["your account"] = "il tuo account",
        ["your e-mail"] = "la tua e-mail",
        ["your folder"] = "la tua cartella",
        ["{0} change"] = "{0} modifica",
        ["{0} changes"] = "{0} modifiche",
        ["{0} files, {1} in the game folder (shaders and presets included)"] = "{0} file, {1} nella cartella del gioco (shader e preset inclusi)",
        ["{0} h played"] = "{0} h di gioco",
        ["{0} in the store"] = "{0} nello store",
        ["{0} is taking long to answer: {1} starts with the saves on this PC."] = "{0} ci mette troppo a rispondere: {1} parte con i salvataggi di questo PC.",
        ["{0} min played"] = "{0} min di gioco",
        ["{0} online of {1}"] = "{0} online su {1}",
        ["{0} parts of the page mention \"{1}\". Clear the search to see the whole page."] = "{0} parti della pagina parlano di \"{1}\". Cancella la ricerca per vedere tutta la pagina.",
        ["{0} sent, {1} brought here, {2} to decide."] = "{0} inviati, {1} portati qui, {2} da decidere.",
        ["Back to desktop (B)"] = "Torna al desktop (B)",
        ["Home"] = "Home",
        ["Menu"] = "Menu",
        ["No installed games yet. Install one from Downloads, or add one from the Library."] = "Ancora nessun gioco installato. Installane uno da Download, o aggiungine uno dalla Libreria.",
        ["Open the game's settings folder"] = "Apri la cartella delle impostazioni del gioco",
        ["Select"] = "Seleziona",
        ["Syncs: {0}"] = "Sincronizza: {0}",
        ["game settings"] = "impostazioni del gioco",
        ["saves"] = "salvataggi",

        // ---- feature picker (1.1) ----
        ["+{0}"] = "+{0}",
        ["12 / 40"] = "12 / 40",
        ["2 h 14 min"] = "2 h 14 min",
        ["A game's page with this choice: the launch bar and the tabs that stay."] = "La pagina di un gioco con questa scelta: la barra di avvio e le schede che restano.",
        ["Apply"] = "Applica",
        ["Change it any time in Settings → Features."] = "Puoi cambiarlo quando vuoi in Impostazioni → Funzioni.",
        ["Choose features"] = "Scegli le funzioni",
        ["Choose what you need"] = "Scegli cosa ti serve",
        ["Continue to the tour"] = "Continua con il tour",
        ["FEATURES"] = "FUNZIONI",
        ["FEATURES YOU USE"] = "FUNZIONI CHE USI",
        ["Fine-tune"] = "Rifinisci",
        ["Game has the overview, trailer and controller support. Drag a tab to reorder it; Settings → Features turns the mod tools on."] = "Gioco ha la panoramica, il trailer e il supporto controller. Trascina una scheda per riordinarla; Impostazioni → Funzioni attiva gli strumenti per le mod.",
        ["Game has the overview, trailer and controller support. OptiScaler installs in one click and swaps DLSS, FSR and XeSS. Drag a tab to reorder it."] = "Gioco ha la panoramica, il trailer e il supporto controller. OptiScaler si installa con un clic e scambia DLSS, FSR e XeSS. Trascina una scheda per riordinarla.",
        ["Game has the overview, trailer and controller support. Mods lists what is in the game folder and adds ReShade, RenoDX, Luma, DLSS 5 and DXVK. Drag a tab to reorder it."] = "Gioco ha la panoramica, il trailer e il supporto controller. Mod elenca cosa c'è nella cartella del gioco e aggiunge ReShade, RenoDX, Luma, DLSS 5 e DXVK. Trascina una scheda per riordinarla.",
        ["HDR · Smart"] = "HDR · Smart",
        ["Pick a starting point. What you leave out is only hidden: no tabs, buttons or pop-ups for it. Nothing is installed or removed, and Settings → Features brings it back any time."] = "Scegli un punto di partenza. Ciò che lasci fuori è solo nascosto: niente schede, pulsanti o pop-up. Non si installa né si rimuove nulla, e Impostazioni → Funzioni lo riporta quando vuoi.",
        ["Preview"] = "Anteprima",
        ["Turn single features on or off. A mix of your own works too."] = "Attiva o disattiva le singole funzioni. Va bene anche un mix tutto tuo.",
        ["WELCOME · STEP 1 OF 2"] = "BENVENUTO · PASSO 1 DI 2",
        ["What is left out is only hidden, nothing is uninstalled."] = "Ciò che è escluso è solo nascosto, nulla viene disinstallato.",
        ["Your game"] = "Il tuo gioco",
        ["Your own mix"] = "Il tuo mix",
        ["only the launcher"] = "solo il launcher",
        ["{0} · {1} of {2} features"] = "{0} · {1} di {2} funzioni",
        ["Everything"] = "Tutto",
        ["Every tool Hybrid Launcher has. Recommended if you are not sure."] = "Ogni strumento di Hybrid Launcher. Consigliato se non sei sicuro.",
        ["No achievements"] = "Niente obiettivi",
        ["Everything except trophies and achievement pop-ups."] = "Tutto tranne trofei e pop-up degli obiettivi.",
        ["OptiScaler + Mods"] = "OptiScaler + Mod",
        ["The OptiScaler and Mods tabs, nothing else on the game page."] = "Le schede OptiScaler e Mod, nient'altro nella pagina del gioco.",
        ["Only OptiScaler"] = "Solo OptiScaler",
        ["Upscaling and frame generation, the rest stays out of the way."] = "Upscaling e frame generation, il resto non si vede.",
        ["Just a launcher"] = "Solo un launcher",
        ["Your games and Play. No mod tools, no extras."] = "I tuoi giochi e Gioca. Niente strumenti per le mod, niente extra.",
        ["Swap DLSS, FSR and XeSS in one click, with frame generation and a quick panel."] = "Scambia DLSS, FSR e XeSS con un clic, con frame generation e un pannello rapido.",
        ["Every mod in the game folder, plus ReShade, RenoDX and Luma for HDR, DLSS 5 and DXVK."] = "Ogni mod nella cartella del gioco, più ReShade, RenoDX e Luma per l'HDR, DLSS 5 e DXVK.",
        ["Trophies on the game page, and pop-ups while you play."] = "Trofei nella pagina del gioco e pop-up mentre giochi.",
        ["Windows HDR turns on with the game and off when it closes."] = "L'HDR di Windows si accende con il gioco e si spegne quando si chiude.",
        ["Saves backed up to OneDrive, MEGA or a folder, with a history."] = "Salvataggi copiati su OneDrive, MEGA o una cartella, con una cronologia.",
        ["Known fixes, issues and settings for each game."] = "Correzioni, problemi e impostazioni noti per ogni gioco.",
        ["Notes & shortcuts"] = "Note e scorciatoie",
        ["Your own notes, quick-access folders and programs, and useful links per game."] = "Le tue note, cartelle e programmi ad accesso rapido e link utili per ogni gioco.",
        // 1.1: game names of your own, custom dlls.
        ["Rename this game"] = "Rinomina questo gioco",
        ["Custom DLLs"] = "DLL personalizzate",
        ["Add custom DLLs (copied into the shared folder)"] = "Aggiungi DLL personalizzate (copiate nella cartella condivisa)",
        ["DLL files…"] = "File DLL…",
        ["A folder laid out for OptiScaler…"] = "Una cartella già pronta per OptiScaler…",
        ["Open the shared custom DLLs folder"] = "Apri la cartella condivisa delle DLL personalizzate",
        ["No custom DLLs yet: add one"] = "Ancora nessuna DLL personalizzata: aggiungine una",
        ["DLSSG frame generation"] = "Frame generation DLSSG",
        ["Deletes the entry from Hybrid Launcher's shared custom DLLs folder. Every game that has it on loses it from its OptiScaler install."] = "Elimina la voce dalla cartella condivisa delle DLL personalizzate di Hybrid Launcher. Ogni gioco che la ha attiva la perde dalla sua installazione di OptiScaler.",
        ["Could not delete the entry"] = "Impossibile eliminare la voce",
        ["Could not add the custom DLLs"] = "Impossibile aggiungere le DLL personalizzate",
        ["No DLLs in this folder"] = "Nessuna dll in questa cartella",
        ["Use a name Windows accepts for a folder."] = "Usa un nome che Windows accetta per una cartella.",
        ["Add custom DLLs"] = "Aggiungi DLL personalizzate",
        ["Plain near-black background, soft silver accent (always dark)"] = "Sfondo quasi nero e semplice, accento argento tenue (sempre scuro)",
        ["Deep purple night with violet light (always dark)"] = "Notte viola profondo con luce violetta (sempre scuro)",
        ["A DLL's name must end in .dll and be one Windows accepts for a file."] = "Il nome di una dll deve finire con .dll ed essere accettato da Windows per un file.",
        ["A file with this name is already in that folder. Replace it?"] = "In quella cartella c'è già un file con questo nome. Sostituirlo?",
        ["A new entry…"] = "Una nuova voce…",
        ["A new name, or pick an entry to add to"] = "Un nome nuovo, o scegli una voce a cui aggiungerle",
        ["Add DLLs to this entry"] = "Aggiungi dll a questa voce",
        ["Add to {0}?"] = "Aggiungere a {0}?",
        ["Added to {0}: {1}."] = "Aggiunte a {0}: {1}.",
        ["An entry with this name is already in the shared folder. Its DLLs are added to it, replacing files with the same name."] = "Nella cartella condivisa c'è già una voce con questo nome. Le dll vengono aggiunte a quella, sostituendo i file con lo stesso nome.",
        ["Extra FSR, DLSS or DLSSG DLLs for OptiScaler (nightly). Turn an entry on for this game, then pick it by name in OptiScaler's upscaler or FG list."] = "Dll FSR, DLSS o DLSSG in più per OptiScaler (nightly). Attiva una voce per questo gioco, poi sceglila per nome nella lista degli upscaler o della FG di OptiScaler.",
        ["Could not change the custom DLLs"] = "Impossibile modificare le DLL personalizzate",
        ["Could not rename the entry"] = "Impossibile rinominare la voce",
        ["DLSS upscaler (NGX runtime)"] = "Upscaler DLSS (runtime NGX)",
        ["DX12 upscaler list"] = "lista upscaler DX12",
        ["Delete the entry (from the shared folder and from every game that uses it)"] = "Elimina la voce (dalla cartella condivisa e da ogni gioco che la usa)",
        ["Delete the file"] = "Elimina il file",
        ["Deletes it from {0} in the shared folder and from every game that has {0} on."] = "Lo elimina da {0} nella cartella condivisa e da ogni gioco che ha {0} attiva.",
        ["Dlls: the name each gets and what it is"] = "Dll: il nome di ciascuna e cosa è",
        ["Entry (OptiScaler's menu shows this name)"] = "Voce (il menu di OptiScaler mostra questo nome)",
        ["FFX upscaler, DX12"] = "Upscaler FFX, DX12",
        ["FFX upscaler, Vulkan"] = "Upscaler FFX, Vulkan",
        ["FG Nvngx list"] = "lista FG Nvngx",
        ["Give the entry a name Windows accepts for a folder."] = "Dai alla voce un nome che Windows accetta per una cartella.",
        ["Kind"] = "Tipo",
        ["Move to"] = "Sposta in",
        ["Name the entry"] = "Dai un nome alla voce",
        ["New entry"] = "Nuova voce",
        ["Not a DLL: copied along with the others"] = "Non è una dll: viene copiata insieme alle altre",
        ["Not a valid name"] = "Nome non valido",
        ["An entry is a folder in OptiScaler's custom folder"] = "Una voce è una cartella nella cartella custom di OptiScaler",
        ["On for this game: copied into its OptiScaler folder"] = "Attiva per questo gioco: copiata nella sua cartella di OptiScaler",
        ["One entry can hold an FFX upscaler for DX12 and Vulkan, a DLSS runtime and a DLSSG replacement: OptiScaler lists each under the entry's name. A DLL can have any name; when a folder holds more than one, OptiScaler loads the standard name (amd_fidelityfx_upscaler_dx12.dll, amd_fidelityfx_upscaler_vk.dll, nvngx.dll, nvngx_dlssg.dll) and the others are there for it to load."] = "Una voce può contenere un upscaler FFX per DX12 e Vulkan, un runtime DLSS e un sostituto DLSSG: OptiScaler li elenca tutti col nome della voce. Una dll può avere qualsiasi nome; se una cartella ne ha più di una, OptiScaler carica quella col nome standard (amd_fidelityfx_upscaler_dx12.dll, amd_fidelityfx_upscaler_vk.dll, nvngx.dll, nvngx_dlssg.dll) e le altre servono a lei.",
        ["OptiScaler lists it as \"{0}\" in: {1}"] = "OptiScaler la elenca come \"{0}\" in: {1}",
        ["OptiScaler loads this DLL"] = "OptiScaler carica questa dll",
        ["OptiScaler loads {0} from this folder; this one is there for it to load"] = "OptiScaler carica {0} da questa cartella; questa serve a lei",
        ["Pick a folder with DLLs in it, or one with ffx, ffx_vk, dlss or dlssg folders inside as OptiScaler's custom folder has."] = "Scegli una cartella con delle dll, oppure una con dentro le cartelle ffx, ffx_vk, dlss o dlssg come la cartella custom di OptiScaler.",
        ["Pick DLLs, name them and say what they are"] = "Scegli delle dll, dai loro un nome e indica cosa sono",
        ["Picked: {0}"] = "Scelta: {0}",
        ["Rename the entry"] = "Rinomina la voce",
        ["Rename the entry (the name OptiScaler's menu shows)"] = "Rinomina la voce (il nome che mostra il menu di OptiScaler)",
        ["Rename the file"] = "Rinomina il file",
        ["Rename the file…"] = "Rinomina il file…",
        ["Rename, change kind, move to another entry or delete"] = "Rinomina, cambia tipo, sposta in un'altra voce o elimina",
        ["Replace files?"] = "Sostituire i file?",
        ["That name is taken"] = "Nome già usato",
        ["There is already an entry called {0}. Move the DLLs into it instead, from each DLL's menu."] = "Esiste già una voce chiamata {0}. Sposta invece le dll in quella, dal menu di ogni dll.",
        ["Two DLLs of the same kind have the same name."] = "Due dll dello stesso tipo hanno lo stesso nome.",
        ["Vulkan upscaler list"] = "lista upscaler Vulkan",
        ["\"{0}\" is not a dll file name."] = "\"{0}\" non è un nome di file dll.",
        ["{0} already has: {1}. Replace them?"] = "{0} ha già: {1}. Sostituirli?",
        ["{0} is now {1}."] = "{0} ora è {1}.",
        ["{0} moved to {1} ({2})."] = "{0} spostata in {1} ({2}).",
        ["Rename (only in Hybrid Launcher: the folder keeps its name)"] = "Rinomina (solo in Hybrid Launcher: la cartella mantiene il suo nome)",
        ["Installed mods and their versions (top left of the banner)"] = "Mod installate e loro versioni (in alto a sinistra nel banner)",
        ["{0} {1}: open its tab"] = "{0} {1}: apri la sua scheda",
        ["nightly"] = "nightly",
        ["beta"] = "beta",
        ["this build only"] = "solo in questa build",
        ["This build adds {0} setting of its own: the cards marked \"this build only\"."] = "Questa build aggiunge {0} impostazione sua: le schede segnate \"solo in questa build\".",
        ["This build adds {0} settings of its own: the cards marked \"this build only\"."] = "Questa build aggiunge {0} impostazioni sue: le schede segnate \"solo in questa build\".",
        ["Update automatically"] = "Aggiorna automaticamente",
        ["Notify me of new versions"] = "Avvisami delle nuove versioni",
        ["In every game: a newer version found in the background goes in by itself, your settings kept."] = "In ogni gioco: una versione più nuova trovata in background si installa da sola, mantenendo le tue impostazioni.",
        ["In every game: a Windows notification when a newer version of an Ultra+ mod you have comes out."] = "In ogni gioco: una notifica di Windows quando esce una versione più nuova di una mod Ultra+ che hai.",
        ["What the banner and the launch bar show in every game. To hide something for one game only, use the gear beside Play → Customization on its page."] = "Cosa mostrano il banner e la barra di avvio in ogni gioco. Per nascondere qualcosa in un solo gioco, usa l'ingranaggio accanto a Gioca → Personalizzazione nella sua pagina.",
        ["Installed as {0}  ·  {1:yyyy-MM-dd HH:mm}"] = "Installato come {0}  ·  {1:yyyy-MM-dd HH:mm}",
        ["DLSS NR model file included"] = "file del modello DLSS NR incluso",
