        ["Storing the file…"] = "Salvataggio del file…",
        ["Builds with DLSS 5 neural rendering need NVIDIA's {0} beside them. Turn this on and pick yours once: every install that needs it gets it."] = "Le build con il neural rendering di DLSS 5 hanno bisogno del {0} di NVIDIA accanto. Attiva questa opzione e scegli il tuo una volta: ogni installazione che ne ha bisogno lo riceve.",
        ["{0} {1} ({2}) is kept by Hybrid Launcher. {3}"] = "{0} {1} ({2}) è conservato da Hybrid Launcher. {3}",
        ["It goes into every install whose build needs it; uninstalling takes it out."] = "Viene messo in ogni installazione la cui build ne ha bisogno; disinstallando viene tolto.",
        ["Off: installs don't get it."] = "Disattivato: le installazioni non lo ricevono.",
        ["{0} {1} stored: forks and custom builds that need it get it when installed."] = "{0} {1} salvato: i fork e le build personalizzate che ne hanno bisogno lo ricevono all'installazione.",
        ["Could not store the DLSS NR model file"] = "Impossibile salvare il file del modello DLSS NR",
        ["{0} is not NVIDIA's DLSS NR runtime (its version info does not say DLSSNR)."] = "{0} non è il runtime DLSS NR di NVIDIA (le sue informazioni di versione non dicono DLSSNR).",
        ["Adding the DLSS NR model file"] = "Aggiunta del file del modello DLSS NR",
        ["This build uses DLSS 5 neural rendering: your {0} goes in with it."] = "Questa build usa il neural rendering di DLSS 5: il tuo {0} viene installato con lei.",
