        ["This game only. It follows On globally until you change it here"] = "Solo questo gioco. Segue Attivo ovunque finché non lo cambi qui",
        ["It is in this game's OptiScaler install."] = "È nell'installazione di OptiScaler di questo gioco.",
        ["This game's build doesn't need it."] = "La build di questo gioco non ne ha bisogno.",
        ["Builds with DLSS 5 neural rendering need NVIDIA's {0} beside them. Tick a box and pick yours once: the installs that need it get it."] = "Le build con il neural rendering di DLSS 5 hanno bisogno accanto del {0} di NVIDIA. Spunta una casella e scegli il tuo una volta: le installazioni che ne hanno bisogno lo ricevono.",
