        ["Background saver"] = "Risparmio in secondo piano",
        ["When another window is in front, Hybrid Launcher rests: moving clips and muted trailers pause, nothing is polled and Windows runs it in efficiency mode. It wakes up the moment you click it. Downloads keep full speed."] = "Quando un'altra finestra è in primo piano, Hybrid Launcher si riposa: le clip animate e i trailer senza audio vanno in pausa, niente viene controllato a intervalli e Windows lo esegue in modalità efficienza. Si risveglia appena ci clicchi. I download mantengono la piena velocità.",
