        ["The blur, reflections and clips stop while a game started from Hybrid Launcher is running, so they take no graphics power from it, and come back by themselves when it closes."] = "Sfocatura, riflessi e clip si fermano mentre è in esecuzione un gioco avviato da Hybrid Launcher, così non gli tolgono potenza grafica, e tornano da soli quando si chiude.",
