        ["They work together. Use one upscaler setup at a time: OptiScaler's or Ultra+'s."] = "Funzionano insieme. Usa una configurazione di upscaling alla volta: quella di OptiScaler o quella di Ultra+.",
        ["Try again"] = "Riprova",
