        ["Ultra+ is not installed in this game"] = "Ultra+ non è installato in questo gioco",
        ["Ultra+ loads UE4SS through dwmapi.dll: reinstall OptiScaler under another file name first (dxgi.dll works for most games)."] = "Ultra+ carica UE4SS tramite dwmapi.dll: reinstalla prima OptiScaler con un altro nome di file (dxgi.dll va bene per la maggior parte dei giochi).",
        ["Ultra+ loads through {0} in this game. Pick another OptiScaler file name in Setup options (dxgi.dll works for most games), then install."] = "In questo gioco Ultra+ si carica tramite {0}. Scegli un altro nome di file per OptiScaler nelle Opzioni di installazione (dxgi.dll va bene per la maggior parte dei giochi), poi installa.",
