        ["On the game's Ultra+ tab. Updating keeps your settings."] = "Nella scheda Ultra+ del gioco. Aggiornare mantiene le tue impostazioni.",
        ["{0} {1} is available"] = "{0} {1} è disponibile",
        ["Click to see what is new and update."] = "Clicca per vedere le novità e aggiornare.",
        ["DLSS NR model file picker (OptiScaler tab, forks and custom builds)"] = "Scelta del file del modello DLSS NR (scheda OptiScaler, fork e build personalizzate)",
        ["Hide this row for this game"] = "Nascondi questa riga per questo gioco",
        ["DLSS NR row hidden for this game. The game's gear shows it again, Settings → Appearance → Game page hides it in every game; files already set up keep working."] = "Riga DLSS NR nascosta per questo gioco. L'ingranaggio del gioco la rimostra, Impostazioni → Aspetto → Pagina del gioco la nasconde in tutti i giochi; i file già impostati continuano a funzionare.",
        ["WHAT YOU HEAR ABOUT"] = "DI COSA SENTI PARLARE",
        ["WHILE YOU PLAY"] = "MENTRE GIOCHI",
        ["Until I clear them"] = "Finché non le svuoto",
        ["{0} days"] = "{0} giorni",
        ["Keep them for"] = "Conservale per",
        ["Older notifications leave the list by themselves."] = "Le notifiche più vecchie escono dalla lista da sole.",
        ["Clear the list"] = "Svuota la lista",
        ["Notifications kept"] = "Notifiche conservate",
        ["None right now."] = "Nessuna al momento.",
        ["1 in the list."] = "1 nella lista.",
        ["{0} in the list."] = "{0} nella lista.",
        ["OptiScaler updates"] = "Aggiornamenti di OptiScaler",
        ["You follow no OptiScaler build. Turn on Get notified on updates in a game's OptiScaler tab, for Stable, Nightly or a fork."] = "Non segui nessuna build di OptiScaler. Attiva Avvisami degli aggiornamenti nella scheda OptiScaler di un gioco, per Stable, Nightly o un fork.",
        ["New versions of the builds you follow: {0}. Following is chosen in a game's OptiScaler tab."] = "Nuove versioni delle build che segui: {0}. Cosa seguire si sceglie nella scheda OptiScaler di un gioco.",
        ["Stop following all"] = "Smetti di seguirle tutte",
        ["Ultra+ updates"] = "Aggiornamenti di Ultra+",
        ["New Ultra+ versions for your games, and the ones installed by themselves. The pop-up is the same switch as Notify me of new versions on a game's Ultra+ tab."] = "Nuove versioni di Ultra+ per i tuoi giochi e quelle installate da sole. Il pop-up è lo stesso interruttore di Avvisami delle nuove versioni nella scheda Ultra+ di un gioco.",
        ["Hybrid Launcher updates"] = "Aggiornamenti di Hybrid Launcher",
        ["A newer version of the app. The blue Update button in the title bar shows it too; checking at start is in About."] = "Una versione più nuova dell'app. Lo mostra anche il pulsante blu Aggiorna nella barra del titolo; il controllo all'avvio è in Informazioni.",
        ["No pop-ups while a game runs"] = "Niente pop-up mentre un gioco è aperto",
        ["Windows pop-up"] = "Pop-up di Windows",
        ["Notification settings"] = "Impostazioni delle notifiche",
        ["Developed by LorenzoKy"] = "Sviluppato da LorenzoKy",
        // Settings → About: credits in one line (after 1.3.2).
        ["I make and own only Hybrid Launcher. Everything it downloads, runs, reads or links to belongs to its own authors and owners, who are not affiliated with this project."] = "Creo e possiedo solo Hybrid Launcher. Tutto ciò che scarica, esegue, legge o collega appartiene ai rispettivi autori e proprietari, che non sono affiliati a questo progetto.",
        ["Third-party software and credits"] = "Software di terze parti e riconoscimenti",
        ["I make and own only Hybrid Launcher. Everything it downloads, installs, runs, reads or links to (mods, tools, games, stores, services, fonts and libraries) belongs to its own authors and owners, under their own licenses and terms. None of them is affiliated with Hybrid Launcher or endorses it, and all trademarks belong to their owners. Looks inspired by consoles or stores are Hybrid Launcher's own drawings."] = "Creo e possiedo solo Hybrid Launcher. Tutto ciò che scarica, installa, esegue, legge o collega (mod, strumenti, giochi, store, servizi, font e librerie) appartiene ai rispettivi autori e proprietari, con le proprie licenze e condizioni. Nessuno di loro è affiliato a Hybrid Launcher né lo sostiene, e tutti i marchi appartengono ai rispettivi proprietari. Gli stili ispirati a console o store sono disegni di Hybrid Launcher.",
        ["Third-party software"] = "Software di terze parti",
        // Settings → About: third-party credits (1.3.2, no longer shown).
        ["OptiScaler, OptiPatcher and their setup script belong to the OptiScaler team; Hybrid Launcher downloads them from GitHub and runs them unchanged. OptiScaler forks belong to their own authors and install through their own setup script."] = "OptiScaler, OptiPatcher e il loro script di installazione appartengono al team di OptiScaler; Hybrid Launcher li scarica da GitHub e li esegue senza modifiche. I fork di OptiScaler appartengono ai loro autori e si installano con il loro script di installazione.",
        ["Luma"] = "Luma",
        ["Ultra+"] = "Ultra+",
        ["ReShade installers come from reshade.me and run unchanged; RenoDX mods come from their authors' GitHub pages or, for Nexus Mods files, from your own download; Luma comes from Filoppi's Luma Framework releases; Ultra+ comes from The Ultra Place. NVIDIA's DLSS files are never shipped: you pick your own copy."] = "Gli installer di ReShade arrivano da reshade.me e vengono eseguiti senza modifiche; le mod RenoDX arrivano dalle pagine GitHub dei loro autori o, per i file di Nexus Mods, dal tuo download; Luma arriva dalle release di Luma Framework di Filoppi; Ultra+ arriva da The Ultra Place. I file DLSS di NVIDIA non sono mai inclusi: scegli la tua copia.",
        ["Game information comes from PCGamingWiki, HowLongToBeat, Metacritic and the stores' public pages; SteamDB, Nexus Mods and the OptiScaler wiki are links only."] = "Le informazioni sui giochi arrivano da PCGamingWiki, HowLongToBeat, Metacritic e dalle pagine pubbliche degli store; SteamDB, Nexus Mods e la wiki di OptiScaler sono solo link.",
        ["Not affiliated with or endorsed by any of them, or by Valve, Epic Games, GOG, Microsoft, Sony Interactive Entertainment, AMD, NVIDIA or Intel. The PlayStation, Xbox, Steam, GOG and Epic Games \"Like\" pop-up looks are Hybrid Launcher's own drawings inspired by them, with its own logo and trophies. All trademarks belong to their owners."] = "Non affiliato né approvato da nessuno di loro, né da Valve, Epic Games, GOG, Microsoft, Sony Interactive Entertainment, AMD, NVIDIA o Intel. Gli stili dei pop-up \"Like\" PlayStation, Xbox, Steam, GOG ed Epic Games sono disegni propri di Hybrid Launcher ispirati a loro, con il suo logo e i suoi trofei. Tutti i marchi appartengono ai rispettivi proprietari.",
        ["Settings → Sounds: the Every achievement sound plays its own file again, not gold's."] = "Impostazioni → Suoni: il suono di Ogni obiettivo riproduce di nuovo il suo file, non quello dell'oro.",
        ["Settings → About, the README and the site credit every project Hybrid Launcher works with."] = "Impostazioni → Informazioni, il README e il sito citano ogni progetto con cui lavora Hybrid Launcher.",
        // Welcome to the new version (after an update).
        ["Welcome to {0} {1}"] = "Benvenuto in {0} {1}",
        ["Here is what's new in this version."] = "Ecco le novità di questa versione.",
        ["See everything that changed"] = "Vedi tutto ciò che è cambiato",
        ["Achievement pop-ups that look like a console's or a store's, with the game's own platinum and your own sounds."] = "Pop-up degli obiettivi con l'aspetto di una console o di uno store, con il platino del gioco e i tuoi suoni.",
        ["A Controller tab: give any action to any button, and a Home button that also opens the trophy you just earned."] = "Una scheda Controller: assegna qualsiasi azione a qualsiasi tasto, e un tasto Home che apre anche il trofeo appena ottenuto.",
        ["Search every setting from the box beside the Settings title."] = "Cerca qualsiasi impostazione dalla casella accanto al titolo Impostazioni.",
        ["Your play time is kept when you reinstall or move a game."] = "Il tuo tempo di gioco resta anche se reinstalli o sposti un gioco.",
        ["Epic games that 1.3.0 missed are found again, and Settings fits a 1080p window."] = "I giochi Epic che la 1.3.0 non trovava vengono trovati di nuovo, e le Impostazioni stanno in una finestra a 1080p.",
        ["If {0} has earned a place on your PC, you can buy me a slice of pizza."] = "Se {0} si è guadagnato un posto sul tuo PC, puoi offrirmi una fetta di pizza.",
        ["{0} is being installed or removed in {1}. Try again when it is done."] = "{0} è in corso di installazione o rimozione in {1}. Riprova quando ha finito.",
        ["NOTIFICATION LIST"] = "LISTA DELLE NOTIFICHE",
        ["Notifications button in the title bar"] = "Pulsante Notifiche nella barra del titolo",
        ["Beside Minimize: every notification is kept in its list, so one you missed can still be read."] = "Accanto a Riduci a icona: ogni notifica resta nella sua lista, così puoi leggere anche quelle perse.",
        ["Each source can be kept in the app's list, show a Windows pop-up, both, or neither."] = "Ogni fonte può restare nella lista dell'app, mostrare un pop-up di Windows, entrambe le cose o nessuna.",
        ["They wait in the app's list instead, so nothing jumps over the game."] = "Aspettano nella lista dell'app, così niente compare sopra il gioco.",
        ["In the app"] = "Nell'app",
        ["If Hybrid Launcher helps you, a slice of pizza on Ko-fi keeps it going. Code, releases and other projects are on GitHub."] = "Se Hybrid Launcher ti è utile, una fetta di pizza su Ko-fi lo fa andare avanti. Codice, versioni e altri progetti sono su GitHub.",
        ["Epic Games"] = "Epic Games",
        ["GOG Galaxy"] = "GOG Galaxy",
        ["Match the game's store"] = "Come lo store del gioco",
        ["Minimal"] = "Minimale",
        ["No game with achievements found"] = "Nessun gioco con obiettivi trovato",
        ["POP-UPS"] = "POP-UP",
        ["Pick a game"] = "Scegli un gioco",
        ["PlayStation 4 Like"] = "Stile PlayStation 4",
        ["Xbox Like"] = "Stile Xbox",
        ["Steam Like"] = "Stile Steam",
        ["GOG Like"] = "Stile GOG",
        ["Epic Games Like"] = "Stile Epic Games",
        ["PlayStation 4 Like (black)"] = "Stile PlayStation 4 (nero)",
        ["Sound volume"] = "Volume del suono",
        ["PlayStation 5 Like"] = "Stile PlayStation 5",
        ["Preview with a real game"] = "Anteprima con un gioco vero",
        ["Shows one of the game's real achievements (its name, picture and rarity) the same way an unlock would, in the look of its store when the look matches the store. Platinum shows the game's own platinum: its achievement for unlocking all the others. Nothing is unlocked."] = "Mostra uno degli obiettivi veri del gioco (nome, immagine e rarità) come apparirebbe uno sblocco, nello stile del suo store se lo stile è Come lo store del gioco. Platino mostra il platino del gioco: il suo obiettivo per sbloccare tutti gli altri. Non viene sbloccato nulla.",
        ["The pop-up of this game's platinum: its achievement for unlocking all the others"] = "Il pop-up del platino di questo gioco: il suo obiettivo per sbloccare tutti gli altri",
        ["The unlock pop-up goes back to how Hybrid Launcher ships: on, with the look, place, colours and sound it comes with."] = "Il pop-up degli sblocchi torna come in Hybrid Launcher appena installato: attivo, con stile, posizione, colori e suono predefiniti.",
        ["Which store's notification to imitate. “Match the game's store” uses the Steam, GOG, Epic or Xbox look of each game. Colour and background below apply to Hybrid Launcher and Minimal; the others keep their own colours."] = "Quale notifica imitare. «Come lo store del gioco» usa lo stile Steam, GOG, Epic o Xbox di ogni gioco. Colore e sfondo qui sotto valgono per Hybrid Launcher e Minimale; gli altri tengono i propri colori.",
        ["Which store's notification to imitate. “Match the game's store” uses the Steam, GOG, Epic or Xbox look of each game. Colour applies to Hybrid Launcher and Minimal. Background applies to those and to the PlayStation looks (Automatic keeps the console's own); the others keep their own colours."] = "Quale notifica imitare. «Come lo store del gioco» usa lo stile Steam, GOG, Epic o Xbox di ogni gioco. Il colore vale per Hybrid Launcher e Minimale. Lo sfondo vale per questi e per gli stili PlayStation (Automatico tiene quello della console); gli altri tengono i propri colori.",
        ["Which store's notification to imitate. “Match the game's store” uses the Steam, GOG, Epic or Xbox look of each game. Colour and background below apply to Hybrid Launcher and Minimal, and the PlayStation looks have a background choice of their own; the others keep their own colours."] = "Quale notifica imitare. «Come lo store del gioco» usa lo stile Steam, GOG, Epic o Xbox di ogni gioco. Colore e sfondo qui sotto valgono per Hybrid Launcher e Minimale, e gli stili PlayStation hanno una scelta di sfondo tutta loro; gli altri tengono i propri colori.",
        ["PlayStation background"] = "Sfondo PlayStation",
        // Welcome to 1.3.3.
        ["The mouse wheel glides: the game page, the library, Settings and the game list scroll smoothly, and answer at once."] = "La rotella del mouse scorre fluida: la pagina del gioco, la libreria, le Impostazioni e l'elenco dei giochi scorrono in modo continuo e rispondono subito.",
        ["Vsync, always on: everything the app moves by itself follows your display's refresh, at any refresh rate."] = "Vsync, sempre attivo: tutto ciò che l'app muove da sola segue l'aggiornamento del tuo schermo, a qualsiasi frequenza.",
        ["Every state of the Play button looks like Play: same size, nothing squeezed."] = "Ogni stato del pulsante Gioca è come Gioca: stessa dimensione, niente di schiacciato.",
        ["The PlayStation 5 and 4 Like pop-ups can have a light, dark or coloured background. The console's own stays the default."] = "I pop-up PlayStation 5 e 4 Like possono avere uno sfondo chiaro, scuro o colorato. Quello della console resta il predefinito.",
        ["Settings → About has the same short third-party note as the README."] = "Impostazioni → Informazioni ha la stessa breve nota sul software di terze parti del README.",
        ["The PlayStation 5 and 4 looks: the console's own background, or a light, dark or coloured one."] = "Gli stili PlayStation 5 e 4: lo sfondo della console, oppure uno chiaro, scuro o colorato.",
        ["Original"] = "Originale",
        ["Trophy's metal"] = "Metallo del trofeo",
        ["Colour picked above"] = "Colore scelto sopra",
        ["{0} has no achievements that can be read on this PC."] = "{0} non ha obiettivi leggibili su questo PC.",
        ["Game page cache"] = "Cache delle pagine dei giochi",
        ["Covers, banners, screenshots and the store, wiki and review data of each game, kept on disk so pages open at once, also offline. Past this size the pictures used least recently go first."] = "Copertine, banner, screenshot e i dati di store, wiki e recensioni di ogni gioco, tenuti su disco perché le pagine si aprano subito, anche offline. Oltre questa dimensione se ne vanno prima le immagini usate meno di recente.",
        ["{0} GB"] = "{0} GB",
        ["{0} in use now."] = "{0} in uso ora.",
        ["Game page cache emptied: {0} freed. Pages fetch what they show again."] = "Cache delle pagine svuotata: liberati {0}. Le pagine scaricano di nuovo ciò che mostrano.",
        ["Could not empty the cache"] = "Impossibile svuotare la cache",
        ["A picture of the screen the game is on with each unlock, saved in {0} under the game's name."] = "Un'immagine dello schermo del gioco a ogni sblocco, salvata in {0} con il nome del gioco.",
        ["A short double rumble on a connected Xbox-compatible controller with each unlock."] = "Una breve doppia vibrazione sul controller compatibile Xbox collegato a ogni sblocco.",
        ["ACHIEVEMENT PROGRESS {0}"] = "PROGRESSI OBIETTIVO {0}",
        ["Achievement progress {0}"] = "Progressi obiettivo {0}",
        ["An achievement with steps (kill 100 enemies, collect 50 items) shows how far along it is each time it passes the next mark. Local achievements and Xbox give the steps."] = "Un obiettivo a passi (sconfiggi 100 nemici, raccogli 50 oggetti) mostra a che punto sei ogni volta che supera la tacca successiva. Gli obiettivi locali e Xbox danno i passi.",
        ["Clear the unlock history?"] = "Svuotare la cronologia degli sblocchi?",
        ["Controller vibration"] = "Vibrazione del controller",
        ["Every unlock Hybrid Launcher shows is written down with its date, game and screenshot. Nothing yet."] = "Ogni sblocco mostrato da Hybrid Launcher viene annotato con data, gioco e screenshot. Ancora niente.",
        ["Every {0}%"] = "Ogni {0}%",
        ["Export failed"] = "Esportazione non riuscita",
        ["Export the list"] = "Esporta l'elenco",
        ["Export the list (CSV or JSON)"] = "Esporta l'elenco (CSV o JSON)",
        ["Export…"] = "Esporta…",
        ["Folders read for local achievements now: {0}. Add one that holds a folder per game (named by its Steam app id), or a single game's folder with its achievement file."] = "Cartelle lette ora per gli obiettivi locali: {0}. Aggiungine una con una cartella per gioco (con il nome dell'app id di Steam), o la cartella di un singolo gioco con il suo file degli obiettivi.",
        ["Keep an unlock history"] = "Tieni una cronologia degli sblocchi",
        ["Microsoft account for Xbox"] = "Account Microsoft per Xbox",
        ["Microsoft refused the sign-in ({0})."] = "Microsoft ha rifiutato l'accesso ({0}).",
        ["More folders"] = "Altre cartelle",
        ["Open the screenshot"] = "Apri lo screenshot",
        ["Optional. With your Microsoft account, Xbox achievements are always current and their unlocks pop up while you play. Sign in on Microsoft's own page: Hybrid Launcher never sees your password."] = "Facoltativo. Con il tuo account Microsoft gli obiettivi Xbox sono sempre aggiornati e i loro sblocchi compaiono mentre giochi. L'accesso avviene sulla pagina di Microsoft: Hybrid Launcher non vede mai la tua password.",
        ["Platinum: every achievement unlocked"] = "Platino: tutti gli obiettivi sbloccati",
        ["Play time, the mods installed (Opti, RS, RDX, U+), upscaler tags and achievements on each cover. Off shows the bare cover art. Also in the library's Filters."] = "Tempo di gioco, mod installate (Opti, RS, RDX, U+), etichette degli upscaler e obiettivi su ogni copertina. Disattivato mostra la copertina e basta. Anche nei Filtri della libreria.",
        ["Progress pop-ups"] = "Pop-up dei progressi",
        ["Progress: {0:0.##} of {1:0.##}"] = "Progressi: {0:0.##} di {1:0.##}",
        ["Progress: {0:0}%"] = "Progressi: {0:0}%",
        ["Progress: {0}"] = "Progressi: {0}",
        ["ReShade {0} is installed, loaded by OptiScaler"] = "ReShade {0} è installato, caricato da OptiScaler",
        ["RenoDX is installed: {0}"] = "RenoDX è installato: {0}",
        ["Screenshot"] = "Screenshot",
        ["Screenshot folder"] = "Cartella degli screenshot",
        ["Show Xbox unlocks with Hybrid Launcher's pop-up (the Xbox Game Bar may show its own too)."] = "Mostra gli sblocchi Xbox con il pop-up di Hybrid Launcher (la Xbox Game Bar può mostrare anche il suo).",
        ["Sign in to Xbox first (Settings → Achievements)."] = "Prima accedi a Xbox (Impostazioni → Obiettivi).",
        ["Sign in…"] = "Accedi…",
        ["Signed in as {0}. While an Xbox game runs its achievements are checked every 40 seconds and new unlocks pop up."] = "Accesso come {0}. Mentre un gioco Xbox è aperto i suoi obiettivi vengono controllati ogni 40 secondi e i nuovi sblocchi compaiono.",
        ["Signed in to Xbox as {0}."] = "Accesso a Xbox come {0}.",
        ["Tags on the covers"] = "Etichette sulle copertine",
        ["Tags on the covers (play time, mods, upscalers, achievements)"] = "Etichette sulle copertine (tempo di gioco, mod, upscaler, obiettivi)",
        ["The picture shows the pop-up too. Off: it is taken just before the pop-up appears."] = "L'immagine mostra anche il pop-up. Disattivato: viene scattata appena prima che compaia.",
        ["Try"] = "Prova",
        ["Ultra+ is installed"] = "Ultra+ è installato",
        ["Unlock history"] = "Cronologia degli sblocchi",
        ["Unlock history saved to {0}."] = "Cronologia degli sblocchi salvata in {0}.",
        ["With the pop-up"] = "Con il pop-up",
        ["Xbox achievements"] = "Obiettivi Xbox",
        ["Xbox and PC Game Pass games' achievements, read from the Xbox app on this PC. The Xbox app is not set up here yet: open it once and sign in."] = "Gli obiettivi dei giochi Xbox e PC Game Pass, letti dall'app Xbox di questo PC. L'app Xbox non è ancora configurata: aprila una volta ed esegui l'accesso.",
        ["Xbox and PC Game Pass games' achievements, read from the Xbox app on this PC: no sign-in needed. They are as fresh as the last time the Xbox app showed the game; sign in below for live ones."] = "Gli obiettivi dei giochi Xbox e PC Game Pass, letti dall'app Xbox di questo PC: nessun accesso richiesto. Sono aggiornati all'ultima volta che l'app Xbox ha mostrato il gioco; accedi qui sotto per averli in tempo reale.",
        ["Xbox pop-ups while playing"] = "Pop-up Xbox mentre giochi",
        ["Xbox refused the sign-in ({0})."] = "Xbox ha rifiutato l'accesso ({0}).",
        ["{0} of {1} G"] = "{0} di {1} G",
        ["{0} unlocks are removed from Hybrid Launcher's history. Your achievements and screenshots stay."] = "{0} sblocchi vengono tolti dalla cronologia di Hybrid Launcher. I tuoi obiettivi e gli screenshot restano.",
        ["{0} unlocks so far, the latest {1:d MMM yyyy}. Export it as CSV (a spreadsheet) or JSON."] = "{0} sblocchi finora, l'ultimo il {1:d MMM yyyy}. Esportala come CSV (un foglio di calcolo) o JSON.",
        ["ON UNLOCK"] = "ALLO SBLOCCO",
        ["UNLOCK HISTORY"] = "CRONOLOGIA DEGLI SBLOCCHI",
        ["Choose a picture…"] = "Scegli un'immagine…",
        ["Cover"] = "Copertina",
        ["From OptiScaler.ini:"] = "Da OptiScaler.ini:",
        ["Recent games"] = "Giochi recenti",
        ["Remove them"] = "Rimuovile",
        ["Remove {0} ({1})"] = "Rimuovi {0} ({1})",
        ["The store's cover. Choose a picture to use your own (2:3, like 600 × 900, fits best)."] = "La copertina dello store. Scegli un'immagine per usarne una tua (2:3, come 600 × 900, è la più adatta).",
        ["Use the store's"] = "Usa quella dello store",
        ["Your own picture. A portrait picture (2:3, like 600 × 900) fits the tile best."] = "La tua immagine. Un'immagine verticale (2:3, come 600 × 900) è la più adatta al riquadro.",
        ["{0} older nightly builds that no game uses take {1}. The newest three stay."] = "{0} build nightly più vecchie che nessun gioco usa occupano {1}. Le tre più recenti restano.",
        ["The upscaler OptiScaler uses in DirectX 12 games."] = "L'upscaler che OptiScaler usa nei giochi DirectX 12.",
        ["The upscaler OptiScaler uses in DirectX 11 games. The ones marked “on DX12” run through a DirectX 12 bridge."] = "L'upscaler che OptiScaler usa nei giochi DirectX 11. Quelli indicati “on DX12” passano da un ponte DirectX 12.",
        ["The upscaler OptiScaler uses in Vulkan games. The ones marked “on DX12” run through a DirectX 12 bridge."] = "L'upscaler che OptiScaler usa nei giochi Vulkan. Quelli indicati “on DX12” passano da un ponte DirectX 12.",
        ["Uses FSR 4 instead of FSR 3.1 when the graphics card supports it."] = "Usa FSR 4 invece di FSR 3.1 quando la scheda video lo supporta.",
        ["Renders above the screen's resolution and scales down, for a sharper picture at some cost."] = "Renderizza sopra la risoluzione dello schermo e poi riduce, per un'immagine più nitida a un certo costo.",
        ["How far above the screen's resolution output scaling renders."] = "Di quanto l'output scaling renderizza sopra la risoluzione dello schermo.",
        ["Uses the upscale ratio below instead of the game's quality preset."] = "Usa il rapporto di upscaling qui sotto invece della qualità scelta nel gioco.",
        ["Screen resolution divided by render resolution: 1.5 is Quality, 2 is Performance."] = "Risoluzione dello schermo divisa per quella di rendering: 1,5 è Qualità, 2 è Prestazioni.",
        ["Turns on OptiScaler's frame generation."] = "Attiva la generazione dei frame di OptiScaler.",
        ["Where frame generation takes its data from: the game's own frame generation, or the upscaler."] = "Da dove la generazione dei frame prende i dati: dalla generazione dei frame del gioco o dall'upscaler.",
        ["What makes the generated frames. FSR and XeSS frame generation need their dll next to OptiScaler."] = "Cosa crea i frame generati. La generazione dei frame FSR e XeSS richiede la sua dll accanto a OptiScaler.",
        ["Draws the game's UI over the generated frames. Needs a game that hands the UI over apart."] = "Disegna l'interfaccia del gioco sopra i frame generati. Serve un gioco che fornisca l'interfaccia a parte.",
        ["Caps the frame rate (through Reflex when the game has it). 0 means no limit."] = "Limita il frame rate (tramite Reflex se il gioco lo ha). 0 significa nessun limite.",
        ["Ignores the game's sharpness setting and uses the strength below."] = "Ignora la nitidezza impostata nel gioco e usa l'intensità qui sotto.",
        ["How much OptiScaler sharpens the picture."] = "Quanto OptiScaler rende più nitida l'immagine.",
        ["AMD's RCAS sharpening, applied by OptiScaler after upscaling."] = "La nitidezza RCAS di AMD, applicata da OptiScaler dopo l'upscaling.",
        ["Sharpens more while the camera moves, where upscaling blurs most."] = "Aumenta la nitidezza mentre la telecamera si muove, dove l'upscaling sfoca di più.",
        ["Makes the game see an Nvidia card, so it offers DLSS on AMD and Intel."] = "Fa vedere al gioco una scheda Nvidia, così offre DLSS su AMD e Intel.",
        ["The same for Vulkan games."] = "Lo stesso per i giochi Vulkan.",
        ["Spoofs the card for Nvidia Streamline only, even with the switches above off."] = "Simula la scheda solo per Nvidia Streamline, anche con gli interruttori sopra spenti.",
        ["The card name the game sees while spoofing."] = "Il nome della scheda che il gioco vede durante la simulazione.",
        ["Changes the frame generation ratio on the fly to reach a target frame rate. Needs an RTX 50 card or OptiScaler's own frame generation."] = "Cambia al volo il rapporto di generazione dei frame per raggiungere un frame rate obiettivo. Serve una RTX 50 o la generazione dei frame di OptiScaler.",
        ["How many frames are generated for each real one."] = "Quanti frame vengono generati per ogni frame reale.",
        ["Loads the .asi files of the plugins folder (see Plugins & DLLs)."] = "Carica i file .asi della cartella dei plugin (vedi Plugin e DLL).",
        ["Loads ReShade through OptiScaler, so both work in the same game."] = "Carica ReShade tramite OptiScaler, così funzionano entrambi nello stesso gioco.",
        ["Shows OptiScaler's FPS counter in game."] = "Mostra il contatore FPS di OptiScaler nel gioco.",
        ["The size of OptiScaler's in-game menu."] = "La dimensione del menu di OptiScaler nel gioco.",
        ["Interface size"] = "Dimensione dell'interfaccia",
        ["Scroll bars"] = "Barre di scorrimento",
        ["Makes everything in the window smaller or bigger, on top of the Windows display scale. Menus and dialogs keep the Windows size. Only 100% is fully tested: any other size is experimental and some pages may not look right."] = "Rimpicciolisce o ingrandisce tutto ciò che è nella finestra, oltre alla scala dello schermo di Windows. Menu e finestre di dialogo mantengono la dimensione di Windows. Solo il 100% è provato a fondo: ogni altra dimensione è sperimentale e alcune pagine potrebbero non apparire bene.",
        ["Shown: they get thinner in a smaller window. Hidden: no scroll bars on the pages and lists; the mouse wheel, touch, the keyboard and a controller still scroll."] = "Mostrate: diventano più sottili in una finestra più piccola. Nascoste: niente barre di scorrimento su pagine ed elenchi; la rotellina del mouse, il tocco, la tastiera e il controller scorrono comunque.",
        ["Add to Hybrid Launcher"] = "Aggiungi a Hybrid Launcher",
        ["Drop a game's .exe to add it as a game, or a folder to add it as a games folder."] = "Trascina qui l'.exe di un gioco per aggiungerlo come gioco, o una cartella per aggiungerla come cartella giochi.",
        ["Folder added. Each sub-folder with an .exe is listed as a game."] = "Cartella aggiunta. Ogni sottocartella con un .exe compare come gioco.",
        ["Search achievements"] = "Cerca obiettivi",
        ["Colour applies to Hybrid Launcher and Minimal. Background applies to those and to the PlayStation looks (Automatic keeps the console's own); the others keep their own colours."] = "Il colore vale per Hybrid Launcher e Minimale. Lo sfondo vale per questi e per gli stili PlayStation (Automatico tiene quello della console); gli altri tengono i propri colori.",
        ["Pinned"] = "Fissati",
        ["Play time"] = "Tempo di gioco",
        ["Upscalers (DLSS, FSR, XeSS)"] = "Upscaler (DLSS, FSR, XeSS)",
        ["A progress pop-up of this game: a step towards one of its locked achievements"] = "Un pop-up di avanzamento di questo gioco: un passo verso uno dei suoi obiettivi bloccati",
        ["A step towards an achievement"] = "Un passo verso un obiettivo",
        ["Also the articles about the game that Steam relays from news sites"] = "Anche gli articoli sul gioco che Steam riprende dai siti di notizie",
        ["Every Hybrid Launcher release, newest first"] = "Ogni versione di Hybrid Launcher, dalla più recente",
        ["Every build on SteamDB"] = "Ogni build su SteamDB",
        ["HYBRID LAUNCHER"] = "HYBRID LAUNCHER",
        ["Hybrid Launcher and Minimal only"] = "Solo Hybrid Launcher e Minimale",
        ["Hybrid Launcher, Steam, GOG and Epic looks"] = "Stili Hybrid Launcher, Steam, GOG ed Epic",
        ["News"] = "Notizie",
        ["News and update notes of your games, and what is new in Hybrid Launcher"] = "Notizie e note degli aggiornamenti dei tuoi giochi, e le novità di Hybrid Launcher",
        ["No installed games yet: their news shows here once they are in the library."] = "Nessun gioco installato: le notizie compaiono qui quando i giochi sono nella libreria.",
        ["No posts match. Steam has news only for games it knows; try Press articles, or another game."] = "Nessun post corrisponde. Steam ha notizie solo per i giochi che conosce; prova Articoli della stampa, o un altro gioco.",
        ["No update notes on Steam for this game"] = "Nessuna nota di aggiornamento su Steam per questo gioco",
        ["Of the {0} look"] = "Dello stile {0}",
        ["Only the developers' notes for each update"] = "Solo le note degli sviluppatori per ogni aggiornamento",
        ["Open on {0}"] = "Apri su {0}",
        ["Pick a game to see its updates, newest first"] = "Scegli un gioco per vedere i suoi aggiornamenti, dal più recente",
        ["Pick the text colour"] = "Scegli il colore del testo",
        ["Play time, the mods installed (Opti, RS, RDX, U+), upscaler tags and achievements on each cover. Hidden shows the bare cover art. Each kind can be turned off below, or in the library's Filters."] = "Tempo di gioco, mod installate (Opti, RS, RDX, U+), tag degli upscaler e obiettivi su ogni copertina. Nascosti mostra solo la copertina. Ogni tipo si può spegnere qui sotto, o nei Filtri della libreria.",
        ["Press articles"] = "Articoli della stampa",
        ["Progress"] = "Avanzamento",
        ["Read the news again"] = "Leggi di nuovo le notizie",
        ["Sample achievement"] = "Obiettivo di esempio",
        ["Shows one of the game's real achievements (its name, picture and rarity) the same way an unlock would, in the look of its store when the look matches the store. Platinum shows the game's own platinum: its achievement for unlocking all the others. Progress shows a step towards one of its locked achievements, with its real count when the game keeps one. Nothing is unlocked."] = "Mostra uno degli obiettivi reali del gioco (nome, immagine e rarità) come apparirebbe uno sblocco, nello stile del suo store quando lo stile segue lo store. Platino mostra il platino del gioco: il suo obiettivo per aver sbloccato tutti gli altri. Avanzamento mostra un passo verso uno dei suoi obiettivi bloccati, con il conteggio reale quando il gioco lo tiene. Non viene sbloccato nulla.",
        ["Text"] = "Testo",
        ["The release list could not be read (offline, or GitHub's limit for now)."] = "Non è stato possibile leggere l'elenco delle versioni (offline, o il limite di GitHub per ora).",
        ["Updates only"] = "Solo aggiornamenti",
        ["Version history"] = "Cronologia versioni",
        ["What the developers of your games posted on Steam, their update notes, and what changed in Hybrid Launcher."] = "Cosa hanno pubblicato su Steam gli sviluppatori dei tuoi giochi, le note degli aggiornamenti e cosa è cambiato in Hybrid Launcher.",
        ["Which look's colours to set"] = "Di quale stile impostare i colori",
        ["Which store's notification to imitate. “Match the game's store” uses the Steam, GOG, Epic or Xbox look of each game. Every look keeps its own background and text colours below (Automatic = the look's own). Colour applies only to Hybrid Launcher and Minimal; options a look does not use are greyed out."] = "Quale notifica di store imitare. “Come lo store del gioco” usa lo stile Steam, GOG, Epic o Xbox di ogni gioco. Ogni stile tiene i propri colori di sfondo e testo qui sotto (Automatico = quelli dello stile). Il colore vale solo per Hybrid Launcher e Minimale; le opzioni che uno stile non usa sono in grigio.",
        ["You have {0}"] = "Hai la {0}",
