        ["Drag the rows to change the order; each card stays in its column. Unticked cards are hidden on every game's dashboard. Each card's own menu can also move or hide it."] = "Trascina le righe per cambiare l'ordine; ogni scheda resta nella sua colonna. Le schede senza spunta sono nascoste nella dashboard di ogni gioco. Anche il menu di ogni scheda può spostarla o nasconderla.",
