        ["Play from Hybrid Launcher and your sessions show up here: this week, the last 14 days, your usual session and streaks."] = "Gioca da Hybrid Launcher e qui compaiono le tue sessioni: questa settimana, gli ultimi 14 giorni, la sessione tipica e le serie.",
