        ["Put F5Low {0}, published beside this build, in with it (NVIDIA RTX only)"] = "Installa insieme F5Low {0}, pubblicato accanto a questa build (solo NVIDIA RTX)",
        ["Reinstall OptiScaler to switch."] = "Reinstalla OptiScaler per cambiare.",
        ["Switching…"] = "Cambio in corso…",
        ["Skipping {0}"] = "{0} saltato",
        ["Streak"] = "Serie",
        ["The port runs only with {0} {1} or newer; yours is {2}, so it will be slow or not start."] = "Il port funziona solo con {0} {1} o più recente; il tuo è {2}, quindi sarà lento o non partirà.",
        ["The vendor-neutral port runs the model with DirectX 12 compute on {0}."] = "Il port vendor-neutral esegue il modello con il compute di DirectX 12 su {0}.",
        ["This build has no vendor-neutral forwarder: the model runs through NVIDIA's NGX, on RTX cards only."] = "Questa build non ha il forwarder vendor-neutral: il modello passa da NGX di NVIDIA, solo su schede RTX.",
        ["This game has the vendor-neutral port now."] = "Ora questo gioco ha il port vendor-neutral.",
        ["This game uses NGX now."] = "Ora questo gioco usa NGX.",
        ["Usual session"] = "Sessione tipica",
        ["Vendor-neutral (any DirectX 12 GPU)"] = "Vendor-neutral (qualsiasi GPU DirectX 12)",
