        ["You usually play"] = "Di solito giochi",
        ["You're at {0:0}% · {1} to go"] = "Sei al {0:0}% · mancano {1}",
        ["Your {0} is {1}: the port needs {2} or newer, or it runs slowly."] = "Il tuo {0} è {1}: il port richiede {2} o più recente, altrimenti è lento.",
        ["about {0} week at your pace"] = "circa {0} settimana al tuo ritmo",
        ["about {0} weeks at your pace"] = "circa {0} settimane al tuo ritmo",
