        ["{0} left to unlock"] = "{0} da sbloccare",
        ["{0}: the vendor-neutral DLSS 5 forwarder is in, so the model runs on any DirectX 12 card."] = "{0}: è stato messo il forwarder DLSS 5 vendor-neutral, quindi il modello gira su qualsiasi scheda DirectX 12.",
