        ["{0} {1}: click for its tab, or to hide these tags"] = "{0} {1}: clic per la sua scheda o per nascondere questi tag",
        ["{0}: {1} files laid over the build."] = "{0}: {1} file sovrapposti alla build.",
        // 1.4.0-rc.10
        ["DLSS 5 model file"] = "File del modello DLSS 5",
        ["Install anyway"] = "Installa comunque",
        ["Install without it"] = "Installa senza",
        ["On {0} the vendor-neutral port runs it, and it needs version {1} or newer."] = "Su {0} lo esegue il port vendor-neutral, che richiede la versione {1} o più recente.",
        ["Pick {0}…"] = "Scegli {0}…",
        ["Steam reviews and Metacritic scores."] = "Recensioni di Steam e punteggi di Metacritic.",
        ["This build runs DLSS 5 neural rendering with NVIDIA's {0}, which no build may include: without it DLSS 5 does not start."] = "Questa build esegue il neural rendering DLSS 5 con il file {0} di NVIDIA, che nessuna build può includere: senza, DLSS 5 non parte.",
        ["Your {0} is version {1}. The vendor-neutral port that runs DLSS 5 on {2} works only with {3} or newer, so DLSS 5 will not start with this one."] = "Il tuo {0} è la versione {1}. Il port vendor-neutral che esegue DLSS 5 su {2} funziona solo con la {3} o più recente, quindi con questo DLSS 5 non parte.",
        ["{0} is taking long to answer: the saves of {1} are sent at the next sync."] = "{0} ci mette troppo a rispondere: i salvataggi di {1} verranno inviati alla prossima sincronizzazione.",
        // 1.4.0-rc.16: Ubisoft Connect, EA app, Rockstar Games Launcher; DXVK, DXVK-gplasync, VKD3D-Proton; the mod check
        ["DXVK, DXVK-gplasync and VKD3D-Proton: Direct3D through Vulkan"] = "DXVK, DXVK-gplasync e VKD3D-Proton: Direct3D tramite Vulkan",
        ["A few lines of dxvk.conf in the game folder"] = "Alcune righe di dxvk.conf nella cartella del gioco",
        ["An older release: for when a newer one misbehaves in this game."] = "Una release precedente: per quando una più recente dà problemi in questo gioco.",
        ["Async goes on in dxvk.conf. Avoid it in online games with anti-cheat."] = "L'async viene attivato in dxvk.conf. Evitalo nei giochi online con anti-cheat.",
        ["Async shader compiling"] = "Compilazione degli shader in async",
        ["Changed since: {0}. Install it again to put them back."] = "Cambiati da allora: {0}. Installalo di nuovo per rimetterli.",
        ["Click for what is wrong and how to fix it"] = "Clic per vedere cosa non va e come risolverlo",
        ["Could not change dxvk.conf"] = "Impossibile modificare dxvk.conf",
        ["Could not install {0}"] = "Impossibile installare {0}",
        ["Could not uninstall {0}"] = "Impossibile disinstallare {0}",
        ["DXVK and VKD3D-Proton"] = "DXVK e VKD3D-Proton",
        ["Direct3D 8 to 11 (DXVK) or 12 (VKD3D-Proton) run through Vulkan"] = "Direct3D da 8 a 11 (DXVK) o 12 (VKD3D-Proton) eseguito tramite Vulkan",
        ["Direct3D version"] = "Versione di Direct3D",
        ["EA"] = "EA",
        ["Ubisoft"] = "Ubisoft",
        ["Rockstar"] = "Rockstar",
        ["Frame rate cap"] = "Limite di frame rate",
        ["Graphics API: {0}."] = "API grafica: {0}.",
        ["Hide this until it changes"] = "Nascondi finché non cambia qualcosa",
        ["Hybrid Launcher installed OptiScaler {0} as {1}, and the file is not there any more. A game update or a file check (Verify integrity) removes files the game does not know."] = "Hybrid Launcher ha installato OptiScaler {0} come {1}, e il file non c'è più. Un aggiornamento del gioco o una verifica dei file (Verifica integrità) rimuove i file che il gioco non conosce.",
        ["Ignore"] = "Ignora",
        ["Install (replaces {0})"] = "Installa (sostituisce {0})",
        ["Install OptiScaler again"] = "Reinstalla OptiScaler",
        ["Install it again"] = "Installalo di nuovo",
        ["Its files are not there any more (a game update or a file check may have cleared the folder)."] = "I suoi file non ci sono più (un aggiornamento del gioco o una verifica dei file può aver ripulito la cartella).",
        ["Layer"] = "Layer",
        ["LoadReshade is on in OptiScaler.ini, but there is no ReShade64.dll beside it, so no ReShade starts. Install ReShade through OptiScaler again, or turn the setting off."] = "LoadReshade è attivo in OptiScaler.ini, ma accanto non c'è ReShade64.dll, quindi ReShade non parte. Fai caricare di nuovo ReShade da OptiScaler, oppure disattiva l'impostazione.",
        ["Loading releases…"] = "Caricamento delle release…",
        ["Mods in {0}"] = "Mod in {0}",
        ["No release found (offline?)"] = "Nessuna release trovata (offline?)",
        ["No translation layer in this game: it runs on Windows' Direct3D"] = "Nessun layer di traduzione in questo gioco: usa il Direct3D di Windows",
        ["Open DXVK"] = "Apri DXVK",
        ["Open Luma"] = "Apri Luma",
        ["Open ReShade"] = "Apri ReShade",
        ["Open RenoDX"] = "Apri RenoDX",
        ["Open dxvk.conf"] = "Apri dxvk.conf",
        ["OptiScaler is gone from the game folder"] = "OptiScaler non è più nella cartella del gioco",
        ["OptiScaler is in this folder twice"] = "OptiScaler è due volte in questa cartella",
        ["OptiScaler is set to load ReShade, and ReShade is not here"] = "OptiScaler è impostato per caricare ReShade, ma ReShade non c'è",
        ["OptiScaler no longer loads ReShade in this game."] = "OptiScaler non carica più ReShade in questo gioco.",
        ["OptiScaler's upscalers work with the game's own Direct3D: through DXVK most of them have nothing to hook. Use one or the other in a game."] = "Gli upscaler di OptiScaler lavorano con il Direct3D del gioco: con DXVK quasi nessuno trova a cosa agganciarsi. In un gioco usa l'uno o l'altro.",
        ["Puts {0} next to the game exe."] = "Mette {0} accanto all'exe del gioco.",
        ["ReShade is {0}, and OptiScaler also loads ReShade64.dll (LoadReshade on). Two ReShades in one game draw their effects twice or crash. Let one of them go: stop OptiScaler loading it, or remove {0} in ReShade's section."] = "ReShade è {0}, e OptiScaler carica anche ReShade64.dll (LoadReshade attivo). Due ReShade nello stesso gioco applicano gli effetti due volte o vanno in crash. Tienine uno: impedisci a OptiScaler di caricarlo, oppure rimuovi {0} nella sezione di ReShade.",
        ["ReShade loads twice"] = "ReShade viene caricato due volte",
        ["ReShade {0} skips {1}"] = "ReShade {0} salta {1}",
        ["Release"] = "Release",
        ["Removes {0} and puts back the {1} file(s) it replaced. The game runs on Windows' Direct3D again."] = "Rimuove {0} e rimette i {1} file che aveva sostituito. Il gioco torna a usare il Direct3D di Windows.",
        ["RenoDX and Luma mods are ReShade add-ons: without ReShade (the build with full add-on support) in this folder they never start."] = "Le mod RenoDX e Luma sono add-on di ReShade: senza ReShade (la build con supporto completo agli add-on) in questa cartella non partono mai.",
        ["Saved in dxvk.conf. It applies the next time the game starts."] = "Salvato in dxvk.conf. Vale dal prossimo avvio del gioco.",
        ["Something replaced OptiScaler's {0} since Hybrid Launcher installed it: {1}. OptiScaler does not load."] = "Qualcosa ha sostituito {0} di OptiScaler dopo l'installazione da Hybrid Launcher: {1}. OptiScaler non viene caricato.",
        ["Stop OptiScaler loading ReShade"] = "Non far caricare ReShade a OptiScaler",
        ["The RenoDX mod is gone from the game folder"] = "La mod RenoDX non è più nella cartella del gioco",
        ["The game is listed as {0}: the dlls of another Direct3D version are not used by it."] = "Il gioco risulta {0}: le dll di un'altra versione di Direct3D non le usa.",
        ["The layer, the game's Direct3D version and the release"] = "Il layer, la versione di Direct3D del gioco e la release",
        ["The newest release."] = "La release più recente.",
        ["There is no dxvk.conf in the game folder yet: the switches above make one."] = "Nella cartella del gioco non c'è ancora un dxvk.conf: gli interruttori qui sopra lo creano.",
        ["These files belong to another mod"] = "Questi file appartengono a un'altra mod",
        ["Turn LoadReshade off"] = "Disattiva LoadReshade",
        ["VKD3D-Proton needs DXVK's dxgi.dll, and no DXVK release could be found (offline?)."] = "VKD3D-Proton ha bisogno del dxgi.dll di DXVK, e non è stata trovata nessuna release di DXVK (offline?).",
        ["a file of unknown origin"] = "un file di origine sconosciuta",
        ["and"] = "e",
        ["dxgi.dll comes from DXVK {0}."] = "dxgi.dll viene da DXVK {0}.",
        ["dxgi.enableHDR: lets the game offer HDR through DXVK (Windows HDR must be on)."] = "dxgi.enableHDR: permette al gioco di offrire l'HDR tramite DXVK (l'HDR di Windows deve essere attivo).",
        ["dxgi.maxFrameRate and d3d9.maxFrameRate: 0 leaves the frame rate free."] = "dxgi.maxFrameRate e d3d9.maxFrameRate: 0 lascia il frame rate libero.",
        ["dxvk.enableAsync: frames are drawn while shaders compile, so less stutter; an effect can be missing for a moment."] = "dxvk.enableAsync: i frame vengono disegnati mentre gli shader si compilano, quindi meno stutter; un effetto può mancare per un attimo.",
        ["in the folder"] = "nella cartella",
        ["the game's"] = "quella del gioco",
        ["{0} add-ons"] = "{0} add-on",
        ["{0} are both OptiScaler: the game loads both copies, which usually ends in a crash at start. Keep one: uninstall OptiScaler, then install it again."] = "{0} sono entrambi OptiScaler: il gioco carica tutte e due le copie, e di solito va in crash all'avvio. Tienine una: disinstalla OptiScaler, poi installalo di nuovo.",
        ["{0} belongs to {1}. Take it out first, or the game would lose it."] = "{0} appartiene a {1}. Toglilo prima, altrimenti il gioco lo perderebbe.",
        ["{0} changed since Hybrid Launcher installed {1} {2}: a game update or a file check put the game's own back, or removed them."] = "{0} è cambiato da quando Hybrid Launcher ha installato {1} {2}: un aggiornamento del gioco o una verifica dei file ha rimesso i file originali, o li ha rimossi.",
        ["{0} does not run {1} games."] = "{0} non esegue giochi {1}.",
        ["{0} draws with {1}: DXVK and VKD3D-Proton are for Direct3D games."] = "{0} usa {1}: DXVK e VKD3D-Proton servono ai giochi Direct3D.",
        ["{0} files are in the folder (not installed by Hybrid Launcher)"] = "Nella cartella ci sono file di {0} (non installati da Hybrid Launcher)",
        ["{0} add-ons have no ReShade to load them"] = "{0} add-on non hanno un ReShade che li carichi",
        ["{0} has no ReShade to load it"] = "{0} non ha un ReShade che lo carichi",
        ["{0} is OptiScaler here. DXVK needs that name for itself, and OptiScaler's upscalers need the game's own Direct3D anyway. Take OptiScaler out (or install it under another dll name) before DXVK."] = "Qui {0} è OptiScaler. DXVK ha bisogno di quel nome, e comunque gli upscaler di OptiScaler richiedono il Direct3D del gioco. Togli OptiScaler (o installalo con un altro nome di dll) prima di DXVK.",
        ["{0} is ReShade here. With DXVK, ReShade has to hook Vulkan instead: run ReShade's installer again, pick Vulkan, then install DXVK."] = "Qui {0} è ReShade. Con DXVK, ReShade deve agganciarsi a Vulkan: avvia di nuovo l'installer di ReShade, scegli Vulkan, poi installa DXVK.",
        ["{0} is gone from the game folder"] = "{0} non è più nella cartella del gioco",
        ["{0} is in the game folder"] = "{0} è nella cartella del gioco",
        ["{0} is missing its dxgi.dll"] = "A {0} manca il suo dxgi.dll",
        ["{0} is not OptiScaler any more"] = "{0} non è più OptiScaler",
        ["{0} is not complete any more"] = "{0} non è più completo",
        ["{0} is not installed: the layers can go in once it is."] = "{0} non è installato: i layer si possono aggiungere quando lo sarà.",
        ["{0} is not there any more (a game update or a file check may have cleared the folder)."] = "{0} non c'è più (un aggiornamento del gioco o una verifica dei file può aver ripulito la cartella).",
        ["{0} is {1}'s file here."] = "Qui {0} è un file di {1}.",
        ["{0} problems with this game's mods"] = "{0} problemi con le mod di questo gioco",
        ["{0} removed, with problems"] = "{0} rimosso, con qualche problema",
        ["{0} {1} has no {2} for {3}-bit games."] = "{0} {1} non ha {2} per giochi a {3} bit.",
        ["{0} {1} installed in {2}. It runs the next time the game starts."] = "{0} {1} installato in {2}. Entra in funzione al prossimo avvio del gioco.",
        ["{0} {1} is installed"] = "{0} {1} è installato",
        ["{0} {1} is installed for {2}"] = "{0} {1} è installato per {2}",
        ["{0} {1}: the archive has no x64 folder."] = "{0} {1}: l'archivio non ha una cartella x64.",
        ["{0}'s {1} is here without DXVK's dxgi.dll: {0} cannot start, and the game runs on Windows' Direct3D or does not start."] = "Qui c'è {1} di {0} senza il dxgi.dll di DXVK: {0} non può partire, e il gioco usa il Direct3D di Windows oppure non si avvia.",
        ["{0}'s {1} is here, but dxgi.dll is {2}. {0} only starts with DXVK's own dxgi.dll: the game runs on Windows' Direct3D, or does not start. Give the other mod another dll name, or take {0} out."] = "Qui c'è {1} di {0}, ma dxgi.dll è {2}. {0} parte solo con il dxgi.dll di DXVK: il gioco usa il Direct3D di Windows, oppure non si avvia. Dai all'altra mod un altro nome di dll, oppure togli {0}.",
        ["{0}, {1}-bit, installed {2:d MMM yyyy, HH:mm}"] = "{0}, {1} bit, installato il {2:d MMM yyyy, HH:mm}",
        ["• On Windows these layers help older games most: Direct3D 9 games that stutter or run slowly on AMD and Intel cards, and games whose Direct3D renderer has bugs. A game that already runs well rarely gains."] = "• Su Windows questi layer aiutano soprattutto i giochi vecchi: giochi Direct3D 9 che scattano o vanno lenti su schede AMD e Intel, e giochi con un renderer Direct3D difettoso. Un gioco che già funziona bene raramente ci guadagna.",
        ["• DXVK-gplasync compiles shaders in the background, so the first time an effect shows the frame does not wait for it. Use it in single-player games: its async mode is something anti-cheat systems can object to."] = "• DXVK-gplasync compila gli shader in background, così la prima volta che compare un effetto il frame non lo aspetta. Usalo nei giochi single-player: la sua modalità async può non piacere ai sistemi anti-cheat.",
        ["• VKD3D-Proton is made for Linux; on Windows it is mostly for testing. It needs DXVK's dxgi.dll, which goes in with it."] = "• VKD3D-Proton è fatto per Linux; su Windows serve soprattutto per fare prove. Ha bisogno del dxgi.dll di DXVK, che viene installato insieme.",
        ["• OptiScaler and ReShade (as dxgi.dll, d3d11.dll…) cannot share those file names with DXVK: Hybrid Launcher does not replace them. ReShade can hook Vulkan instead (pick Vulkan in its installer)."] = "• OptiScaler e ReShade (come dxgi.dll, d3d11.dll…) non possono condividere quei nomi di file con DXVK: Hybrid Launcher non li sostituisce. ReShade può invece agganciarsi a Vulkan (scegli Vulkan nel suo installer).",
        ["• Uninstall puts back every file the layer replaced, and removes a dxvk.conf Hybrid Launcher made."] = "• La disinstallazione rimette ogni file sostituito dal layer, e rimuove il dxvk.conf creato da Hybrid Launcher.",
        // 1.4.0-rc.16: OptiScaler's file name swapped in place
        ["Works in most games (DirectX 11 and 12)"] = "Funziona nella maggior parte dei giochi (DirectX 11 e 12)",
        ["Loaded by nearly every game; good when dxgi.dll is taken"] = "Caricato da quasi tutti i giochi; utile quando dxgi.dll è occupato",
        ["Some games only"] = "Solo alcuni giochi",
        ["DirectX 12 games only"] = "Solo giochi DirectX 12",
        ["Games that go online at start"] = "Giochi che si collegano a internet all'avvio",
        ["in use now"] = "in uso ora",
        ["not a name OptiScaler is loaded as"] = "non è un nome con cui OptiScaler può essere caricato",
        ["taken by {0}"] = "occupato da {0}",
        ["{0} cannot be used: {1}."] = "{0} non si può usare: {1}.",
        ["OptiScaler's {0} is not in the game folder: install OptiScaler again."] = "Il file {0} di OptiScaler non è nella cartella del gioco: reinstalla OptiScaler.",
        ["The file name OptiScaler is loaded as. Click to change it without reinstalling."] = "Il nome di file con cui viene caricato OptiScaler. Clic per cambiarlo senza reinstallare.",
        ["{0} needs an ASI loader in the game: it is used at the next install."] = "{0} richiede un ASI loader nel gioco: verrà usato alla prossima installazione.",
        ["Load OptiScaler as…"] = "Carica OptiScaler come…",
        ["Wait for the running install or update to finish."] = "Aspetta che finisca l'installazione o l'aggiornamento in corso.",
        ["OptiScaler is now {0} in {1} (was {2}). Nothing was reinstalled."] = "Ora OptiScaler è {0} in {1} (prima era {2}). Non è stato reinstallato nulla.",
        ["Could not rename OptiScaler to {0}"] = "Impossibile rinominare OptiScaler in {0}",
        // 1.4.0-rc.17: what is installed as what
        ["Brought by OptiScaler"] = "Portato da OptiScaler",
        ["Could not read the game folder"] = "Impossibile leggere la cartella del gioco",
        ["Direct3D through Vulkan: less stutter in some older games"] = "Direct3D tramite Vulkan: meno stutter in alcuni giochi più vecchi",
        ["Loaded by Windows in place of its own dll"] = "Caricati da Windows al posto delle sue dll",
        ["Loaded by another mod"] = "Caricati da un'altra mod",
        ["Mod files of {0}"] = "File delle mod di {0}",
        ["No mod files beside the game exe: the game runs as it shipped."] = "Nessun file di mod accanto all'exe del gioco: il gioco gira com'è stato distribuito.",
        ["Not loaded: LoadReshade is off in OptiScaler.ini"] = "Non caricato: LoadReshade è disattivato in OptiScaler.ini",
        ["Not loaded: OptiScaler, which would load it, is not here"] = "Non caricato: OptiScaler, che lo caricherebbe, non c'è",
        ["Not loaded: there is no ReShade here"] = "Non caricato: qui non c'è ReShade",
        ["Not loaded: {0} is the normal ReShade build, which skips add-ons"] = "Non caricato: {0} è la build normale di ReShade, che salta gli add-on",
        ["OptiScaler loads it (ASI plugin)"] = "Lo carica OptiScaler (plugin ASI)",
        ["OptiScaler loads it (LoadReshade on in OptiScaler.ini)"] = "Lo carica OptiScaler (LoadReshade attivo in OptiScaler.ini)",
        ["OptiScaler's copy, in place of the game's own (kept as a backup)"] = "La copia di OptiScaler, al posto di quella del gioco (conservata come backup)",
        ["ReShade add-on"] = "Add-on di ReShade",
        ["ReShade loads it ({0})"] = "Lo carica ReShade ({0})",
        ["ReShade with full add-on support"] = "ReShade con supporto completo agli add-on",
        ["Read by {0} when the game starts"] = "Letto da {0} all'avvio del gioco",
        ["Settings files"] = "File di impostazioni",
        ["The game's own"] = "Del gioco",
        ["What is installed as what"] = "Cosa è installato come cosa",
        ["Windows loads it in place of its own {0}"] = "Windows lo carica al posto del suo {0}",
        ["put in another way"] = "messo in altro modo",
        ["put in by Hybrid Launcher"] = "messo da Hybrid Launcher",
        ["shipped with the game"] = "incluso nel gioco",
        ["without DXVK's dxgi.dll it cannot start"] = "senza il dxgi.dll di DXVK non può partire",
        ["{0} settings"] = "Impostazioni di {0}",
        ["Unknown"] = "Sconosciuto",

        // ---- Mods tab (1.4.0-rc.18) ----
        ["Other files beside the exe ({0}): upscalers and Windows dlls the game ships"] = "Altri file accanto all'exe ({0}): upscaler e dll di Windows forniti dal gioco",
        ["The mods installed in this game and their conflicts; ReShade, RenoDX, Luma, DLSS 5, DXVK and VKD3D-Proton"] = "Le mod installate in questo gioco e i loro conflitti; ReShade, RenoDX, Luma, DLSS 5, DXVK e VKD3D-Proton",
        ["Every mod in the game folder, its files and what loads them, and conflicts between them"] = "Ogni mod nella cartella del gioco, i suoi file e cosa li carica, e i conflitti tra loro",
        ["DLSS 5 neural rendering: the PC's card, the model file, DLSSNR-AMD and F5 Multipass"] = "Rendering neurale DLSS 5: la scheda del PC, il file del modello, DLSSNR-AMD e F5 Multipass",
        ["DXVK and DXVK-gplasync: Direct3D 8 to 11 through Vulkan"] = "DXVK e DXVK-gplasync: Direct3D da 8 a 11 tramite Vulkan",
