        ["Mod"] = "Mod",
        ["No conflicts: every mod in this folder can load."] = "Nessun conflitto: ogni mod in questa cartella può caricarsi.",
        ["No mods in this game: it runs as it shipped."] = "Nessuna mod in questo gioco: gira com'è stato distribuito.",
        ["Not installed by Hybrid Launcher: its files have no record to be taken out by. Install OptiScaler here to manage it."] = "Non installato da Hybrid Launcher: non c'è un registro dei suoi file per toglierlo. Installa OptiScaler qui per gestirlo.",
        ["Not installed by Hybrid Launcher: nothing was backed up, so its files are left for you to remove by hand."] = "Non installato da Hybrid Launcher: non è stato salvato nessun backup, quindi i suoi file vanno tolti a mano.",
        ["Not installed by Hybrid Launcher: remove its files from the game folder by hand."] = "Non installata da Hybrid Launcher: togli i suoi file dalla cartella del gioco a mano.",
        ["Not managed by Hybrid Launcher: remove the file by hand if you do not want it."] = "Non gestito da Hybrid Launcher: togli il file a mano se non lo vuoi.",
        ["F5 Multipass is OptiScaler itself (a fork): uninstall OptiScaler, or install the official build, to take it out."] = "F5 Multipass è OptiScaler stesso (un fork): disinstalla OptiScaler, o installa la build ufficiale, per toglierlo.",
        ["OK"] = "OK",
        ["Problem"] = "Problema",
        ["State"] = "Stato",
