        ["Open in Mods"] = "Apri in Mod",
        ["Open VKD3D-Proton"] = "Apri VKD3D-Proton",
        ["OptiScaler loads it"] = "La carica OptiScaler",
        ["OptiScaler loads it (plugin)"] = "Lo carica OptiScaler (plugin)",
        ["ReShade loads it"] = "La carica ReShade",
        ["Reading the game folder…"] = "Lettura della cartella del gioco…",
        ["Reads the game folder again: mods in each other's way, files a game update put back, add-ons nothing loads"] = "Rilegge la cartella del gioco: mod che si intralciano, file rimessi da un aggiornamento del gioco, add-on che nessuno carica",
        ["Remove RenoDX from this game?"] = "Togliere RenoDX da questo gioco?",
        ["Deletes {0} from\n{1}"] = "Elimina {0} da\n{1}",
        ["Removes Ultra+ from this game and puts back the files it replaced."] = "Toglie Ultra+ da questo gioco e rimette i file che aveva sostituito.",
        ["Show 1 ignored problem"] = "Mostra 1 problema ignorato",
        ["Show {0} ignored problems"] = "Mostra {0} problemi ignorati",
        ["The game's own files ({0})"] = "I file del gioco ({0})",
        ["Uninstall it from its section"] = "Disinstallala dalla sua sezione",
        ["Uninstall {0}"] = "Disinstalla {0}",
        ["as {0}, loaded by Windows"] = "come {0}, caricata da Windows",
        ["{0} is not installed: its mods show here once it is."] = "{0} non è installato: le sue mod compaiono qui quando lo sarà.",
        ["{0}'s section: install, update, settings"] = "La sezione di {0}: installazione, aggiornamento, impostazioni",
        ["A game holds one layer at a time: installing {0} replaces it."] = "Un gioco tiene un solo livello alla volta: installare {0} lo sostituisce.",
        ["Direct3D 12 runs through Vulkan"] = "Direct3D 12 eseguito tramite Vulkan",
        ["Direct3D 8 to 11 run through Vulkan; DXVK-gplasync compiles shaders in the background"] = "Direct3D da 8 a 11 eseguito tramite Vulkan; DXVK-gplasync compila gli shader in background",
        ["No DXVK in this game: it runs on Windows' Direct3D"] = "Nessun DXVK in questo gioco: usa il Direct3D di Windows",
        ["No VKD3D-Proton in this game: it runs on Windows' Direct3D 12"] = "Nessun VKD3D-Proton in questo gioco: usa il Direct3D 12 di Windows",
        ["The release"] = "La release",
        ["{0} draws with {1}: DXVK is for Direct3D 8 to 11 games."] = "{0} disegna con {1}: DXVK è per i giochi Direct3D da 8 a 11.",
        ["{0} draws with {1}: VKD3D-Proton is for Direct3D 12 games."] = "{0} disegna con {1}: VKD3D-Proton è per i giochi Direct3D 12.",
        ["{0} {1} is installed in this game"] = "{0} {1} è installato in questo gioco",
        ["Neural rendering after the game's upscaler: the card, the model file, DLSSNR-AMD and F5 Multipass"] = "Rendering neurale dopo l'upscaler del gioco: la scheda, il file del modello, DLSSNR-AMD e F5 Multipass",
        ["• VKD3D-Proton is made for Linux; on Windows it is mostly for testing, or for a Direct3D 12 game whose own renderer misbehaves on this card."] = "• VKD3D-Proton è fatto per Linux; su Windows serve soprattutto per test, o per un gioco Direct3D 12 il cui renderer dà problemi con questa scheda.",
        ["• It needs DXVK's dxgi.dll, which goes in with it. A game holds one layer at a time: VKD3D-Proton replaces DXVK, and the other way round."] = "• Serve il dxgi.dll di DXVK, che viene installato insieme. Un gioco tiene un solo livello alla volta: VKD3D-Proton sostituisce DXVK, e viceversa.",
        ["• OptiScaler and ReShade (as dxgi.dll, d3d12.dll…) cannot share those file names: Hybrid Launcher does not replace them. ReShade can hook Vulkan instead (pick Vulkan in its installer)."] = "• OptiScaler e ReShade (come dxgi.dll, d3d12.dll…) non possono condividere quei nomi di file: Hybrid Launcher non li sostituisce. ReShade può agganciarsi a Vulkan (scegli Vulkan nel suo installer).",
        // 1.4.0-rc.19: Downloads launchers, achievement sources, Dashboard mods, Library last played.
        ["Could not start {0}"] = "Impossibile avviare {0}",
        ["EA keeps your library online only: install games from the EA app. Hybrid Launcher lists them once installed."] = "EA tiene la tua libreria solo online: installa i giochi dall'app EA. Hybrid Launcher li elenca una volta installati.",
        ["Files and conflicts"] = "File e conflitti",
        ["From the Xbox app on this PC, as fresh as its last look at the game."] = "Dall'app Xbox di questo PC, aggiornati all'ultima volta che ha mostrato il gioco.",
        ["From the Xbox app on this PC: open it once and sign in there first."] = "Dall'app Xbox di questo PC: aprila una volta e accedi lì prima.",
        ["From your GOG account, checked while a GOG game runs."] = "Dal tuo account GOG, controllati mentre un gioco GOG è in esecuzione.",
        ["Games that keep achievements in save files on this PC (Steam emulators). {0} folders read."] = "Giochi che tengono gli obiettivi in file di salvataggio su questo PC (emulatori di Steam). {0} cartelle lette.",
        ["Live from your Microsoft account ({0})."] = "In tempo reale dal tuo account Microsoft ({0}).",
        ["Local achievement folders"] = "Cartelle degli obiettivi locali",
        ["Mods tab"] = "Scheda Mod",
        ["Needs your GOG account: sign in under Downloads → Accounts."] = "Serve il tuo account GOG: accedi da Download → Account.",
        ["Open Ubisoft Connect"] = "Apri Ubisoft Connect",
        ["Open the EA app"] = "Apri l'app EA",
        ["Play {0}"] = "Gioca a {0}",
        ["Read from Steam's own files on this PC: no sign-in."] = "Letti dai file di Steam su questo PC: nessun accesso.",
        ["Rockstar keeps your library online only: install games from the Rockstar Games Launcher. Hybrid Launcher lists them once installed."] = "Rockstar tiene la tua libreria solo online: installa i giochi dal Rockstar Games Launcher. Hybrid Launcher li elenca una volta installati.",
        ["Show all ({0})"] = "Mostra tutte ({0})",
        ["The games you play next show here."] = "Qui compaiono i prossimi giochi a cui giochi.",
        ["Ubisoft keeps your library online only: install games from Ubisoft Connect. Hybrid Launcher lists them once installed."] = "Ubisoft tiene la tua libreria solo online: installa i giochi da Ubisoft Connect. Hybrid Launcher li elenca una volta installati.",
        ["added by you"] = "aggiunta da te",
        ["all load"] = "si caricano tutte",
        ["as {0}"] = "come {0}",
        ["not found"] = "non trovata",
