        ["{0} / {1} achievements"] = "{0} / {1} obiettivi",
        ["{0} folders on this PC are read now. Add one that holds a folder per game (named by its Steam app id), or a single game's folder with its achievement file."] = "Ora vengono lette {0} cartelle su questo PC. Aggiungine una che contiene una cartella per gioco (col nome dell'app id di Steam), o la cartella di un singolo gioco con il suo file degli obiettivi.",
        ["{0} is already running."] = "{0} è già in esecuzione.",
        ["{0} minute"] = "{0} minuto",
        ["{0} minutes"] = "{0} minuti",
        ["{0} mod"] = "{0} mod",
        ["{0} more known place is read as soon as it appears on this PC."] = "Un altro percorso noto viene letto appena compare su questo PC.",
        ["{0} more known places are read as soon as they appear on this PC."] = "Altri {0} percorsi noti vengono letti appena compaiono su questo PC.",
        ["{0} plugin"] = "{0} plugin",
        ["{0} plugins"] = "{0} plugin",
        ["{0} problem"] = "{0} problema",
        ["No {0} game is installed. {1}"] = "Nessun gioco {0} installato. {1}",
        ["Starting point"] = "Punto di partenza",
        ["Each feature"] = "Ogni funzione",
        ["ReShade loads it (add-on)"] = "Lo carica ReShade (add-on)",
        ["Take it out from Mods → DLSS 5."] = "Toglilo da Mod → DLSS 5.",
        ["DLSSNR-AMD is in through ReShade"] = "DLSSNR-AMD è installato tramite ReShade",
        ["Take it out first (Mods → DLSS 5 → DLSSNR-AMD), then install OptiScaler. With OptiScaler, DLSSNR-AMD can go in as its plugin."] = "Toglilo prima (Mod → DLSS 5 → DLSSNR-AMD), poi installa OptiScaler. Con OptiScaler, DLSSNR-AMD può essere installato come suo plugin.",
        ["Do not use it in online games with anti-cheat."] = "Non usarlo nei giochi online con anti-cheat.",
        ["Auto exposure before the network ([Preprocess]); 007 First Light needs it, Ctrl+F10 switches it in game."] = "Esposizione automatica prima della rete ([Preprocess]); serve a 007 First Light, Ctrl+F10 la attiva in gioco.",
        ["Automatic: NGX on an RTX card, the vendor-neutral port on any other."] = "Automatico: NGX su una scheda RTX, il port indipendente dal produttore su tutte le altre.",
        ["Back to the package's settings"] = "Torna alle impostazioni del pacchetto",
        ["Balanced"] = "Bilanciato",
        ["Beside OptiScaler."] = "Accanto a OptiScaler.",
        ["Both mods need NVIDIA's {0}: F5 loads it beside OptiScaler, DLSSNR-AMD only reads its weights (it is never run). It is NVIDIA's file, so Hybrid Launcher cannot download it: pick the one you have. Hybrid Launcher keeps one copy."] = "Entrambe le mod richiedono {0} di NVIDIA: F5 lo carica accanto a OptiScaler, DLSSNR-AMD ne legge solo i pesi (non viene mai eseguito). È un file di NVIDIA, quindi Hybrid Launcher non può scaricarlo: scegli quello che hai. Hybrid Launcher ne conserva una copia.",
        ["Builds a network only when its video memory is free (off by default)."] = "Costruisce una rete solo quando la sua memoria video è libera (disattivato di default).",
        ["CC_SMALL_FP8 is 310.9's default and the fastest; CC_SILVER_AARDWOLD is 310.8's. The two _EXPERIMENTAL / _OPTIMIZED ones are the port's faster versions (RX 9000)."] = "CC_SMALL_FP8 è la rete predefinita della 310.9 e la più veloce; CC_SILVER_AARDWOLD è quella della 310.8. Le due _EXPERIMENTAL / _OPTIMIZED sono le versioni più veloci del port (RX 9000).",
        ["Checking GitLab…"] = "Controllo GitLab…",
        ["Could not ask GitLab for the newest release: {0}"] = "Impossibile chiedere a GitLab la release più recente: {0}",
        ["Could not change the setting"] = "Impossibile cambiare l'impostazione",
        ["Could not prepare DLSSNR-AMD"] = "Impossibile preparare DLSSNR-AMD",
        ["Could not put DLSSNR-AMD back"] = "Impossibile rimettere DLSSNR-AMD",
        ["Could not put DLSSNR-AMD in"] = "Impossibile installare DLSSNR-AMD",
        ["Could not take DLSSNR-AMD out"] = "Impossibile togliere DLSSNR-AMD",
        ["DLSS 5 needs {0} or newer."] = "DLSS 5 richiede {0} o più recente.",
        ["DLSS 5 neural rendering runs NVIDIA's network on the game's picture, after its upscaler. Two mods make it work: janblade's F5 Multipass, a fork of OptiScaler (NVIDIA NGX on RTX cards, a vendor-neutral port on other cards), and mochizuki0323's DLSSNR-AMD, a plugin of the official OptiScaler that runs it natively on Radeon RX 9000 and RX 7000."] = "Il rendering neurale di DLSS 5 esegue la rete di NVIDIA sull'immagine del gioco, dopo il suo upscaler. Due mod lo fanno funzionare: F5 Multipass di janblade, un fork di OptiScaler (NVIDIA NGX sulle schede RTX, un port indipendente dal produttore sulle altre), e DLSSNR-AMD di mochizuki0323, un plugin dell'OptiScaler ufficiale che lo esegue in modo nativo su Radeon RX 9000 e RX 7000.",
        ["DLSSNR-AMD chosen, not in this game yet."] = "DLSSNR-AMD scelto, non ancora in questo gioco.",
        ["DLSSNR-AMD in this game"] = "DLSSNR-AMD in questo gioco",
        ["DLSSNR-AMD is not prepared yet."] = "DLSSNR-AMD non è ancora preparato.",
        ["DLSSNR-AMD needs AMD Software {0}.{1} or newer."] = "DLSSNR-AMD richiede AMD Software {0}.{1} o più recente.",
        ["DLSSNR-AMD needs a Radeon RX 9000 or RX 7000: on this card only F5's vendor-neutral port can run DLSS 5."] = "DLSSNR-AMD richiede una Radeon RX 9000 o RX 7000: su questa scheda solo il port indipendente di F5 può eseguire DLSS 5.",
        ["DLSSNR-AMD prepared"] = "DLSSNR-AMD preparato",
        ["DLSSNR-AMD reads 310.9.16 (all networks) or 310.8.0 (CC_SILVER_AARDWOLD only). F5's vendor-neutral port wants 310.9 or newer."] = "DLSSNR-AMD legge la 310.9.16 (tutte le reti) o la 310.8.0 (solo CC_SILVER_AARDWOLD). Il port indipendente di F5 vuole la 310.9 o più recente.",
        ["DLSSNR-AMD reads only {0} 310.9.16 or 310.8.0; this one is {1}."] = "DLSSNR-AMD legge solo {0} 310.9.16 o 310.8.0; questo è {1}.",
        ["DLSSNR-AMD runs on Radeon RX 9000 (and RX 7000, experimental) only."] = "DLSSNR-AMD funziona solo su Radeon RX 9000 (e RX 7000, sperimentale).",
        ["DLSSNR-AMD was prepared but could not be read back."] = "DLSSNR-AMD è stato preparato ma non è stato possibile rileggerlo.",
        ["DLSSNR-AMD {0} is ready: {1}."] = "DLSSNR-AMD {0} è pronto: {1}.",
        ["DLSSNR-AMD's installer did not finish in 15 minutes and was stopped."] = "L'installer di DLSSNR-AMD non ha finito in 15 minuti ed è stato fermato.",
        ["DLSSNR-AMD's installer did not finish: {0}"] = "L'installer di DLSSNR-AMD non ha finito: {0}",
        ["DLSSNR-AMD: the network, the driver's machine code, what NR Control waits for."] = "DLSSNR-AMD: la rete, il codice macchina del driver, cosa aspetta NR Control.",
        ["DirectX 10, 11 or 12"] = "DirectX 10, 11 o 12",
        ["DirectX 9 through DXVK"] = "DirectX 9 tramite DXVK",
        ["Does not fit"] = "Non adatto",
        ["Downloading DLSSNR-AMD…"] = "Download di DLSSNR-AMD…",
        ["Downloads the package and makes the networks' weights from your model file (once for every game)."] = "Scarica il pacchetto e crea i pesi delle reti dal tuo file del modello (una volta per tutti i giochi).",
        ["Every game whose OptiScaler build needs it gets the file, unless the game says otherwise. DLSSNR-AMD does not need this."] = "Ogni gioco la cui build di OptiScaler ne ha bisogno riceve il file, a meno che il gioco non dica altrimenti. DLSSNR-AMD non ne ha bisogno.",
        ["F5 Multipass with NVIDIA NGX"] = "F5 Multipass con NVIDIA NGX",
        ["F5 Multipass with the vendor-neutral port"] = "F5 Multipass con il port indipendente dal produttore",
        ["F5 build"] = "Build F5",
        ["F5 installs"] = "Installazioni F5",
        ["F5 {0}"] = "F5 {0}",
        ["F5's vendor-neutral port: \"network: main\" means the model file is older than 310.9 and runs slowly."] = "Port indipendente di F5: \"network: main\" significa che il file del modello è più vecchio della 310.9 e va lento.",
        ["Finished picture"] = "Immagine finale",
        ["Fits"] = "Adatto",
        ["Fix green or grainy colours"] = "Correggi colori verdi o granulosi",
        ["GitLab lists no Windows package of DLSSNR-AMD."] = "GitLab non elenca nessun pacchetto Windows di DLSSNR-AMD.",
        ["GitLab lists no Windows package."] = "GitLab non elenca nessun pacchetto Windows.",
        ["Graphics API"] = "API grafica",
        ["HUD fix"] = "Correzione HUD",
        ["Home opens ReShade; NR's settings are on its Add-ons page. Ctrl+F11 cycles the networks. The first start compiles for about a minute; until then the picture looks as without NR."] = "Home apre ReShade; le impostazioni di NR sono nella sua pagina Add-on. Ctrl+F11 cambia rete. Il primo avvio compila per circa un minuto; fino ad allora l'immagine è come senza NR.",
        ["Home opens ReShade; NR's settings are on its Add-ons page. The first start compiles for about a minute."] = "Home apre ReShade; le impostazioni di NR sono nella sua pagina Add-on. Il primo avvio compila per circa un minuto.",
        ["How many of the network's layers run in the faster, rougher form."] = "Quanti strati della rete girano nella forma più veloce e grezza.",
        ["Hybrid Launcher copies the stored file beside OptiScaler (uninstalling takes it out)."] = "Hybrid Launcher copia il file salvato accanto a OptiScaler (disinstallando lo toglie).",
        ["If NR Control keeps waiting for the game's upscaler, set [Spoofing] Dxgi=false in OptiScaler.ini. Its own log is in the Logs page."] = "Se NR Control continua ad aspettare l'upscaler del gioco, imposta [Spoofing] Dxgi=false in OptiScaler.ini. Il suo log è nella pagina Log.",
        ["In game"] = "In gioco",
        ["In this game: {0}"] = "In questo gioco: {0}",
        ["Install OptiScaler first: the latest nightly loads .asi plugins."] = "Installa prima OptiScaler: l'ultima nightly carica i plugin .asi.",
        ["Install janblade's F5 Multipass from the OptiScaler tab."] = "Installa F5 Multipass di janblade dalla scheda OptiScaler.",
        ["It says so now: pick the 310.9 model file."] = "Ora lo dice: scegli il file del modello 310.9.",
        ["Keeping what games need…"] = "Conservo ciò che serve ai giochi…",
        ["Keeps the game's HUD out of the network's work."] = "Tiene l'HUD del gioco fuori dal lavoro della rete.",
        ["Lays it over this game's OptiScaler."] = "Lo mette sopra l'OptiScaler di questo gioco.",
        ["Logs"] = "Log",
        ["Making the networks' weights from your model file (a minute or two)…"] = "Creo i pesi delle reti dal tuo file del modello (un minuto o due)…",
        ["Memory guard"] = "Protezione memoria",
        ["Model backend"] = "Backend del modello",
        ["Model file"] = "File del modello",
        ["More passes make a stronger effect and cost more time; 1 is the guide's setting."] = "Più passaggi danno un effetto più forte e costano più tempo; 1 è l'impostazione della guida.",
        ["Motion vectors come from ReShade's VORT effects, put in with it. Do not use it in online games with anti-cheat."] = "I motion vector arrivano dagli effetti VORT di ReShade, installati insieme. Non usarlo nei giochi online con anti-cheat.",
        ["NVIDIA's {0}"] = "{0} di NVIDIA",
        ["Needs the model"] = "Serve il modello",
        ["Network"] = "Rete",
        ["Neural rendering"] = "Rendering neurale",
        ["New enough"] = "Abbastanza recente",
        ["Newest: {0} ({1:d})."] = "Più recente: {0} ({1:d}).",
        ["No OptiScaler in this game yet."] = "Ancora nessun OptiScaler in questo gioco.",
        ["No OptiScaler in this game: install the latest nightly."] = "Nessun OptiScaler in questo gioco: installa l'ultima nightly.",
        ["No OptiScaler or ReShade of Hybrid Launcher in this game"] = "Nessun OptiScaler o ReShade di Hybrid Launcher in questo gioco",
