        ["Older AMD"] = "AMD meno recente",
        ["On: DLSSNR-AMD {0} through ReShade, network {1}. In game, Home opens ReShade; NR is on its Add-ons page."] = "Attivo: DLSSNR-AMD {0} tramite ReShade, rete {1}. In gioco, Home apre ReShade; NR è nella sua pagina Add-on.",
        ["On: DLSSNR-AMD {0}, network {1}. In game, End opens NR Control."] = "Attivo: DLSSNR-AMD {0}, rete {1}. In gioco, Fine apre NR Control.",
        ["On: F5 {0} through {1}. In game, Insert opens OptiScaler's menu."] = "Attivo: F5 {0} tramite {1}. In gioco, Ins apre il menu di OptiScaler.",
