        ["OptiScaler {0} is not F5: install the F5 build from the OptiScaler tab (it replaces this one)."] = "OptiScaler {0} non è F5: installa la build F5 dalla scheda OptiScaler (sostituisce questa).",
        ["Optimized layers"] = "Strati ottimizzati",
        ["Optional-Vendor-Neutral-DLSS5-Forwarder.zip from the same release, extracted into the game folder."] = "Optional-Vendor-Neutral-DLSS5-Forwarder.zip della stessa release, estratto nella cartella del gioco.",
        ["Over OptiScaler {0}. Uninstalling OptiScaler takes it out too."] = "Sopra OptiScaler {0}. Disinstallare OptiScaler toglie anche questo.",
        ["Overview"] = "Panoramica",
        ["Package"] = "Pacchetto",
        ["Passes"] = "Passaggi",
        ["Performance"] = "Prestazioni",
        ["Pick 310.9.16…"] = "Scegli la 310.9.16…",
        ["Pick NVIDIA's {0} 310.9.16 (all networks) or 310.8.0: only its weights are read."] = "Scegli {0} 310.9.16 di NVIDIA (tutte le reti) o la 310.8.0: vengono letti solo i suoi pesi.",
        ["Picked from what the game uses; change it when the game runs another one. DirectX 9 goes through DXVK (Vulkan), as the package does it."] = "Scelta in base a ciò che usa il gioco; cambiala se il gioco ne usa un'altra. DirectX 9 passa per DXVK (Vulkan), come fa il pacchetto.",
        ["Pick…"] = "Scegli…",
        ["Prepare"] = "Prepara",
        ["Prepare again"] = "Prepara di nuovo",
        ["Prepare the package first."] = "Prepara prima il pacchetto.",
        ["Prepared before the ReShade way existed: prepare it again to get ReShade's files."] = "Preparato prima che esistesse la strada di ReShade: preparalo di nuovo per avere i file di ReShade.",
        ["Processing style"] = "Stile di elaborazione",
        ["Put in"] = "Installa",
        ["Put in this game"] = "Installa in questo gioco",
        ["Put it in every F5 install"] = "Mettilo in ogni installazione F5",
        ["Put it in this game's F5 install"] = "Mettilo nell'installazione F5 di questo gioco",
        ["Puts DLSSNR-AMD in with the network below as the one the game starts with."] = "Installa DLSSNR-AMD con la rete qui sotto come quella con cui parte il gioco.",
        ["Puts ReShade with the NR add-on in this game, with the network below as the one it starts with. Files of the same names are kept aside."] = "Installa ReShade con l'add-on NR in questo gioco, con la rete qui sotto come quella con cui parte. I file con lo stesso nome vengono messi da parte.",
        ["Puts it in through ReShade ({0})."] = "Lo installa tramite ReShade ({0}).",
        ["Puts the F5Low frame generation published beside the build in with it (NVIDIA RTX only)."] = "Installa insieme il frame generation F5Low pubblicato accanto alla build (solo NVIDIA RTX).",
        ["Putting DLSSNR-AMD in…"] = "Installazione di DLSSNR-AMD…",
        ["Quality"] = "Qualità",
        ["RTX 20, 30 and 40 cards need ShortFuse's modified 310.8 build (pinned in the RenoDX Discord); NVIDIA's own runs on RTX 50 only."] = "Le schede RTX 20, 30 e 40 richiedono la build 310.8 modificata da ShortFuse (fissata nel Discord di RenoDX); quella di NVIDIA funziona solo sulle RTX 50.",
        ["RTX 50: NVIDIA's own 310.8. RTX 20, 30 and 40: ShortFuse's modified 310.8 (pinned in the RenoDX Discord); Windows calls its signature invalid, which is expected. Driver 616.56 or newer."] = "RTX 50: la 310.8 di NVIDIA. RTX 20, 30 e 40: la 310.8 modificata da ShortFuse (fissata nel Discord di RenoDX); Windows dice che la firma non è valida, ed è normale. Driver 616.56 o più recente.",
        ["RX 7000 and Radeon 700M / 800M: experimental, CC_SMALL_FP8 and CC_SILVER_AARDWOLD only, and none at all when the driver cannot take the prepared machine code."] = "RX 7000 e Radeon 700M / 800M: sperimentale, solo CC_SMALL_FP8 e CC_SILVER_AARDWOLD, e nessuna quando il driver non accetta il codice macchina preparato.",
        ["Ready"] = "Pronto",
        ["Reset"] = "Ripristina",
        ["Runs on the finished picture: native DirectX 12 games only (not Vulkan, not DirectX 11)."] = "Lavora sull'immagine finale: solo giochi DirectX 12 nativi (non Vulkan, non DirectX 11).",
        ["Runs the model"] = "Esegue il modello",
        ["Show F5 builds"] = "Mostra build F5",
        ["Show nightly builds"] = "Mostra build nightly",
        ["Steps for {0}"] = "Passi per {0}",
        ["Take out"] = "Togli",
        ["Taking DLSSNR-AMD out…"] = "Rimozione di DLSSNR-AMD…",
        ["The F5 build in this game"] = "La build F5 in questo gioco",
        ["The ReShade way brings its own ReShade."] = "La strada di ReShade porta il suo ReShade.",
        ["The game folder was not found."] = "La cartella del gioco non è stata trovata.",
        ["The model file in this game"] = "Il file del modello in questo gioco",
        ["The prepared DLSSNR-AMD has no ReShade files: prepare it again."] = "Il DLSSNR-AMD preparato non ha i file di ReShade: preparalo di nuovo.",
        ["The size the network works at, against the output."] = "La dimensione a cui lavora la rete, rispetto all'uscita.",
        ["The vendor-neutral port"] = "Il port indipendente dal produttore",
        ["The vendor-neutral port needs {0} {1} or newer (this one is {2}), or it runs the large network slowly."] = "Il port indipendente richiede {0} {1} o più recente (questo è {2}), altrimenti esegue lentamente la rete grande.",
        ["These two networks need the model of NVIDIA's {0} 310.9.16; this package was made from {1}. Pick the 310.9.16 file: Hybrid Launcher keeps it as the model file and prepares the package again with all four networks."] = "Queste due reti richiedono il modello di {0} 310.9.16 di NVIDIA; questo pacchetto è stato creato da {1}. Scegli il file 310.9.16: Hybrid Launcher lo tiene come file del modello e prepara di nuovo il pacchetto con tutte e quattro le reti.",
        ["This OptiScaler cannot load .asi plugins (no [Plugins] LoadAsiPlugins): install a recent nightly."] = "Questo OptiScaler non può caricare plugin .asi (manca [Plugins] LoadAsiPlugins): installa una nightly recente.",
        ["This OptiScaler install has no OptiScaler.ini."] = "Questa installazione di OptiScaler non ha OptiScaler.ini.",
        ["This file works."] = "Questo file funziona.",
        ["This game has DLSSNR-AMD: take it out first (the two do not go together)."] = "Questo gioco ha DLSSNR-AMD: toglilo prima (i due non vanno insieme).",
        ["This game has F5 ({0}), but not NVIDIA's {1} yet: Set up DLSS 5 → Model file."] = "Questo gioco ha F5 ({0}), ma non ancora {1} di NVIDIA: Configura DLSS 5 → File del modello.",
        ["This game has OptiScaler from Hybrid Launcher: uninstall it first, or put DLSSNR-AMD in through OptiScaler."] = "Questo gioco ha OptiScaler da Hybrid Launcher: disinstallalo prima, oppure installa DLSSNR-AMD tramite OptiScaler.",
        ["This game has ReShade from Hybrid Launcher's ReShade section: uninstall it there first. The ReShade way brings its own ReShade."] = "Questo gioco ha ReShade dalla sezione ReShade di Hybrid Launcher: disinstallalo lì prima. La strada di ReShade porta il suo ReShade.",
        ["This game has a DLSS NR fork of OptiScaler (F5): DLSSNR-AMD goes with the official OptiScaler instead."] = "Questo gioco ha un fork DLSS NR di OptiScaler (F5): DLSSNR-AMD va invece con l'OptiScaler ufficiale.",
        ["This game only; it follows the switch above until you change it here."] = "Solo questo gioco; segue l'interruttore qui sopra finché non lo cambi qui.",
        ["This {0} is {1}: the two networks need 310.9.16."] = "Questo {0} è {1}: le due reti richiedono la 310.9.16.",
        ["Through OptiScaler: for games with DLSS, FSR or XeSS, OptiScaler does the upscaling. Through ReShade: no OptiScaler, any 64-bit game; ReShade's VORT effects give NR the motion vectors."] = "Tramite OptiScaler: per i giochi con DLSS, FSR o XeSS, OptiScaler fa l'upscaling. Tramite ReShade: senza OptiScaler, qualsiasi gioco a 64 bit; gli effetti VORT di ReShade danno a NR i motion vector.",
        ["Through ReShade"] = "Tramite ReShade",
        ["Through ReShade, {0}. Taking it out puts back the game's own files of the same names."] = "Tramite ReShade, {0}. Toglierlo rimette i file del gioco con lo stesso nome.",
        ["Too old"] = "Troppo vecchio",
        ["Turn on DLSS, FSR or XeSS in the game's settings. End opens NR Control; the first start compiles for about a minute."] = "Attiva DLSS, FSR o XeSS nelle impostazioni del gioco. Fine apre NR Control; il primo avvio compila per circa un minuto.",
        ["Turn on DLSS, FSR or XeSS in the game's settings. Insert opens OptiScaler's menu: turn on Neural Rendering there, its status line names the backend."] = "Attiva DLSS, FSR o XeSS nelle impostazioni del gioco. Ins apre il menu di OptiScaler: attiva lì Neural Rendering, la sua riga di stato indica il backend.",
        ["Turn on DLSS, FSR or XeSS in the game's settings: DLSS 5 runs on what the game's upscaler hands OptiScaler. Games with an upscaler of their own shaders never hand it over."] = "Attiva DLSS, FSR o XeSS nelle impostazioni del gioco: DLSS 5 lavora su ciò che l'upscaler del gioco passa a OptiScaler. I giochi con un upscaler fatto con shader propri non lo passano mai.",
        ["Turn on DLSS, FSR or XeSS in the game. End opens NR Control (every NR setting), Insert OptiScaler's menu, Ctrl+F11 cycles the networks, F6 turns NR off and on. The first start compiles for about a minute; until then the picture looks as without NR."] = "Attiva DLSS, FSR o XeSS nel gioco. Fine apre NR Control (tutte le impostazioni di NR), Ins il menu di OptiScaler, Ctrl+F11 cambia rete, F6 spegne e accende NR. Il primo avvio compila per circa un minuto; fino ad allora l'immagine è come senza NR.",
        ["Ultra Performance"] = "Ultra Prestazioni",
        ["Unknown card"] = "Scheda sconosciuta",
        ["Unpacking…"] = "Estrazione…",
        ["Use this"] = "Usa questo",
        ["Vendor-neutral port (any DirectX 12 card)"] = "Port indipendente dal produttore (qualsiasi scheda DirectX 12)",
        ["Vulkan"] = "Vulkan",
        ["Way in"] = "Strada",
        ["Ways that run on this PC"] = "Strade che funzionano su questo PC",
        ["What happens before and after the network: RenoDX's DLSS 5 add-on, or OptiScaler-NR's original (wilsjo2)."] = "Cosa succede prima e dopo la rete: l'add-on DLSS 5 di RenoDX, o l'originale di OptiScaler-NR (wilsjo2).",
        ["Which ways it fits"] = "Con quali strade funziona",
        ["Working scale"] = "Scala di lavoro",
        ["Writes dlssnr-amd.ini again as the package has it, with the network above."] = "Riscrive dlssnr-amd.ini come lo ha il pacchetto, con la rete qui sopra.",
        ["Written in the game folder while the game runs. Open them when DLSS 5 does not start."] = "Scritti nella cartella del gioco mentre il gioco è in esecuzione. Aprili quando DLSS 5 non parte.",
        ["Written to dlssnr-amd.ini; NR reads it again while the game runs. NR Control (End) changes the same settings in game."] = "Scritto in dlssnr-amd.ini; NR lo rilegge mentre il gioco è in esecuzione. NR Control (Fine) cambia le stesse impostazioni in gioco.",
        ["[DlssNr] in OptiScaler.ini; the OptiScaler menu (Insert) changes them in game too. Its status line says which backend runs the model."] = "[DlssNr] in OptiScaler.ini; anche il menu di OptiScaler (Ins) le cambia in gioco. La sua riga di stato dice quale backend esegue il modello.",
        ["dlssnr-amd.ini has no {0} in [{1}]."] = "dlssnr-amd.ini non ha {0} in [{1}].",
        ["janblade's F5 Multipass is a fork of OptiScaler with DLSS 5 built in. On an RTX card NVIDIA's NGX runs the model: the build, the model file beside it, and the driver 616.56 or newer."] = "F5 Multipass di janblade è un fork di OptiScaler con DLSS 5 integrato. Su una scheda RTX il modello lo esegue NGX di NVIDIA: la build, il file del modello accanto e il driver 616.56 o più recente.",
        ["janblade's F5 Multipass is a fork of OptiScaler with DLSS 5 built in. Without an RTX card its vendor-neutral port (Optional-Vendor-Neutral-DLSS5-Forwarder.zip from the same release) runs the model with DirectX 12 compute; Hybrid Launcher puts it in the game folder with nr_port.ini, beside NVIDIA's model file."] = "F5 Multipass di janblade è un fork di OptiScaler con DLSS 5 integrato. Senza una scheda RTX il suo port indipendente dal produttore (Optional-Vendor-Neutral-DLSS5-Forwarder.zip della stessa release) esegue il modello con il compute di DirectX 12; Hybrid Launcher lo mette nella cartella del gioco con nr_port.ini, accanto al file del modello di NVIDIA.",
        ["janblade's OptiScaler fork with NVIDIA's NGX: the reference way on RTX 20 to 50, with F5Low frame generation as an option. It needs the 310.8 model file."] = "Il fork di OptiScaler di janblade con NGX di NVIDIA: la strada di riferimento su RTX da 20 a 50, con il frame generation F5Low come opzione. Richiede il file del modello 310.8.",
        ["janblade's OptiScaler fork with its vendor-neutral port: the model runs with DirectX 12 compute on any card. Its author tested it on NVIDIA only. It needs the 310.9 model file, or it runs the large network slowly."] = "Il fork di OptiScaler di janblade con il suo port indipendente dal produttore: il modello gira con il compute di DirectX 12 su qualsiasi scheda. L'autore l'ha provato solo su NVIDIA. Richiede il file del modello 310.9, altrimenti esegue lentamente la rete grande.",
        ["mochizuki0323's DLSSNR-AMD runs DLSS 5's network natively on Radeon (Vulkan, AMD's own matrix units), as an .asi plugin of the official OptiScaler or, in any 64-bit game, as a ReShade add-on. Hybrid Launcher runs its installer once to make and check the networks' weights from your model file, then puts it in this game the way you pick below."] = "DLSSNR-AMD di mochizuki0323 esegue la rete di DLSS 5 in modo nativo su Radeon (Vulkan, le unità matriciali di AMD), come plugin .asi dell'OptiScaler ufficiale o, in qualsiasi gioco a 64 bit, come add-on di ReShade. Hybrid Launcher esegue una volta il suo installer per creare e controllare i pesi delle reti dal tuo file del modello, poi lo mette in questo gioco nel modo che scegli qui sotto.",
        ["mochizuki0323's port runs NVIDIA's network natively on Radeon through Vulkan, as a plugin of the official OptiScaler. RX 9000 runs all four networks; RX 7000 and Radeon 700M / 800M are experimental, with two. Hybrid Launcher makes its weights once from your model file."] = "Il port di mochizuki0323 esegue la rete di NVIDIA in modo nativo su Radeon tramite Vulkan, come plugin dell'OptiScaler ufficiale. Le RX 9000 eseguono tutte e quattro le reti; RX 7000 e Radeon 700M / 800M sono sperimentali, con due. Hybrid Launcher ne crea i pesi una volta dal tuo file del modello.",
        ["nvngx.dll_dlssnr.dll is the port, with nr_port.ini."] = "nvngx.dll_dlssnr.dll è il port, con nr_port.ini.",
        ["the vendor-neutral port"] = "il port indipendente dal produttore",
        ["{0} is in."] = "{0} è installato.",
        ["{0} is missing: Model file page."] = "Manca {0}: pagina File del modello.",
        ["{0} is not a DLSSNR-AMD package Hybrid Launcher knows (no install.ps1)."] = "{0} non è un pacchetto DLSSNR-AMD che Hybrid Launcher conosce (manca install.ps1).",
        ["{0} is the normal ReShade build, which loads only a few add-ons. RenoDX and Luma need the build with full add-on support: install it again from ReShade's section (the version marked \"with full add-on support\")."] = "{0} è la build normale di ReShade, che carica solo pochi add-on. RenoDX e Luma richiedono la build con supporto completo agli add-on: reinstallala dalla sezione di ReShade (la versione segnata \"with full add-on support\").",
        ["{0}, NVIDIA's signed build"] = "{0}, la build firmata di NVIDIA",
        ["{0}, ShortFuse's build for RTX 20 / 30 / 40"] = "{0}, la build di ShortFuse per RTX 20 / 30 / 40",
        ["{0}, network {1}"] = "{0}, rete {1}",
        ["{0}, prepared {1:d} from {2} {3}: {4}. {5} on this PC."] = "{0}, preparato il {1:d} da {2} {3}: {4}. {5} su questo PC.",
        ["{0}, {1}"] = "{0}, {1}",
        ["{0}, {1}, network {2}"] = "{0}, {1}, rete {2}",
        ["{0}: DLSSNR-AMD and its ReShade taken out; the game's own files are back."] = "{0}: DLSSNR-AMD e il suo ReShade tolti; i file del gioco sono tornati.",
        ["{0}: DLSSNR-AMD taken out; OptiScaler stays."] = "{0}: DLSSNR-AMD tolto; OptiScaler resta.",
        ["{0}: DLSSNR-AMD was not put back. {1}"] = "{0}: DLSSNR-AMD non è stato rimesso. {1}",
        ["{0}: DLSSNR-AMD {1} is in through ReShade. In game, Home opens ReShade."] = "{0}: DLSSNR-AMD {1} è installato tramite ReShade. In gioco, Home apre ReShade.",
        ["{0}: DLSSNR-AMD {1} is in. Turn on DLSS, FSR or XeSS in the game; End opens NR Control."] = "{0}: DLSSNR-AMD {1} è installato. Attiva DLSS, FSR o XeSS nel gioco; Fine apre NR Control.",
        ["{0}: {1}"] = "{0}: {1}",
        ["A game's page opens on its Dashboard: trailer, the newest update and its patch notes read in the app, your play time, achievements and mods."] = "La pagina di un gioco si apre sulla sua Dashboard: trailer, l'ultimo aggiornamento con le note di patch lette nell'app, il tuo tempo di gioco, obiettivi e mod.",
        ["The Mods tab lists every mod in the game folder, what loads it and whether it works, with a fix for each conflict."] = "La scheda Mod elenca ogni mod nella cartella del gioco, cosa la carica e se funziona, con una correzione per ogni conflitto.",
        ["DLSS 5 (early, experimental): DLSSNR-AMD on Radeon RX 9000 and RX 7000, janblade's F5 Multipass on NVIDIA, set up step by step."] = "DLSS 5 (in anteprima, sperimentale): DLSSNR-AMD su Radeon RX 9000 e RX 7000, F5 Multipass di janblade su NVIDIA, configurati passo per passo.",
        ["DXVK, DXVK-gplasync and VKD3D-Proton in a click, and OptiScaler's file name changed without reinstalling."] = "DXVK, DXVK-gplasync e VKD3D-Proton con un clic, e il nome del file di OptiScaler cambiato senza reinstallare.",
        ["Ubisoft Connect, EA app and Rockstar games are found; the Library has a Last played section and Play on every cover."] = "I giochi di Ubisoft Connect, EA app e Rockstar vengono trovati; la Libreria ha la sezione Ultima partita e Gioca su ogni copertina.",
        ["Xbox achievements, an unlock history with a screenshot of each unlock, and smooth mouse-wheel scrolling everywhere."] = "Obiettivi Xbox, una cronologia degli sblocchi con uno screenshot di ognuno, e scorrimento fluido con la rotella ovunque.",
        ["About DLSS 5"] = "Informazioni su DLSS 5",
        ["About DLSSNR-AMD"] = "Informazioni su DLSSNR-AMD",
        ["About F5 Multipass"] = "Informazioni su F5 Multipass",
        ["Change the model file…"] = "Cambia il file del modello…",
        ["Copied beside OptiScaler (uninstalling takes it out)."] = "Copiato accanto a OptiScaler (la disinstallazione lo toglie).",
        ["Could not set up DLSS 5"] = "Impossibile configurare DLSS 5",
        ["DLSS 5 (experimental)"] = "DLSS 5 (sperimentale)",
        ["Downloaded and prepared from your model file, once for every game."] = "Scaricato e preparato dal tuo file del modello, una volta per tutti i giochi.",
        ["Free for the ReShade way, which brings its own ReShade."] = "Libero per la strada di ReShade, che porta il suo ReShade.",
        ["From the same release, extracted into the game folder."] = "Dalla stessa release, estratto nella cartella del gioco.",
        ["Goes in through ReShade ({0})."] = "Si installa tramite ReShade ({0}).",
        ["In game: Home opens ReShade; NR's settings are on its Add-ons page. The first start compiles for about a minute."] = "In gioco: Home apre ReShade; le impostazioni di NR sono nella sua pagina Add-ons. Il primo avvio compila per circa un minuto.",
        ["In game: turn on DLSS, FSR or XeSS in the game's settings. End opens NR Control; the first start compiles for about a minute."] = "In gioco: attiva DLSS, FSR o XeSS nelle impostazioni del gioco. Fine apre NR Control; il primo avvio compila per circa un minuto.",
        ["In game: turn on DLSS, FSR or XeSS in the game's settings. Insert opens OptiScaler's menu: turn on Neural Rendering there, its status line names the backend."] = "In gioco: attiva DLSS, FSR o XeSS nelle impostazioni del gioco. Ins apre il menu di OptiScaler: attiva lì Neural Rendering, la sua riga di stato indica il backend.",
        ["In the game folder, with nr_port.ini."] = "Nella cartella del gioco, con nr_port.ini.",
        ["In this game"] = "In questo gioco",
        ["LATEST ACHIEVEMENTS"] = "ULTIMI OBIETTIVI",
        ["Laid over this game's OptiScaler."] = "Messo sopra l'OptiScaler di questo gioco.",
        ["Model in this game"] = "Modello in questo gioco",
        ["Next: {0}. {1}"] = "Prossimo: {0}. {1}",
        ["Not in this game: install janblade's F5 Multipass from the OptiScaler tab."] = "Non in questo gioco: installa F5 Multipass di janblade dalla scheda OptiScaler.",
        ["Not in this game: the latest nightly loads plugins."] = "Non in questo gioco: l'ultima nightly carica i plugin.",
        ["Not possible"] = "Non possibile",
        ["OptiScaler {0} is not F5: the F5 build replaces it."] = "OptiScaler {0} non è F5: la build F5 lo sostituisce.",
        ["Pick the model file…"] = "Scegli il file del modello…",
        ["Search results"] = "Risultati della ricerca",
        ["The achievements you unlock show here, from every game."] = "Gli obiettivi che sblocchi compaiono qui, da tutti i giochi.",
        ["Vendor-neutral port"] = "Port indipendente dal produttore",
        ["{0:#,0} h played"] = "{0:#,0} h di gioco",
        ["{0:#,0} of {1:#,0} achievements"] = "{0:#,0} obiettivi su {1:#,0}",
        ["{0} is set up in this game"] = "{0} è configurato in questo gioco",
        ["{0} minute played"] = "{0} minuto di gioco",
        ["{0} minutes played"] = "{0} minuti di gioco",
        ["{0} setting matches"] = "{0} impostazione trovata",
        ["{0} settings match"] = "{0} impostazioni trovate",
        ["{0} this week"] = "{0} questa settimana",
        ["{0}+ this week"] = "{0}+ questa settimana",
        ["{0}, loads plugins"] = "{0}, carica i plugin",
        ["{0}: {1} of {2} ready"] = "{0}: {1} di {2} pronti",
        ["Show fewer"] = "Mostra meno",
        // ---- Auto tab (2.0.0-rc.7) ----
        ["32-bit"] = "32 bit",
        ["64-bit"] = "64 bit",
        ["A Luma mod is already in this game."] = "Una mod Luma è già in questo gioco.",
        ["A RenoDX mod is already in this game."] = "Una mod RenoDX è già in questo gioco.",
        ["A RenoDX mod is already in: Luma is left out (both are HDR mods)."] = "Una mod RenoDX è già presente: Luma resta fuori (sono entrambe mod HDR).",
        ["AMD / Intel card"] = "Scheda AMD / Intel",
        ["AMD / Intel card: Nvidia spoofing on, so the game offers DLSS for OptiScaler to replace"] = "Scheda AMD / Intel: spoofing Nvidia attivo, così il gioco offre il DLSS che OptiScaler sostituisce",
        ["Already in this game as {0}. Updates are in the OptiScaler tab."] = "Già in questo gioco come {0}. Gli aggiornamenti sono nella scheda OptiScaler.",
        ["An HDR mod, and a display of this PC has HDR on."] = "Una mod HDR, e uno schermo di questo PC ha l'HDR attivo.",
        ["An HDR mod: tick it if you play in HDR (no display of this PC has HDR on now)."] = "Una mod HDR: spuntala se giochi in HDR (ora nessuno schermo di questo PC ha l'HDR attivo).",
        ["Another install is running in this game."] = "Un'altra installazione è in corso in questo gioco.",
        ["As ReShade64.dll, loaded by OptiScaler"] = "Come ReShade64.dll, caricato da OptiScaler",
        ["As {0}, the name the OptiScaler wiki gives for this game"] = "Come {0}, il nome indicato dalla wiki di OptiScaler per questo gioco",
        ["Auto setup"] = "Configurazione automatica",
        ["Brings its own ReShade with full add-on support"] = "Porta il suo ReShade con supporto completo agli add-on",
        ["Comes with Luma"] = "Incluso in Luma",
        ["Conflicts handled"] = "Conflitti risolti",
        ["Could not list ReShade releases. Check the connection and try again."] = "Impossibile elencare le versioni di ReShade. Controlla la connessione e riprova.",
        ["Could not read the game: {0}"] = "Impossibile leggere il gioco: {0}",
        ["DLSSNR-AMD is in through its own ReShade. Take it out first (Mods → DLSS 5)."] = "DLSSNR-AMD è installato tramite il suo ReShade. Toglilo prima (Mod → DLSS 5).",
        ["DXVK or VKD3D-Proton is in this game: it renders through Vulkan, so OptiScaler is left out unless you tick it."] = "In questo gioco c'è DXVK o VKD3D-Proton: disegna tramite Vulkan, quindi OptiScaler resta fuori a meno che tu non lo spunti.",
        ["Done: {0} set up in {1}."] = "Fatto: {0} configurato in {1}.",
        ["Every file name OptiScaler can load as is taken by another mod in this folder."] = "Ogni nome di file con cui OptiScaler può caricarsi è già usato da un'altra mod in questa cartella.",
        ["Everything this game can use is already in, or needs a choice of its own in its tab."] = "Tutto ciò che questo gioco può usare è già presente, o richiede una scelta nella sua scheda.",
        ["Graphics API from {0}."] = "API grafica da {0}.",
        ["Graphics API not known"] = "API grafica sconosciuta",
        ["HDR off"] = "HDR spento",
        ["Hybrid Launcher cannot write there without administrator rights. Install OptiScaler from its tab once to restart as administrator, then come back."] = "Hybrid Launcher non può scrivere lì senza diritti di amministratore. Installa OptiScaler una volta dalla sua scheda per riavviare come amministratore, poi torna qui.",
        ["In as {0}, {1}"] = "Installato come {0}, {1}",
        ["Install 1 mod"] = "Installa 1 mod",
        ["Install {0} mods"] = "Installa {0} mod",
        ["Its settings are on ReShade's Add-ons page (Home in game)"] = "Le sue impostazioni sono nella pagina Add-on di ReShade (Home in gioco)",
        ["Last run"] = "Ultima esecuzione",
        ["Left out: Luma is ticked, and only one HDR mod goes in."] = "Escluso: Luma è spuntato, e si installa una sola mod HDR.",
        ["Left out: RenoDX is ticked, and only one HDR mod goes in."] = "Escluso: RenoDX è spuntato, e si installa una sola mod HDR.",
        ["Listed as in progress."] = "Indicata come in sviluppo.",
        ["Luma brings its own ReShade with full add-on support."] = "Luma porta il suo ReShade con supporto completo agli add-on.",
        ["Luma needs ReShade as a proxy dll, which DXVK or VKD3D-Proton holds in this game."] = "Luma richiede ReShade come dll proxy, che in questo gioco è occupata da DXVK o VKD3D-Proton.",
        ["Needed by another ticked mod"] = "Richiesto da un'altra mod spuntata",
        ["No Luma build to install."] = "Nessuna build di Luma da installare.",
        ["No Luma mod is listed for this game."] = "Nessuna mod Luma è elencata per questo gioco.",
        ["No RenoDX mod is listed for this game."] = "Nessuna mod RenoDX è elencata per questo gioco.",
        ["Not for this game"] = "Non per questo gioco",
        ["Not installed (see the message above)"] = "Non installato (vedi il messaggio sopra)",
        ["Nothing to install"] = "Niente da installare",
        ["Nvidia card"] = "Scheda Nvidia",
        ["Nvidia card: DLSS inputs work without spoofing"] = "Scheda Nvidia: gli input DLSS funzionano senza spoofing",
        ["On the OptiScaler wiki"] = "Nella wiki di OptiScaler",
        ["Open Ultra+"] = "Apri Ultra+",
        ["OptiPatcher when the game is on its list"] = "OptiPatcher se il gioco è nella sua lista",
        ["OptiScaler loads Luma's ReShade (ReShade64.dll)"] = "OptiScaler carica il ReShade di Luma (ReShade64.dll)",
        ["OptiScaler tab"] = "Scheda OptiScaler",
        ["Optional"] = "Facoltativo",
        ["Own tab"] = "Scheda propria",
        ["Part of the one click"] = "Incluso nel clic unico",
        ["Performance mode on, the tutorial skipped, overlay on Home"] = "Modalità prestazioni attiva, tutorial saltato, overlay su Home",
        ["Plan"] = "Piano",
        ["Post-processing filters (sharpening, colour, SMAA). Tick it if you want them."] = "Filtri di post-elaborazione (nitidezza, colore, SMAA). Spuntalo se li vuoi.",
        ["ReShade and OptiScaler would both be dxgi.dll: ReShade goes in as ReShade64.dll and OptiScaler loads it."] = "ReShade e OptiScaler sarebbero entrambi dxgi.dll: ReShade va come ReShade64.dll e lo carica OptiScaler.",
        ["ReShade is {0}, the name OptiScaler takes: it becomes ReShade64.dll and OptiScaler loads it."] = "ReShade è {0}, il nome che prende OptiScaler: diventa ReShade64.dll e lo carica OptiScaler.",
        ["ReShade stays {0}; OptiScaler goes in as {1} beside it."] = "ReShade resta {0}; OptiScaler va accanto come {1}.",
        ["ReShade {0} in as {1}"] = "ReShade {0} installato come {1}",
        ["ReShade {0} in as {1}, loaded by OptiScaler"] = "ReShade {0} installato come {1}, caricato da OptiScaler",
        ["ReShade {0} is already in as {1}."] = "ReShade {0} è già presente come {1}.",
        ["ReShade {0} is the normal build, which skips RenoDX: it is replaced by the build with full add-on support."] = "ReShade {0} è la build normale, che ignora RenoDX: viene sostituito dalla build con supporto completo agli add-on.",
        ["Read again"] = "Rileggi",
        ["RenoDX and Luma are both HDR mods: only one goes in. RenoDX is kept."] = "RenoDX e Luma sono entrambe mod HDR: se ne installa una sola. Resta RenoDX.",
        ["RenoDX needs ReShade as a proxy dll, which DXVK or VKD3D-Proton holds in this game."] = "RenoDX richiede ReShade come dll proxy, che in questo gioco è occupata da DXVK o VKD3D-Proton.",
        ["RenoDX runs inside ReShade."] = "RenoDX funziona dentro ReShade.",
        ["Skipped: it was to be loaded by OptiScaler, which did not go in"] = "Saltato: doveva caricarlo OptiScaler, che non è stato installato",
        ["Some mods did not go in"] = "Alcune mod non sono state installate",
        ["Spoofing off: the OptiScaler wiki says this game does not need it"] = "Spoofing spento: secondo la wiki di OptiScaler questo gioco non ne ha bisogno",
        ["Spoofing off: OptiPatcher supports this game and unlocks the DLSS inputs without it"] = "Spoofing spento: OptiPatcher supporta questo gioco e sblocca gli input DLSS senza",
        ["Nvidia spoofing on, as set on the OptiScaler tab"] = "Spoofing Nvidia acceso, come impostato nella scheda OptiScaler",
        ["Nvidia spoofing off, as set on the OptiScaler tab"] = "Spoofing Nvidia spento, come impostato nella scheda OptiScaler",
        ["OptiPatcher: this game is on its list"] = "OptiPatcher: questo gioco è nella sua lista",
        ["OptiPatcher: this game is not on its list"] = "OptiPatcher: questo gioco non è nella sua lista",
        ["Standard effects (SMAA, LumaSharpen, Vibrance and more) in reshade-shaders"] = "Effetti standard (SMAA, LumaSharpen, Vibrance e altri) in reshade-shaders",
        ["Start the game: Insert opens OptiScaler's menu, Home opens ReShade."] = "Avvia il gioco: Ins apre il menu di OptiScaler, Home apre ReShade.",
        ["The OptiScaler wiki names {0} for this game, but another mod holds it: OptiScaler goes in as {1}."] = "La wiki di OptiScaler indica {0} per questo gioco, ma lo usa un'altra mod: OptiScaler va come {1}.",
        ["The ReShade installer holds no archive Hybrid Launcher can read."] = "L'installer di ReShade non contiene un archivio che Hybrid Launcher sa leggere.",
        ["The RenoDX mod has no direct download."] = "La mod RenoDX non ha un download diretto.",
        ["The build with full add-on support (RenoDX needs it)"] = "La build con supporto completo agli add-on (serve a RenoDX)",
        ["The game folder is protected"] = "La cartella del gioco è protetta",
        ["The game is 32-bit; OptiScaler works only in 64-bit games."] = "Il gioco è a 32 bit; OptiScaler funziona solo nei giochi a 64 bit.",
        ["The game renders through Vulkan, where ReShade goes in as a layer: use ReShade's own installer (Mods → ReShade)."] = "Il gioco disegna tramite Vulkan, dove ReShade si installa come layer: usa l'installer di ReShade (Mod → ReShade).",
        ["The game renders with {0}; OptiScaler needs DirectX 11, DirectX 12 or Vulkan."] = "Il gioco usa {0}; OptiScaler richiede DirectX 11, DirectX 12 o Vulkan.",
        ["The mods this game can use, picked to work together, with recommended settings"] = "Le mod che questo gioco può usare, scelte per funzionare insieme, con le impostazioni consigliate",
        ["The newest stable release"] = "L'ultima versione stabile",
        ["The normal build (safer in online games)"] = "La build normale (più sicura nei giochi online)",
        ["Ticked mods go in with one click, in this order"] = "Le mod spuntate si installano con un clic, in quest'ordine",
        ["Ultra+ has a mod for this game. Its builds and add-ons are picked in the Ultra+ tab."] = "Ultra+ ha una mod per questo gioco. Build e add-on si scelgono nella scheda Ultra+.",
        ["Upscaling (FSR, XeSS, DLSS) and frame generation for any card, with its in-game menu on Insert."] = "Upscaling (FSR, XeSS, DLSS) e frame generation per qualsiasi scheda, con il suo menu in gioco su Ins.",
        ["Use the recommendation"] = "Usa il consiglio",
        ["Will be replaced"] = "Sarà sostituito",
        ["{0} has no build on GitHub yet: see Mods → Luma."] = "{0} non ha ancora build su GitHub: vedi Mod → Luma.",
        ["{0} has no direct download (Nexus Mods only): see Mods → RenoDX."] = "{0} non ha un download diretto (solo Nexus Mods): vedi Mod → RenoDX.",
        ["{0} in"] = "{0} installato",
        ["{0} in ({1})"] = "{0} installato ({1})",
        ["{0} is missing from the ReShade installer."] = "{0} manca nell'installer di ReShade.",
        ["{0} is taken by another mod in this folder."] = "{0} è già usato da un'altra mod in questa cartella.",
        ["{0} of {1}: {2}…"] = "{0} di {1}: {2}…",
        ["{0}, the newest snapshot ({1}-bit)"] = "{0}, l'ultimo snapshot ({1} bit)",
        ["{0}, the newest stable build"] = "{0}, l'ultima build stabile",
        ["OptiScaler, ReShade, RenoDX and Luma picked for this game and installed together with one click, with recommended settings"] = "OptiScaler, ReShade, RenoDX e Luma scelti per questo gioco e installati insieme con un clic, con le impostazioni consigliate",
        ["Experimental: OptiScaler, ReShade, RenoDX and Luma picked for this game and installed together with one click, with recommended settings"] = "Sperimentale: OptiScaler, ReShade, RenoDX e Luma scelti per questo gioco e installati insieme con un clic, con le impostazioni consigliate",
        ["Experimental"] = "Sperimentale",
        ["Add-on (full add-on support)"] = "Add-on (supporto completo agli add-on)",
        ["Build (needed by RenoDX)"] = "Build (richiesta da RenoDX)",
        ["Choose file…"] = "Scegli il file…",
        ["Not chosen yet"] = "Non ancora scelto",
        ["Model file ({0})"] = "File del modello ({0})",
        ["DLSS 5 is ticked: select its method, or untick it."] = "DLSS 5 è spuntato: seleziona il metodo, o togli la spunta.",
        ["Hide details"] = "Nascondi dettagli",
        ["Method"] = "Metodo",
        ["Not for this game:"] = "Non per questo gioco:",
        ["RenoDX needs the add-on build: it is picked for you."] = "RenoDX richiede la build add-on: viene scelta per te.",
        ["Select one"] = "Selezionane uno",
        ["Show details"] = "Mostra dettagli",
        ["Standard is safer in online games with anti-cheat. Add-on is needed by add-ons such as RenoDX."] = "Standard è più sicura nei giochi online con anti-cheat. Add-on serve agli add-on come RenoDX.",
        ["The build with full add-on support (avoid it in online games with anti-cheat)"] = "La build con supporto completo agli add-on (evitala nei giochi online con anti-cheat)",
        ["What each ticked mod goes in with: file name, build and settings"] = "Con cosa entra ogni mod spuntata: nome del file, build e impostazioni",
        ["• What you tick changes what the others can be: DLSS 5's F5 method needs janblade's F5 build of OptiScaler, DLSSNR-AMD a build without DLSS NR, and a Vulkan layer goes alone."] = "• Ciò che spunti cambia cosa possono essere le altre: il metodo F5 di DLSS 5 richiede la build F5 di OptiScaler di janblade, DLSSNR-AMD una build senza DLSS NR, e un layer Vulkan va da solo.",
        ["• RenoDX and Luma are HDR mods: only one goes in. RenoDX needs ReShade's add-on build, which is picked for you; Luma brings its own ReShade. Without them the standard build is safer in online games."] = "• RenoDX e Luma sono mod HDR: ne entra solo una. RenoDX richiede la build add-on di ReShade, che viene scelta per te; Luma porta il suo ReShade. Senza di loro la build standard è più sicura nei giochi online.",
        ["The Auto tab is new: it may pick something wrong for some games."] = "La scheda Auto è nuova: per alcuni giochi può scegliere qualcosa di sbagliato.",
        ["Experimental. Installing each mod from its own tab (OptiScaler, Mods, Ultra+) is recommended: you see what goes in, where and why, and you can undo one step at a time."] = "Sperimentale. È consigliato installare ogni mod dalla sua scheda (OptiScaler, Mod, Ultra+): vedi cosa entra, dove e perché, e puoi annullare un passo alla volta.",
        ["• Close the game before installing. Each mod goes in with the newest stable build."] = "• Chiudi il gioco prima di installare. Ogni mod si installa con l'ultima build stabile.",
        ["• Everything installed here is managed from its own place afterwards: OptiScaler in its tab, ReShade, RenoDX and Luma in Mods, where each can be updated or removed."] = "• Tutto ciò che installi qui si gestisce poi dal suo posto: OptiScaler nella sua scheda, ReShade, RenoDX e Luma in Mod, dove ognuno si aggiorna o si rimuove.",
        ["• With OptiScaler in the game, ReShade goes in as ReShade64.dll and OptiScaler loads it, so both work."] = "• Con OptiScaler nel gioco, ReShade va come ReShade64.dll e lo carica OptiScaler, così funzionano entrambi.",
        ["• RenoDX and Luma are HDR mods: only one goes in. RenoDX needs ReShade with full add-on support, which is picked for you; Luma brings its own ReShade."] = "• RenoDX e Luma sono mod HDR: se ne installa una sola. RenoDX richiede ReShade con supporto completo agli add-on, scelto per te; Luma porta il suo ReShade.",
        ["• In game: Insert opens OptiScaler's menu, Home opens ReShade (and the RenoDX or Luma settings on its Add-ons page)."] = "• In gioco: Ins apre il menu di OptiScaler, Home apre ReShade (e le impostazioni di RenoDX o Luma nella sua pagina Add-on).",
        ["• Files a mod replaces are backed up as set in Settings → Features, and put back when it is removed."] = "• I file che una mod sostituisce vengono salvati come impostato in Impostazioni → Funzionalità, e rimessi quando la togli.",
        // ---- Auto tab, modular (2.0.0-rc.8) ----
        ["A Luma mod is already in this game. Tick it to put the build picked below in its place."] = "Una mod Luma è già in questo gioco. Spuntala per mettere al suo posto la build scelta sotto.",
        ["A Luma mod is in: RenoDX is left out (both are HDR mods)."] = "C'è una mod Luma: RenoDX resta fuori (sono entrambe mod HDR).",
        ["A RenoDX mod is already in this game. Tick it to download its newest snapshot again."] = "Una mod RenoDX è già in questo gioco. Spuntala per scaricare di nuovo l'ultimo snapshot.",
        ["A Vulkan layer is already in this game. It is managed in Mods → DXVK."] = "In questo gioco c'è già un layer Vulkan. Si gestisce in Mod → DXVK.",
        ["Already in this game as {0}."] = "Già in questo gioco come {0}.",
        ["Already in this game as {0}. Tick it to put the build picked below in its place."] = "Già in questo gioco come {0}. Spuntalo per mettere al suo posto la build scelta sotto.",
        ["Auto ({0})"] = "Auto ({0})",
        ["Brings its own ReShade with the NR add-on; Home opens it in game"] = "Porta il suo ReShade con l'add-on NR; Home lo apre in gioco",
        ["Build: {0}"] = "Build: {0}",
        ["Comes with another pick"] = "Incluso in un'altra scelta",
        ["DLSS 5 needs a 64-bit DirectX 11, DirectX 12 or Vulkan game."] = "DLSS 5 richiede un gioco a 64 bit DirectX 11, DirectX 12 o Vulkan.",
        ["DLSS 5 package"] = "Pacchetto DLSS 5",
        ["DLSS 5's F5 method needs janblade's F5 build (or one you imported)."] = "Il metodo F5 di DLSS 5 richiede la build F5 di janblade (o una che hai importato).",
        ["DLSS 5's method goes through OptiScaler."] = "Il metodo di DLSS 5 passa da OptiScaler.",
        ["DLSS 5: {0}"] = "DLSS 5: {0}",
        ["DLSSNR-AMD brings its own ReShade with the NR add-on."] = "DLSSNR-AMD porta il suo ReShade con l'add-on NR.",
        ["DLSSNR-AMD goes into builds without DLSS NR that load plugins: the nightly is picked first."] = "DLSSNR-AMD va nelle build senza DLSS NR che caricano plugin: viene scelta prima la nightly.",
        ["DLSSNR-AMD is not prepared"] = "DLSSNR-AMD non è preparato",
        ["DLSSNR-AMD through OptiScaler"] = "DLSSNR-AMD tramite OptiScaler",
        ["DLSSNR-AMD through ReShade (no OptiScaler)"] = "DLSSNR-AMD tramite ReShade (senza OptiScaler)",
        ["DXVK for the game's Direct3D version, the release picked"] = "DXVK per la versione Direct3D del gioco, la release scelta",
        ["DXVK is ticked"] = "DXVK è spuntato",
        ["DXVK or VKD3D-Proton is in this game"] = "In questo gioco c'è DXVK o VKD3D-Proton",
        ["Direct3D through Vulkan: helps older games that stutter on AMD and Intel. Some mods may not work through it: try and see."] = "Direct3D tramite Vulkan: aiuta i giochi più vecchi che scattano su AMD e Intel. Alcune mod potrebbero non funzionare attraverso di esso: prova e vedi.",
        ["Every file it replaces is backed up"] = "Ogni file che sostituisce viene salvato",
        ["F5 Multipass (janblade's OptiScaler build)"] = "F5 Multipass (build di OptiScaler di janblade)",
        ["File name"] = "Nome del file",
        ["Graphics mods for this Unreal Engine game (ray tracing, fixes), loaded through UE4SS. Add-ons and settings are in the Ultra+ tab afterwards."] = "Mod grafiche per questo gioco Unreal Engine (ray tracing, correzioni), caricate tramite UE4SS. Add-on e impostazioni sono poi nella scheda Ultra+.",
        ["Imported: {0}"] = "Importata: {0}",
        ["Laid over OptiScaler as its plugin; End opens NR Control in game"] = "Installato su OptiScaler come suo plugin; Fine apre NR Control in gioco",
        ["Layer for {0}"] = "Layer per {0}",
        ["Left out: DLSSNR-AMD brings its own ReShade, and Luma brings another."] = "Escluso: DLSSNR-AMD porta il suo ReShade, e Luma ne porta un altro.",
        ["Left out: DLSSNR-AMD's ReShade sets other add-ons aside."] = "Escluso: il ReShade di DLSSNR-AMD mette da parte gli altri add-on.",
        ["Left out: DLSSNR-AMD's ReShade method goes without OptiScaler."] = "Escluso: il metodo ReShade di DLSSNR-AMD funziona senza OptiScaler.",
        ["NVIDIA's NGX runs it"] = "Lo esegue NGX di NVIDIA",
        ["Needed"] = "Necessario",
        ["Neural rendering. Tick it and select a method; it needs NVIDIA's nvngx_dlssnr.dll once (Hybrid Launcher asks for it and keeps it)."] = "Rendering neurale. Spuntalo e seleziona un metodo; serve una volta nvngx_dlssnr.dll di NVIDIA (Hybrid Launcher lo chiede e lo conserva).",
        ["No Ultra+ build to install."] = "Nessuna build di Ultra+ da installare.",
        ["No build picked"] = "Nessuna build scelta",
        ["No release picked"] = "Nessuna release scelta",
        ["Not laid over OptiScaler (see the message above)"] = "Non installato su OptiScaler (vedi il messaggio sopra)",
        ["Not prepared: DLSS 5 is skipped"] = "Non preparato: DLSS 5 viene saltato",
        ["Not put in (see the message above)"] = "Non installato (vedi il messaggio sopra)",
        ["(see the message above)"] = "(vedi il messaggio sopra)",
        ["Install puts in the ticked mods. Tick a mod that is already in, then Uninstall to take it out."] = "Installa mette le mod spuntate. Spunta una mod già presente, poi Disinstalla per toglierla.",
        ["Tick a mod that is in the game to uninstall it"] = "Spunta una mod presente nel gioco per disinstallarla",
        ["Uninstall {0} mods"] = "Disinstalla {0} mod",
        ["Tick it, then Uninstall to take it out"] = "Spuntala, poi Disinstalla per toglierla",
        ["Tick it, then Uninstall to take it out, or Install to put the build picked here in its place"] = "Spuntala, poi Disinstalla per toglierla, o Installa per mettere al suo posto la build scelta qui",
        ["Take the ticked mods out of this game, as their own tabs do (the files they replaced come back)"] = "Toglie le mod spuntate da questo gioco, come fanno le loro schede (tornano i file che avevano sostituito)",
        ["Tick the mods you want: Hybrid Launcher downloads each one and puts it in this game's folder in the right order, with settings that work together. What a mod replaces is backed up."] = "Spunta le mod che vuoi: Hybrid Launcher scarica ognuna e la mette nella cartella del gioco nell'ordine giusto, con impostazioni che funzionano insieme. Quello che una mod sostituisce viene salvato.",
        ["It is not in the game folder any more."] = "Non è più nella cartella del gioco.",
        ["It stopped without saying why: the log has the details."] = "Si è fermato senza dire perché: i dettagli sono nel log.",
        ["Last run, under the plan, says why and opens each mod's tab."] = "Ultima esecuzione, sotto il piano, dice perché e apre la scheda di ogni mod.",
        ["Not renamed"] = "Non rinominato",
        ["Nothing is ticked. Tick a mod to install it, or one that is in to put another build in its place."] = "Niente è spuntato. Spunta una mod per installarla, o una già presente per mettere un'altra build al suo posto.",
        ["Now {0}"] = "Ora {0}",
        ["OptiScaler is {0}, a name Ultra+ loads through: it is renamed to {1} first (nothing reinstalled)."] = "OptiScaler è {0}, un nome con cui si carica Ultra+: prima viene rinominato in {1} (senza reinstallare).",
        ["OptiScaler keeps a name Ultra+ does not load through"] = "OptiScaler tiene un nome che Ultra+ non usa",
        ["OptiScaler's file name"] = "Nome del file di OptiScaler",
        ["OptiScaler, ReShade or DLSS 5 is in: they need the game's own Direct3D. Take them out first to use a Vulkan layer."] = "C'è OptiScaler, ReShade o DLSS 5: richiedono il Direct3D del gioco. Toglili prima per usare un layer Vulkan.",
        ["Pick the mods and their builds; the plan keeps them working together"] = "Scegli le mod e le loro build; il piano le fa funzionare insieme",
        ["ReShade {0} is already in as {1}. Tick it to put the version picked below in its place."] = "ReShade {0} è già presente come {1}. Spuntalo per mettere al suo posto la versione scelta sotto.",
        ["Reading OptiScaler's builds…"] = "Lettura delle build di OptiScaler…",
        ["Reading the releases…"] = "Lettura delle release…",
        ["Read when ticked"] = "Lette quando la spunti",
        ["The F5 build is not in"] = "La build F5 non è installata",
        ["The OptiScaler build picked does not fit the DLSS 5 method: the one it needs is picked instead."] = "La build di OptiScaler scelta non va con il metodo DLSS 5: viene scelta quella necessaria.",
        ["The build in is a DLSS NR one, which DLSSNR-AMD does not go into: it is replaced by an official build."] = "La build presente è una DLSS NR, in cui DLSSNR-AMD non va: viene sostituita da una build ufficiale.",
        ["The build in is not F5: DLSS 5's F5 method replaces it with janblade's F5 build."] = "La build presente non è F5: il metodo F5 di DLSS 5 la sostituisce con la build F5 di janblade.",
        ["The build picked below, with its UE4SS"] = "La build scelta sotto, con il suo UE4SS",
        ["The game does not render with Direct3D: there is nothing to translate."] = "Il gioco non usa Direct3D: non c'è niente da tradurre.",
        ["The vendor-neutral port runs it on this card"] = "Su questa scheda lo esegue il port indipendente dal produttore",
        ["Tick to put the build picked here in its place"] = "Spunta per mettere al suo posto la build scelta qui",
        ["Ticked mods go in with one click, each in the right order"] = "Le mod spuntate si installano con un clic, ognuna nell'ordine giusto",
        ["Ultra+ has no mod for this game."] = "Ultra+ non ha una mod per questo gioco.",
        ["Ultra+ is in this game. Tick it to put the build picked below in its place; add-ons and settings are in the Ultra+ tab."] = "Ultra+ è in questo gioco. Spuntalo per mettere al suo posto la build scelta sotto; add-on e impostazioni sono nella scheda Ultra+.",
        ["Ultra+ {0} in"] = "Ultra+ {0} installato",
        ["VKD3D-Proton with DXVK's dxgi.dll, the release picked"] = "VKD3D-Proton con il dxgi.dll di DXVK, la release scelta",
        ["Way"] = "Metodo",
        ["in progress"] = "in sviluppo",
        ["newest"] = "la più recente",
        ["{0} belongs to {1}"] = "{0} appartiene a {1}",
        ["{0} in as {1}"] = "{0} installato come {1}",
        ["{0} is in this game. Its settings and networks are in Mods → DLSS 5."] = "{0} è in questo gioco. Impostazioni e reti sono in Mod → DLSS 5.",
        ["{0} is taken in this folder: OptiScaler goes in as {1}."] = "{0} è già usato in questa cartella: OptiScaler va come {1}.",
        ["{0} {1} in"] = "{0} {1} installato",
        ["{0}, the build picked below"] = "{0}, la build scelta sotto",
        ["{0}: DLSS 5 needs the game's own Direct3D."] = "{0}: DLSS 5 richiede il Direct3D del gioco.",
        ["{0}: Luma needs ReShade as a proxy dll."] = "{0}: Luma richiede ReShade come dll proxy.",
        ["{0}: OptiScaler's upscalers need the game's own Direct3D."] = "{0}: gli upscaler di OptiScaler richiedono il Direct3D del gioco.",
        ["{0}: ReShade would have to hook Vulkan (ReShade's own installer, Mods → ReShade)."] = "{0}: ReShade dovrebbe agganciarsi a Vulkan (installer di ReShade, Mod → ReShade).",
        ["{0}: RenoDX needs ReShade as a proxy dll."] = "{0}: RenoDX richiede ReShade come dll proxy.",
        ["{0}: Ultra+ is made for the game's own renderer."] = "{0}: Ultra+ è fatto per il renderer del gioco.",
        ["• Close the game before installing. Each mod's build is picked in its row; the newest stable one is picked first."] = "• Chiudi il gioco prima di installare. La build di ogni mod si sceglie nella sua riga; viene proposta prima l'ultima stabile.",
        ["• What you tick changes what the others can be: DLSS 5's F5 way needs janblade's F5 build of OptiScaler, DLSSNR-AMD a build without DLSS NR, and a Vulkan layer goes alone."] = "• Ciò che spunti cambia cosa possono essere le altre: il metodo F5 di DLSS 5 richiede la build F5 di OptiScaler di janblade, DLSSNR-AMD una build senza DLSS NR, e un layer Vulkan va da solo.",
        ["• Everything installed here is managed from its own place afterwards: OptiScaler in its tab, the other mods in Mods, Ultra+ in its tab."] = "• Tutto ciò che installi qui si gestisce poi dal suo posto: OptiScaler nella sua scheda, le altre mod in Mod, Ultra+ nella sua scheda.",
        ["Reading its list…"] = "Lettura della sua lista…",
        // 2.0.0-rc.18: OptiScaler builds added from the Auto tab.
        ["Add a build"] = "Aggiungi una build",
        ["From a GitHub fork…"] = "Da un fork su GitHub…",
        ["Import a build (a folder or an archive, e.g. one shared on Discord) or add a fork by its GitHub address, as on the OptiScaler tab"] = "Importa una build (una cartella o un archivio, ad es. una condivisa su Discord) o aggiungi un fork dal suo indirizzo GitHub, come nella scheda OptiScaler",
        // 2.0.0-rc.18: RenoDX mainly HDR, Luma not only HDR, generic mods flagged, match disclaimer.
        ["• What you tick changes what the others can be: DLSS 5's F5 method needs janblade's F5 build of OptiScaler, DLSSNR-AMD a build without DLSS NR. A Vulkan layer goes with the others, but some mods may not work through it."] = "• Ciò che spunti cambia cosa possono essere le altre: il metodo F5 di DLSS 5 richiede la build F5 di OptiScaler di janblade, DLSSNR-AMD una build senza DLSS NR. Un layer Vulkan va insieme alle altre, ma alcune mod potrebbero non funzionarci sopra.",
        ["• RenoDX is mainly for HDR; Luma reworks a game's rendering (upscaling, HDR, fixes, depending on the mod). Only one of them goes in. RenoDX needs ReShade's add-on build, which is picked for you; Luma brings its own ReShade. Without them the standard build is safer in online games."] = "• RenoDX serve soprattutto per l'HDR; Luma rielabora il rendering del gioco (upscaling, HDR, correzioni, a seconda della mod). Ne entra solo una delle due. RenoDX richiede la build add-on di ReShade, che viene scelta per te; Luma porta il suo ReShade. Senza di loro la build standard è più sicura nei giochi online.",
        ["• RenoDX and Luma mods are matched to the game by name, so a match can be wrong, and a generic mod (one for every game of an engine) may not work or may not be needed: check the mod in Mods → RenoDX or Mods → Luma before installing."] = "• Le mod RenoDX e Luma sono abbinate al gioco per nome, quindi l'abbinamento può essere sbagliato, e una mod generica (una per tutti i giochi di un motore) potrebbe non funzionare o non servire: controlla la mod in Mod → RenoDX o Mod → Luma prima di installare.",
        ["• Each Luma mod is made for one game (or, the generic ones, for one engine): it reworks the game's rendering, and what it adds depends on the mod (upscaling such as DLSS or FSR, HDR, fixes). A generic mod may not work in a game, or may not be needed."] = "• Ogni mod Luma è fatta per un gioco (o, quelle generiche, per un motore): rielabora il rendering del gioco, e ciò che aggiunge dipende dalla mod (upscaling come DLSS o FSR, HDR, correzioni). Una mod generica potrebbe non funzionare in un gioco, o non servire.",
        ["Luma Framework mods for DirectX 11 games: reworked rendering, such as upscaling, HDR and fixes"] = "Mod di Luma Framework per giochi DirectX 11: rendering rielaborato, come upscaling, HDR e correzioni",
        ["Mainly HDR mods for this game (ReShade add-ons)"] = "Mod soprattutto HDR per questo gioco (add-on di ReShade)",
        ["Luma: graphics mods for this game"] = "Luma: mod grafiche per questo gioco",
        ["A Luma mod is in: RenoDX is left out (they do not go together)."] = "C'è una mod Luma: RenoDX resta fuori (non vanno insieme).",
        ["A RenoDX mod is already in: Luma is left out (they do not go together)."] = "C'è già una mod RenoDX: Luma resta fuori (non vanno insieme).",
        ["GENERIC, not made for this game"] = "GENERICA, non fatta per questo gioco",
        ["GENERIC, tried with this game"] = "GENERICA, provata con questo gioco",
        ["Generic"] = "Generica",
        ["Generic mod for {0} games, not made for this one (its list says it was tried with it)."] = "Mod generica per i giochi {0}, non fatta per questo (la sua lista dice che è stata provata con questo).",
        ["Generic mod for {0} games, not made for this one: it may not work here or may not be needed."] = "Mod generica per i giochi {0}, non fatta per questo: potrebbe non funzionare qui o non servire.",
        ["Left out: Luma is ticked, and RenoDX and Luma do not go together."] = "Esclusa: Luma è spuntata, e RenoDX e Luma non vanno insieme.",
        ["Left out: RenoDX is ticked, and RenoDX and Luma do not go together."] = "Esclusa: RenoDX è spuntata, e RenoDX e Luma non vanno insieme.",
        ["Made for every {0} game, not for this one: it may not work here or may not be needed."] = "Fatta per tutti i giochi {0}, non per questo: potrebbe non funzionare qui o non servire.",
        ["Mainly an HDR mod (some also fix other things), and a display of this PC has HDR on."] = "Soprattutto una mod HDR (alcune correggono anche altro), e uno schermo di questo PC ha l'HDR attivo.",
        ["Mainly an HDR mod (some also fix other things): tick it if you play in HDR (no display of this PC has HDR on now)."] = "Soprattutto una mod HDR (alcune correggono anche altro): spuntala se giochi in HDR (ora nessuno schermo di questo PC ha l'HDR attivo).",
        ["Matched by name from the {0} list, so it may be wrong. Checking it in Mods → {0} first is recommended."] = "Abbinata per nome dalla lista di {0}, quindi può essere sbagliata. Controllarla prima in Mod → {0} è consigliato.",
        ["RenoDX and Luma both rework the image through ReShade: only one goes in. RenoDX is kept."] = "RenoDX e Luma rielaborano entrambe l'immagine tramite ReShade: ne entra solo una. Resta RenoDX.",
        ["Reworks the game's rendering; what it adds depends on the mod (upscaling, HDR, fixes). Mods → Luma lists what this one does."] = "Rielabora il rendering del gioco; ciò che aggiunge dipende dalla mod (upscaling, HDR, correzioni). Mod → Luma elenca cosa fa questa.",

        // ---- 2.1: themes, artwork, verify files, profiles ----
        ["Total Dark"] = "Nero totale",
        ["Gray"] = "Grigio",
        ["Pure black background, white accent. Best on OLED screens"] = "Sfondo nero puro, accento bianco. Ideale sugli schermi OLED",
        ["Soft near-black background, silver accent"] = "Sfondo quasi nero e morbido, accento argento",
        ["Graphite grey background, steel blue accent"] = "Sfondo grigio grafite, accento blu acciaio",
        ["Night crimson background, the logo's red accent"] = "Sfondo cremisi notturno, l'accento rosso del logo",
        ["Epic Games wants a confirmation"] = "Epic Games chiede una conferma",
        ["Epic asks you to confirm on its store page before Hybrid Launcher can read your Epic achievements. Settings → Achievements → Epic Games → Confirm on Epic."] = "Epic ti chiede una conferma sulla sua pagina dello store prima che Hybrid Launcher possa leggere i tuoi achievement Epic. Impostazioni → Achievement → Epic Games → Conferma su Epic.",
        ["Epic's store page. If Epic asks you to confirm, answer it here, then close this window: Hybrid Launcher reads your achievements again."] = "La pagina dello store di Epic. Se Epic chiede una conferma, rispondi qui e poi chiudi questa finestra: Hybrid Launcher rilegge i tuoi achievement.",
        ["Confirm on Epic"] = "Conferma su Epic",
        ["Epic Games check"] = "Controllo di Epic Games",
        ["Epic asks you to confirm on its store page first: Confirm on Epic, below."] = "Epic chiede prima una conferma sulla sua pagina dello store: Conferma su Epic, qui sotto.",
        ["Epic stopped answering until you confirm on its store page. Open it, answer what Epic asks, then close the window."] = "Epic ha smesso di rispondere finché non confermi sulla sua pagina dello store. Aprila, rispondi a ciò che chiede Epic, poi chiudi la finestra.",
        ["If Epic achievements stop showing, Epic may want you to confirm on its store page: open it here and answer what it asks."] = "Se gli achievement Epic non compaiono più, Epic potrebbe volere una conferma sulla sua pagina dello store: aprila qui e rispondi a ciò che chiede.",
        ["Your Windows accent colour on a dark window, your wallpaper's tone faintly behind it"] = "Il colore d'accento di Windows su una finestra scura, con il tono dello sfondo del desktop appena visibile",
        ["The window's background and accent colour together: Windows (your Windows accent), Total Dark, Dark, Gray or Hybrid."] = "Sfondo della finestra e colore d'accento insieme: Windows (l'accento di Windows), Nero totale, Scuro, Grigio o Hybrid.",
        ["The window's background and accent colour together: Total Dark, Dark, Gray or Hybrid."] = "Sfondo della finestra e colore d'accento insieme: Nero totale, Scuro, Grigio o Hybrid.",
        ["On: cards and outlines take a trace of the theme's accent. Off: neutral surfaces, only buttons and highlights in the accent colour."] = "Attivo: schede e contorni prendono una traccia dell'accento del tema. Disattivo: superfici neutre, solo pulsanti ed evidenziazioni nel colore d'accento.",
        ["Logo"] = "Logo",
        ["Icon"] = "Icona",
        ["The library tile (portrait, 2:3)"] = "La copertina in libreria (verticale, 2:3)",
        ["The wide picture at the top of the game's page"] = "L'immagine larga in cima alla pagina del gioco",
        ["The title drawn on the banner"] = "Il titolo disegnato sul banner",
        ["The small picture in the game list"] = "La piccola immagine nell'elenco dei giochi",
        ["Artwork"] = "Immagini",
