        ["Edit artwork…"] = "Modifica immagini…",
        ["Choose a file…"] = "Scegli un file…",
        ["Now: the store's."] = "Ora: quella dello store.",
        ["Now: your own pick."] = "Ora: scelta da te.",
        ["Your pick"] = "Scelta da te",
        ["{0} {1} is out"] = "{0} {1} è uscito",
        ["A new version of the build you follow."] = "Una nuova versione della build che segui.",
        ["Click to update it in {0}."] = "Clicca per aggiornarlo in {0}.",
        ["{0} OptiScaler updates"] = "{0} aggiornamenti di OptiScaler",
        ["Update it from {0}'s OptiScaler tab."] = "Aggiornalo dalla scheda OptiScaler di {0}.",
        ["Ultra+ {0} installed in {1}"] = "Ultra+ {0} installato in {1}",
        ["Updated by itself. Your settings were kept."] = "Aggiornato da solo. Le tue impostazioni sono rimaste.",
        ["Update it from the game's Ultra+ tab. Your settings stay."] = "Aggiornalo dalla scheda Ultra+ del gioco. Le tue impostazioni restano.",
        ["Click to update it. Your settings stay."] = "Clicca per aggiornarlo. Le tue impostazioni restano.",
        ["From the store"] = "Dallo store",
        ["From SteamGridDB"] = "Da SteamGridDB",
        ["Search another game"] = "Cerca un altro gioco",
        ["Pictures for {0}"] = "Immagini per {0}",
        ["STEAMGRIDDB"] = "STEAMGRIDDB",
        ["Not this game? Search SteamGridDB"] = "Non è questo gioco? Cerca su SteamGridDB",
        ["Paste your SteamGridDB API key"] = "Incolla la tua chiave API di SteamGridDB",
        ["Save key"] = "Salva chiave",
        ["Get a free key"] = "Ottieni una chiave gratuita",
        ["SteamGridDB shares thousands of covers, banners, logos and icons made by its community. It asks for a free API key of your own: sign in on steamgriddb.com, open Preferences → API, and paste the key here. It stays on this PC."] = "SteamGridDB condivide migliaia di copertine, banner, loghi e icone creati dalla sua community. Chiede una tua chiave API gratuita: accedi su steamgriddb.com, apri Preferences → API e incolla qui la chiave. Resta su questo PC.",
        ["Checking the key…"] = "Verifica della chiave…",
        ["SteamGridDB could not be reached: {0}"] = "Impossibile raggiungere SteamGridDB: {0}",
        ["SteamGridDB has no game by this name."] = "SteamGridDB non ha giochi con questo nome.",
        ["SteamGridDB has no game by this name. Search for it above."] = "SteamGridDB non ha giochi con questo nome. Cercalo qui sopra.",
        ["SteamGridDB refused the key. Check it and paste it again."] = "SteamGridDB ha rifiutato la chiave. Controllala e incollala di nuovo.",
        ["SteamGridDB refused the key. Paste it again."] = "SteamGridDB ha rifiutato la chiave. Incollala di nuovo.",
        ["No {0} for this game on SteamGridDB yet."] = "Ancora nessun elemento \"{0}\" per questo gioco su SteamGridDB.",
        ["The picture could not be downloaded: {0}"] = "Impossibile scaricare l'immagine: {0}",
        ["{0} × {1}, by {2}"] = "{0} × {1}, di {2}",
        ["The cover, banner, logo and icon come from the store. Pick others from SteamGridDB or your own pictures."] = "Copertina, banner, logo e icona vengono dallo store. Scegline altri da SteamGridDB o dalle tue immagini.",
        ["{0} picture of your own. Change them from SteamGridDB or your own files."] = "{0} immagine tua. Cambiale da SteamGridDB o dai tuoi file.",
        ["{0} pictures of your own. Change them from SteamGridDB or your own files."] = "{0} immagini tue. Cambiale da SteamGridDB o dai tuoi file.",
        ["Verify"] = "Verifica",
        ["Verify…"] = "Verifica…",
        ["Verify game files"] = "Verifica file di gioco",
        ["Verify game files…"] = "Verifica file di gioco…",
        ["Verify the files of {0}"] = "Verifica i file di {0}",
        ["Repair"] = "Riparazione",
        ["Mods in this game"] = "Mod in questo gioco",
        ["Installed here: {0}. A verify puts back any game file a mod replaced (a swapped DLSS or FSR dll, a patched exe); files a mod added are usually left alone. Check the mods' tabs afterwards."] = "Installate qui: {0}. Una verifica ripristina i file del gioco che una mod ha sostituito (una dll DLSS o FSR cambiata, un exe modificato); i file aggiunti da una mod di solito restano. Controlla poi le schede delle mod.",
        ["{0} checks every file of {1} against its own list and downloads again what is missing or damaged. It helps when the game crashes at start, after a failed update, or when a mod left it broken."] = "{0} controlla ogni file di {1} con la propria lista e riscarica ciò che manca o è danneggiato. Aiuta quando il gioco si chiude all'avvio, dopo un aggiornamento fallito o quando una mod lo ha lasciato rotto.",
        ["{0} checks the game's files and downloads again what is missing or damaged."] = "{0} controlla i file del gioco e riscarica ciò che manca o è danneggiato.",
        ["{0} could not be opened. Is it installed?"] = "Impossibile aprire {0}. È installato?",
        ["{0} has no direct link for this: Hybrid Launcher opens it, then:"] = "{0} non ha un collegamento diretto per questo: Hybrid Launcher lo apre, poi:",
        ["{0} is checking the files of {1}."] = "{0} sta verificando i file di {1}.",
        ["No launcher keeps a list of this game's files."] = "Nessun launcher tiene una lista dei file di questo gioco.",
        ["Hybrid Launcher downloaded this game itself, so no launcher keeps a list of its files to check them against. Download it again to repair it."] = "Hybrid Launcher ha scaricato questo gioco da sé, quindi nessun launcher tiene una lista dei suoi file con cui confrontarli. Scaricalo di nuovo per ripararlo.",
        ["This game was not installed by a launcher Hybrid Launcher knows, so nothing can check its files. Reinstall it to repair it."] = "Questo gioco non è stato installato da un launcher che Hybrid Launcher conosce, quindi nulla può controllarne i file. Reinstallalo per ripararlo.",
        ["In the Library, click ⋯ on the game → Manage → Verify."] = "Nella Libreria, fai clic su ⋯ sul gioco → Gestisci → Verifica.",
        ["On the game's page in GOG Galaxy, click the settings icon beside Play → Manage installation → Verify / Repair."] = "Nella pagina del gioco in GOG Galaxy, fai clic sull'icona delle impostazioni accanto a Gioca → Gestisci installazione → Verifica / Ripara.",
        ["In Ubisoft Connect open Games, pick the game → Properties → Verify files."] = "In Ubisoft Connect apri Giochi, scegli il gioco → Proprietà → Verifica file.",
        ["In the EA app open Library, click ⋯ on the game → Repair."] = "Nell'app EA apri la Libreria, fai clic su ⋯ sul gioco → Ripara.",
        ["In the Xbox app open the game's page, click ⋯ → Manage → Files → Verify and repair."] = "Nell'app Xbox apri la pagina del gioco, fai clic su ⋯ → Gestisci → File → Verifica e ripara.",
        ["In the Rockstar Games Launcher open Settings → My installed games → the game → Verify integrity."] = "Nel Rockstar Games Launcher apri Impostazioni → I miei giochi installati → il gioco → Verifica integrità.",
        ["Rare: fewer than 10% of players have them"] = "Rari: li ha meno del 10% dei giocatori",
        ["Uncommon: 10 to 30% of players have them"] = "Non comuni: li ha dal 10 al 30% dei giocatori",
        ["Common: 30% of players or more have them"] = "Comuni: li ha il 30% dei giocatori o più",
        ["Create your profile"] = "Crea il tuo profilo",
        ["Add your name and picture"] = "Aggiungi nome e immagine",
        ["Your dashboard"] = "La tua dashboard",
