        // 2.1-rc.3
        ["All launchers"] = "Tutti i launcher",
        ["Checking files ({0} of {1})"] = "Controllo dei file ({0} di {1})",
        ["Checking the files of {0}: follow it in Downloads."] = "Controllo dei file di {0}: segui l'avanzamento in Download.",
        ["Close {0} first: its files are in use."] = "Chiudi prima {0}: i suoi file sono in uso.",
        ["Hybrid Launcher checks every file of {0} against {1}'s list for its current version and downloads again what is missing or damaged, without opening {1}. It helps when the game crashes at start, after a failed update, or when a mod left it broken."] = "Hybrid Launcher controlla ogni file di {0} con l'elenco di {1} per la versione attuale e riscarica quelli mancanti o danneggiati, senza aprire {1}. Serve quando il gioco si chiude all'avvio, dopo un aggiornamento fallito o quando una mod l'ha lasciato rotto.",
        ["Installed games only"] = "Solo i giochi installati",
        ["Installing"] = "Installazione",
        ["Launchers"] = "Launcher",
        ["No games yet"] = "Ancora nessun gioco",
        ["Open Downloads"] = "Apri Download",
