        ["Repairing"] = "Riparazione",
        ["Sign in to see your Xbox achievements"] = "Accedi per vedere i tuoi obiettivi Xbox",
        ["Sign in to see your whole library"] = "Accedi per vedere tutta la tua libreria",
        ["Signed in to {0} in Downloads → Accounts, Hybrid Launcher verifies the game itself, with no launcher."] = "Con l'accesso a {0} in Download → Account, Hybrid Launcher verifica il gioco da solo, senza launcher.",
        ["Sort by"] = "Ordina per",
        ["Starting… (click to stop it)"] = "Avvio… (clic per fermarlo)",
        ["The check reads the whole game, which takes a few minutes on a big one. Follow it in Downloads; the game cannot start until it is done."] = "Il controllo legge tutto il gioco: su uno grande ci vuole qualche minuto. Seguilo in Download; il gioco non si avvia finché non ha finito.",
        ["Use {0}"] = "Usa {0}",
        ["Verified: every file is fine"] = "Verificato: tutti i file sono a posto",
        ["Verified: {0} file repaired"] = "Verificato: {0} file riparato",
        ["Verified: {0} files repaired"] = "Verificato: {0} file riparati",
        ["Which launchers' games are listed"] = "Di quali launcher mostrare i giochi",
        ["{0} games, {1} installed"] = "{0} giochi, {1} installati",
        ["{0} is running: click to close it"] = "{0} è in esecuzione: clic per chiuderlo",
        ["{0} launcher"] = "{0} launcher",
