        // 2.1-rc.4
        ["From {0}: {1:0.#} hours"] = "Da {0}: {1:0.#} ore",
        // 2.1-rc.6
        ["Every mod Hybrid Launcher installed is out, and the game's files are back."] = "Tutte le mod installate da Hybrid Launcher sono state tolte e i file del gioco sono tornati.",
        ["Left as they are (not installed by Hybrid Launcher): {0}."] = "Restano dove sono (non installate da Hybrid Launcher): {0}.",
        ["No mod here was installed by Hybrid Launcher: the ones in the folder were put in another way, so they stay."] = "Nessuna mod qui è stata installata da Hybrid Launcher: quelle nella cartella sono state messe in altro modo, quindi restano.",
        ["Still in the game: {0}. Uninstall it from its section."] = "Ancora nel gioco: {0}. Disinstallala dalla sua sezione.",
        ["Takes out every mod Hybrid Launcher installed here; mods put in another way stay"] = "Toglie tutte le mod installate qui da Hybrid Launcher; quelle messe in altro modo restano",
        ["Takes out {0} and puts back every game file they replaced."] = "Toglie {0} e rimette ogni file del gioco che avevano sostituito.",
        ["Uninstall 1 mod?"] = "Disinstallare 1 mod?",
        ["Uninstall all"] = "Disinstalla tutto",
        ["Uninstall {0} mods?"] = "Disinstallare {0} mod?",
